-- BEGIN db/schema/20_functions/00_per_tooth_rpc_cutover.sql
-- Changed return records cannot be replaced in place. Remove only known obsolete
-- contracts; the definitions and grants below recreate the current API.
DO $$
DECLARE f record;
BEGIN
    FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p
        JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'
        AND (
            (p.proname IN ('get_my_work_orders','get_my_work_orders_v188','get_my_production','get_patient_case')
             AND pg_get_function_result(p.oid) ~ '\m(tip_lucrare|nr_elemente|material)\M')
            OR (p.proname IN ('get_my_work_orders','get_my_work_orders_v188')
                AND pg_get_function_result(p.oid) NOT LIKE '%cost_model numeric%')
            OR (p.proname IN ('create_work_order','create_technician_work_order','update_doctor_work_order',
                'update_management_work_order','update_management_work_order_v188','save_my_work_order_case','upsert_patient_case')
                AND p.proargnames && ARRAY['p_tip_lucrare','p_nr_elemente','p_material'])
            OR (p.proname='estimate_doctor_work_order_price' AND p.proargnames @> ARRAY['p_elements'])
        ) ORDER BY CASE WHEN p.proname='get_my_work_orders_v188' THEN 0 ELSE 1 END
    LOOP EXECUTE format('DROP FUNCTION %s',f.signature); END LOOP;
END $$;
-- END db/schema/20_functions/00_per_tooth_rpc_cutover.sql

-- BEGIN db/schema/20_functions/adjust_material_quantity.sql
CREATE OR REPLACE FUNCTION public.adjust_material_quantity(
    p_lab_organization_id uuid,p_material_id bigint,p_mode text,p_value numeric,
    p_expected_quantity numeric DEFAULT NULL,p_request_key text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_role text:=public.effective_lab_role(p_lab_organization_id); v_mode text:=lower(trim(p_mode));
    v_material public.lab_materials_inventory%rowtype; v_new numeric(14,3);
    v_hash text; v_request public.ai_operation_requests%rowtype; v_result jsonb;
BEGIN
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'Material quantity update denied'; END IF;
    IF v_mode NOT IN ('set','add','subtract') THEN RAISE EXCEPTION 'Material mode must be set, add or subtract'; END IF;
    IF p_value IS NULL OR p_value<0 THEN RAISE EXCEPTION 'Quantity value must be zero or greater'; END IF;
    IF v_mode='set' AND nullif(trim(coalesce(p_request_key,'')),'') IS NOT NULL
       AND p_expected_quantity IS NULL THEN
        RAISE EXCEPTION 'Expected quantity is required for an idempotent set';
    END IF;

    IF nullif(trim(coalesce(p_request_key,'')),'') IS NOT NULL THEN
        v_hash:=md5(jsonb_build_object('material_id',p_material_id,'mode',v_mode,'value',p_value,'expected',p_expected_quantity)::text);
        INSERT INTO public.ai_operation_requests(lab_organization_id,request_key,requested_by_user_id,envelope_hash)
        VALUES(p_lab_organization_id,p_request_key,auth.uid(),v_hash) ON CONFLICT DO NOTHING;
        SELECT * INTO v_request FROM public.ai_operation_requests
        WHERE lab_organization_id=p_lab_organization_id AND request_key=p_request_key FOR UPDATE;
        IF v_request.requested_by_user_id<>auth.uid() THEN RAISE EXCEPTION 'Request key belongs to another user'; END IF;
        IF v_request.envelope_hash<>v_hash THEN RAISE EXCEPTION 'Request key was already used for another operation'; END IF;
        IF v_request.state='completed' THEN RETURN v_request.result; END IF;
    END IF;

    SELECT * INTO v_material FROM public.lab_materials_inventory
    WHERE lab_organization_id=p_lab_organization_id AND id=p_material_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Material not found'; END IF;
    IF v_mode='set' AND p_expected_quantity IS NOT NULL AND v_material.cantitate<>p_expected_quantity THEN RAISE EXCEPTION 'Material quantity changed; reload before setting it'; END IF;
    v_new:=round(case v_mode when 'set' then p_value when 'add' then v_material.cantitate+p_value else v_material.cantitate-p_value end,3);
    IF v_new<0 THEN RAISE EXCEPTION 'Material quantity cannot become negative'; END IF;
    UPDATE public.lab_materials_inventory SET cantitate=v_new,ultima_actualizare=now(),
        updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
    WHERE lab_organization_id=p_lab_organization_id AND id=p_material_id;
    v_result:=jsonb_build_object('ok',true,'entity','material','operation',v_mode,'material_id',p_material_id,
        'material',v_material.material,'unit',v_material.um,'old_quantity',v_material.cantitate,'new_quantity',v_new,'request_key',p_request_key);
    IF nullif(trim(coalesce(p_request_key,'')),'') IS NOT NULL THEN
        UPDATE public.ai_operation_requests SET state='completed',result=v_result,completed_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND request_key=p_request_key;
    END IF;
    RETURN v_result;
END; $$;
REVOKE ALL ON FUNCTION public.adjust_material_quantity(uuid,bigint,text,numeric,numeric,text) FROM public;
GRANT EXECUTE ON FUNCTION public.adjust_material_quantity(uuid,bigint,text,numeric,numeric,text) TO authenticated;
-- END db/schema/20_functions/adjust_material_quantity.sql

-- BEGIN db/schema/20_functions/adjust_work_order_scope_costs.sql
CREATE OR REPLACE FUNCTION public.adjust_work_order_scope_costs(p_lab uuid,p_order bigint,p_before jsonb,p_after jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE a public.lab_work_order_stage_assignments%rowtype; d record; v_cost numeric; v_source text; v_existing boolean;
BEGIN
    IF p_before IS NOT DISTINCT FROM p_after THEN RETURN; END IF;
    FOR a IN SELECT * FROM public.lab_work_order_stage_assignments
        WHERE lab_organization_id=p_lab AND work_order_id=p_order AND ended_at IS NULL FOR UPDATE
    LOOP
        FOR d IN
            WITH before_scope AS (SELECT x->>'work_type' work_type,(x->>'quantity')::numeric quantity FROM jsonb_array_elements(p_before) x),
            after_scope AS (SELECT x->>'work_type' work_type,(x->>'quantity')::numeric quantity FROM jsonb_array_elements(p_after) x)
            SELECT coalesce(n.work_type,o.work_type) work_type,coalesce(n.quantity,0)-coalesce(o.quantity,0) delta
            FROM before_scope o FULL JOIN after_scope n USING(work_type)
            WHERE coalesce(n.quantity,0)<>coalesce(o.quantity,0)
        LOOP
            -- Existing work types retain their original frozen cost, including missing costs.
            SELECT l.unit_cost,l.cost_source INTO v_cost,v_source FROM public.lab_work_order_assignment_cost_lines l
            WHERE l.assignment_id=a.id AND lower(trim(l.work_type))=lower(trim(d.work_type));
            v_existing:=FOUND;
            IF NOT v_existing THEN
                SELECT l.unit_cost,l.cost_source INTO v_cost,v_source FROM public.lab_work_order_assignment_adjustments l
                WHERE l.assignment_id=a.id AND lower(trim(l.work_type))=lower(trim(d.work_type)) ORDER BY l.created_at,l.id LIMIT 1;
                v_existing:=FOUND;
            END IF;
            IF NOT v_existing THEN
                v_cost:=public.resolve_technician_unit_cost(
                    p_lab,a.technician_name,d.work_type,a.stage_key
                );
                v_source:=CASE WHEN v_cost IS NULL THEN 'missing' ELSE 'catalog' END;
            END IF;
            IF v_cost IS NULL THEN
                RAISE EXCEPTION 'Missing technician cost configuration: % / % / %',
                    a.technician_name,d.work_type,a.stage_key;
            END IF;
            INSERT INTO public.lab_work_order_assignment_adjustments(assignment_id,work_type,quantity_delta,unit_cost,amount,cost_source,created_by_user_id)
            VALUES(a.id,d.work_type,d.delta,v_cost,round(v_cost*d.delta,2),coalesce(v_source,'missing'),auth.uid());
        END LOOP;
        INSERT INTO public.work_order_financial_audit(lab_organization_id,work_order_id,entity_type,entity_id,action,before_value,after_value,changed_by_user_id)
        VALUES(p_lab,p_order,'stage_assignment',a.id::text,'scope_adjustment',p_before,
            jsonb_build_object('scope',p_after,'agreed_amount',public.assignment_agreed_amount(a.id)),auth.uid());
    END LOOP;
END; $$;
REVOKE ALL ON FUNCTION public.adjust_work_order_scope_costs(uuid,bigint,jsonb,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/adjust_work_order_scope_costs.sql

-- BEGIN db/schema/20_functions/admin_bulk_config_import.sql
-- Flowrise Supabase function: public.admin_bulk_config_import(p_kind text, p_mode text, p_rows jsonb)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.admin_bulk_config_import(p_kind text, p_mode text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_kind text := lower(trim(coalesce(p_kind,'')));
    v_mode text := upper(trim(coalesce(p_mode,'')));
    v_count integer := 0;
    v_row jsonb;
    v_id_text text;
    v_id_big bigint;
    v_source_row integer;
    v_contract text;
    v_work_type text;
    v_technician text;
    v_stage text;
    v_price numeric;
    v_cost numeric;
    v_active boolean;
    v_next_work_type bigint;
    v_next_cost_row integer;
begin
    if not public.is_lab_management(v_lab)
       or lower(coalesce(public.current_org_role(v_lab),'')) <> 'admin' then
        raise exception 'Admin access required';
    end if;

    if v_kind not in ('prices','types','costs') then
        raise exception 'Invalid import section';
    end if;

    if v_mode not in ('MERGE','REPLACE') then
        raise exception 'Invalid import mode';
    end if;

    if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
        raise exception 'CSV contains no rows';
    end if;

    if jsonb_array_length(p_rows) > 10000 then
        raise exception 'Maximum 10000 rows per import';
    end if;

    if v_kind = 'prices' then
        -- Validate the entire payload BEFORE a REPLACE delete.
        for v_row in select * from jsonb_array_elements(p_rows)
        loop
            v_contract := trim(coalesce(v_row->>'contract',''));
            v_work_type := trim(coalesce(v_row->>'tip_lucrare',''));

            begin
                v_price := nullif(trim(coalesce(v_row->>'pret','')),'')::numeric;
            exception when others then
                raise exception 'Invalid Pret value: %', coalesce(v_row->>'pret','');
            end;

            if v_contract = '' or v_work_type = '' or v_price is null or v_price < 0 then
                raise exception 'Each price row requires Contract, Tip_Lucrare and a non-negative Pret';
            end if;
        end loop;

        if v_mode = 'REPLACE' then
            delete from public.lab_contract_work_prices
            where lab_organization_id = v_lab;
        end if;

        for v_row in select * from jsonb_array_elements(p_rows)
        loop
            v_id_text := nullif(trim(coalesce(v_row->>'id','')),'');
            if v_id_text is null then
                v_id_text := 'price_' || gen_random_uuid()::text;
            end if;

            insert into public.lab_contract_work_prices (
                lab_organization_id,
                id,
                contract,
                tip_lucrare,
                pret,
                updated_at
            )
            values (
                v_lab,
                v_id_text,
                trim(v_row->>'contract'),
                trim(v_row->>'tip_lucrare'),
                (v_row->>'pret')::numeric,
                now()
            )
            on conflict (lab_organization_id,id)
            do update set
                contract = excluded.contract,
                tip_lucrare = excluded.tip_lucrare,
                pret = excluded.pret,
                updated_at = now();

            v_count := v_count + 1;
        end loop;

    elsif v_kind = 'types' then
        select coalesce(max(id),0) + 1
          into v_next_work_type
        from public.lab_work_types
        where lab_organization_id = v_lab;

        -- Validate first.
        for v_row in select * from jsonb_array_elements(p_rows)
        loop
            v_work_type := trim(coalesce(v_row->>'tip_lucrare',''));
            if v_work_type = '' then
                raise exception 'Each work type row requires Tip_Lucrare';
            end if;

            if nullif(trim(coalesce(v_row->>'id','')),'') is not null then
                begin
                    perform (v_row->>'id')::bigint;
                exception when others then
                    raise exception 'Invalid work type ID: %', v_row->>'id';
                end;
            end if;
        end loop;

        if v_mode = 'REPLACE' then
            delete from public.lab_work_types
            where lab_organization_id = v_lab;

            -- Start generated IDs after the largest explicitly supplied ID.
            select greatest(
                coalesce(max((x->>'id')::bigint) filter (
                    where nullif(trim(coalesce(x->>'id','')),'') is not null
                ),0),
                0
            ) + 1
            into v_next_work_type
            from jsonb_array_elements(p_rows) x;
        end if;

        for v_row in select * from jsonb_array_elements(p_rows)
        loop
            if nullif(trim(coalesce(v_row->>'id','')),'') is null then
                v_id_big := v_next_work_type;
                v_next_work_type := v_next_work_type + 1;
            else
                v_id_big := (v_row->>'id')::bigint;
            end if;

            v_active := case
                when lower(trim(coalesce(v_row->>'active','true')))
                     in ('false','0','no','inactive','nu') then false
                else true
            end;

            insert into public.lab_work_types (
                lab_organization_id,
                id,
                tip_lucrare,
                active,
                updated_at
            )
            values (
                v_lab,
                v_id_big,
                trim(v_row->>'tip_lucrare'),
                v_active,
                now()
            )
            on conflict (lab_organization_id,id)
            do update set
                tip_lucrare = excluded.tip_lucrare,
                active = excluded.active,
                updated_at = now();

            v_count := v_count + 1;
        end loop;

    else
        select coalesce(max(source_row_no),0) + 1
          into v_next_cost_row
        from public.lab_technician_costs
        where lab_organization_id = v_lab;

        -- Validate first.
        for v_row in select * from jsonb_array_elements(p_rows)
        loop
            v_technician := trim(coalesce(v_row->>'tehnician',''));
            v_work_type := trim(coalesce(v_row->>'tip_lucrare',''));
            v_stage := trim(coalesce(v_row->>'etapa',''));

            if v_technician = '' or v_work_type = '' or v_stage = '' then
                raise exception 'Each technician cost row requires Tehnician, Tip_Lucrare and Etapa';
            end if;

            if nullif(trim(coalesce(v_row->>'source_row_no','')),'') is not null then
                begin
                    perform (v_row->>'source_row_no')::integer;
                exception when others then
                    raise exception 'Invalid Source_Row_No: %', v_row->>'source_row_no';
                end;
            end if;

            if nullif(trim(coalesce(v_row->>'cost','')),'') is not null then
                begin
                    v_cost := (v_row->>'cost')::numeric;
                exception when others then
                    raise exception 'Invalid Cost: %', v_row->>'cost';
                end;
                if v_cost < 0 then
                    raise exception 'Cost cannot be negative';
                end if;
            end if;
        end loop;

        if v_mode = 'REPLACE' then
            delete from public.lab_technician_costs
            where lab_organization_id = v_lab;

            select greatest(
                coalesce(max((x->>'source_row_no')::integer) filter (
                    where nullif(trim(coalesce(x->>'source_row_no','')),'') is not null
                ),0),
                0
            ) + 1
            into v_next_cost_row
            from jsonb_array_elements(p_rows) x;
        end if;

        for v_row in select * from jsonb_array_elements(p_rows)
        loop
            if nullif(trim(coalesce(v_row->>'source_row_no','')),'') is null then
                v_source_row := v_next_cost_row;
                v_next_cost_row := v_next_cost_row + 1;
            else
                v_source_row := (v_row->>'source_row_no')::integer;
            end if;

            v_id_text := nullif(trim(coalesce(v_row->>'legacy_id','')),'');
            if v_id_text is null then
                v_id_text := 'cost_' || gen_random_uuid()::text;
            end if;

            if nullif(trim(coalesce(v_row->>'cost','')),'') is null then
                v_cost := null;
            else
                v_cost := (v_row->>'cost')::numeric;
            end if;

            insert into public.lab_technician_costs (
                lab_organization_id,
                source_row_no,
                legacy_id,
                tehnician,
                tip_lucrare,
                etapa,
                cost,
                updated_at
            )
            values (
                v_lab,
                v_source_row,
                v_id_text,
                trim(v_row->>'tehnician'),
                trim(v_row->>'tip_lucrare'),
                trim(v_row->>'etapa'),
                v_cost,
                now()
            )
            on conflict (lab_organization_id,source_row_no)
            do update set
                legacy_id = excluded.legacy_id,
                tehnician = excluded.tehnician,
                tip_lucrare = excluded.tip_lucrare,
                etapa = excluded.etapa,
                cost = excluded.cost,
                updated_at = now();

            v_count := v_count + 1;
        end loop;
    end if;

    return jsonb_build_object(
        'ok', true,
        'kind', v_kind,
        'mode', v_mode,
        'imported_rows', v_count
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_kind text, p_mode text, p_rows jsonb
-- END db/schema/20_functions/admin_bulk_config_import.sql

-- BEGIN db/schema/20_functions/admin_clear_ai_history_older_than_30_days.sql
-- Flowrise Supabase function: public.admin_clear_ai_history_older_than_30_days
-- Sourced from Flowrise-Dental-V18.24-Cleanup-RPC.sql.
-- Includes the complete function definition and available ACL statements.

create or replace function public.admin_clear_ai_history_older_than_30_days(
    p_lab_organization_id uuid,
    p_days integer default 30
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_deleted bigint := 0;
    v_days integer := greatest(coalesce(p_days,30),30);
begin
    if not public.is_lab_management(p_lab_organization_id) then
        raise exception 'Management access denied';
    end if;

    with deleted as (
        delete from public.lab_chat_history
        where lab_organization_id = p_lab_organization_id
          and created_at < now() - make_interval(days => v_days)
        returning 1
    )
    select count(*) into v_deleted from deleted;

    return jsonb_build_object(
        'ok', true,
        'deleted_messages', v_deleted,
        'cutoff_days', v_days
    );
end;
$$;

revoke all on function public.admin_clear_ai_history_older_than_30_days(uuid,integer) from public;
grant execute on function public.admin_clear_ai_history_older_than_30_days(uuid,integer) to authenticated;
