-- BEGIN db/schema/20_functions/admin_clear_chat_messages_older_than_30_days.sql
-- Flowrise Supabase function: public.admin_clear_chat_messages_older_than_30_days
-- Sourced from Flowrise-Dental-V18.24-Cleanup-RPC.sql.
-- Includes the complete function definition and available ACL statements.

create or replace function public.admin_clear_chat_messages_older_than_30_days(
    p_lab_organization_id uuid,
    p_days integer default 30
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_deleted_messages bigint := 0;
    v_deleted_files bigint := 0;
    v_days integer := greatest(coalesce(p_days,30),30);
begin
    if not public.is_lab_management(p_lab_organization_id) then
        raise exception 'Management access denied';
    end if;

    -- The internal chat is shared by authenticated lab users and does not carry
    -- a lab id on each thread. The management role check scopes this operation
    -- to the currently configured Flowrise lab while cleaning all old chat rows.
    select count(*)
      into v_deleted_files
    from public.chat_attachments a
    join public.chat_messages m on m.id = a.message_id
    where m.created_at < now() - make_interval(days => v_days)
      and exists (
          select 1
          from public.chat_thread_participants tp
          join public.organization_memberships om on om.user_id = tp.user_id
          where tp.thread_id = m.thread_id
            and om.organization_id = p_lab_organization_id
            and om.status = 'active'::public.membership_status
      );

    -- Remove the matching Storage objects as part of the same server-side action.
    delete from storage.objects o
    using public.chat_attachments a
    join public.chat_messages m on m.id = a.message_id
    where o.bucket_id = 'chat-files'
      and o.name = a.storage_path
      and m.created_at < now() - make_interval(days => v_days)
      and exists (
          select 1
          from public.chat_thread_participants tp
          join public.organization_memberships om on om.user_id = tp.user_id
          where tp.thread_id = m.thread_id
            and om.organization_id = p_lab_organization_id
            and om.status = 'active'::public.membership_status
      );

    -- Remove metadata first, then the old messages.
    delete from public.chat_attachments a
    using public.chat_messages m
    where m.id = a.message_id
      and m.created_at < now() - make_interval(days => v_days)
      and exists (
          select 1
          from public.chat_thread_participants tp
          join public.organization_memberships om on om.user_id = tp.user_id
          where tp.thread_id = m.thread_id
            and om.organization_id = p_lab_organization_id
            and om.status = 'active'::public.membership_status
      );

    with deleted as (
        delete from public.chat_messages cm
        where cm.created_at < now() - make_interval(days => v_days)
          and exists (
              select 1
              from public.chat_thread_participants tp
              join public.organization_memberships om on om.user_id = tp.user_id
              where tp.thread_id = cm.thread_id
                and om.organization_id = p_lab_organization_id
                and om.status = 'active'::public.membership_status
          )
        returning 1
    )
    select count(*) into v_deleted_messages from deleted;

    update public.chat_threads t
    set last_message_at = (
        select max(m.created_at)
        from public.chat_messages m
        where m.thread_id = t.id
    );

    return jsonb_build_object(
        'ok', true,
        'deleted_messages', v_deleted_messages,
        'deleted_files', v_deleted_files,
        'cutoff_days', v_days
    );
end;
$$;

revoke all on function public.admin_clear_chat_messages_older_than_30_days(uuid,integer) from public;
grant execute on function public.admin_clear_chat_messages_older_than_30_days(uuid,integer) to authenticated;
-- END db/schema/20_functions/admin_clear_chat_messages_older_than_30_days.sql

-- BEGIN db/schema/20_functions/ai_admin_config_operation.sql
CREATE OR REPLACE FUNCTION public.ai_admin_config_operation(
    p_entity text,p_operation text,p_target jsonb,p_fields jsonb
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_entity text:=lower(trim(p_entity)); v_op text:=lower(trim(p_operation));
    v_count integer:=0; v_id bigint;
BEGIN
    IF lower(coalesce(public.current_org_role(v_lab),''))<>'admin' THEN RAISE EXCEPTION 'Admin access required'; END IF;
    IF v_entity<>'work_type' THEN RAISE EXCEPTION 'Unsupported configuration entity'; END IF;
    IF v_op='create' THEN
        IF trim(coalesce(p_fields->>'work_type',''))='' THEN RAISE EXCEPTION 'Work type is required'; END IF;
        PERFORM pg_advisory_xact_lock(hashtext(v_lab::text||':work_type'));
        SELECT coalesce(max(id),0)+1 INTO v_id FROM public.lab_work_types WHERE lab_organization_id=v_lab;
        INSERT INTO public.lab_work_types(lab_organization_id,id,tip_lucrare,active,updated_at)
        VALUES(v_lab,v_id,trim(p_fields->>'work_type'),coalesce((p_fields->>'active')::boolean,true),now()); v_count:=1;
    ELSIF v_op='update' THEN
        UPDATE public.lab_work_types SET
            tip_lucrare=coalesce(nullif(trim(p_fields->>'work_type'),''),tip_lucrare),
            active=case when p_fields?'active' then (p_fields->>'active')::boolean else active end,updated_at=now()
        WHERE lab_organization_id=v_lab AND id=(p_target->>'id')::bigint; GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSIF v_op='delete' THEN
        DELETE FROM public.lab_work_types WHERE lab_organization_id=v_lab AND id=(p_target->>'id')::bigint; GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSE RAISE EXCEPTION 'Unsupported work type operation'; END IF;
    IF v_count=0 THEN RAISE EXCEPTION 'Work type target not found'; END IF;
    RETURN jsonb_build_object('ok',true,'entity',v_entity,'operation',v_op,'count',v_count,'ids',case when v_id is null then jsonb_build_array(p_target->'id') else jsonb_build_array(v_id) end);
END; $$;
REVOKE ALL ON FUNCTION public.ai_admin_config_operation(text,text,jsonb,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_admin_config_operation.sql

-- BEGIN db/schema/20_functions/ai_admin_price_operation.sql
CREATE OR REPLACE FUNCTION public.ai_admin_price_operation(
    p_entity text,p_operation text,p_target jsonb,p_fields jsonb
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_entity text:=lower(trim(p_entity)); v_op text:=lower(trim(p_operation));
    v_count integer:=0; v_source text; v_destination text; v_mode text; v_id text;
BEGIN
    IF lower(coalesce(public.current_org_role(v_lab),''))<>'admin' THEN RAISE EXCEPTION 'Admin access required'; END IF;
    IF v_entity='work_order_price' AND v_op='set' THEN
        IF NOT (p_fields?'unit_price') OR NOT (p_fields?'discount') OR trim(coalesce(p_fields->>'reason',''))='' THEN
            RAISE EXCEPTION 'Unit price, discount and reason are required';
        END IF;
        RETURN jsonb_build_object('ok',true,'entity',v_entity,'operation',v_op,'count',1,'values',
            public.set_work_order_price_snapshot(v_lab,(p_target->>'id')::bigint,(p_fields->>'unit_price')::numeric,
                coalesce((p_fields->>'discount')::numeric,0),p_fields->>'reason'));
    END IF;
    IF v_entity<>'contract_price' THEN RAISE EXCEPTION 'Unsupported price entity'; END IF;
    PERFORM pg_advisory_xact_lock(hashtext(v_lab::text||':contract_price'));

    IF v_op='duplicate' THEN
        v_source:=trim(coalesce(p_fields->>'source_contract',p_target->>'source_contract',''));
        v_destination:=trim(coalesce(p_fields->>'target_contract',p_target->>'target_contract',''));
        v_mode:=lower(trim(coalesce(p_fields->>'conflict_mode','')));
        IF v_source='' OR v_destination='' OR lower(v_source)=lower(v_destination) THEN RAISE EXCEPTION 'Distinct source and target contracts are required'; END IF;
        IF NOT EXISTS (SELECT 1 FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab AND lower(trim(contract))=lower(v_source)) THEN RAISE EXCEPTION 'Source contract prices not found'; END IF;
        IF EXISTS (SELECT 1 FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab AND lower(trim(contract))=lower(v_destination)) THEN
            IF v_mode NOT IN ('append','replace') THEN RAISE EXCEPTION 'Target contract already has prices; choose append or replace'; END IF;
            IF v_mode='replace' THEN DELETE FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab AND lower(trim(contract))=lower(v_destination); END IF;
        END IF;
        INSERT INTO public.lab_contract_work_prices(lab_organization_id,id,contract,tip_lucrare,pret,updated_at)
        SELECT v_lab,'price_'||gen_random_uuid()::text,v_destination,tip_lucrare,pret,now()
        FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab AND lower(trim(contract))=lower(v_source);
        GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSIF v_op='create' THEN
        IF trim(coalesce(p_fields->>'contract',''))='' OR trim(coalesce(p_fields->>'work_type',''))='' OR NOT (p_fields?'price') THEN RAISE EXCEPTION 'Contract, work type and price are required'; END IF;
        IF (p_fields->>'price')::numeric<0 THEN RAISE EXCEPTION 'Price cannot be negative'; END IF;
        v_id:=coalesce(nullif(trim(p_fields->>'id'),''),'price_'||gen_random_uuid()::text);
        INSERT INTO public.lab_contract_work_prices(lab_organization_id,id,contract,tip_lucrare,pret,updated_at)
        VALUES(v_lab,v_id,trim(p_fields->>'contract'),trim(p_fields->>'work_type'),(p_fields->>'price')::numeric,now()); v_count:=1;
    ELSIF v_op='update' THEN
        IF p_fields?'price' AND (p_fields->>'price')::numeric<0 THEN RAISE EXCEPTION 'Price cannot be negative'; END IF;
        UPDATE public.lab_contract_work_prices SET
            contract=coalesce(nullif(trim(p_fields->>'contract'),''),contract),
            tip_lucrare=coalesce(nullif(trim(p_fields->>'work_type'),''),tip_lucrare),
            pret=case when p_fields?'price' then (p_fields->>'price')::numeric else pret end,updated_at=now()
        WHERE lab_organization_id=v_lab AND id=p_target->>'id'; GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSIF v_op='delete' THEN
        DELETE FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab AND id=p_target->>'id'; GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSE RAISE EXCEPTION 'Unsupported contract price operation'; END IF;
    IF v_count=0 THEN RAISE EXCEPTION 'Contract price target not found'; END IF;
    RETURN jsonb_build_object('ok',true,'entity',v_entity,'operation',v_op,'count',v_count);
END; $$;
REVOKE ALL ON FUNCTION public.ai_admin_price_operation(text,text,jsonb,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_admin_price_operation.sql

-- BEGIN db/schema/20_functions/ai_admin_technician_cost_operation.sql
CREATE OR REPLACE FUNCTION public.ai_admin_technician_cost_operation(
    p_operation text,p_target jsonb,p_fields jsonb
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_op text:=lower(trim(p_operation));
    v_source text; v_destination text; v_mode text; v_count integer:=0; v_next integer;
BEGIN
    IF lower(coalesce(public.current_org_role(v_lab),''))<>'admin' THEN RAISE EXCEPTION 'Admin access required'; END IF;
    PERFORM pg_advisory_xact_lock(hashtext(v_lab::text||':technician_cost'));
    SELECT coalesce(max(source_row_no),0)+1 INTO v_next FROM public.lab_technician_costs WHERE lab_organization_id=v_lab;

    IF v_op='duplicate' THEN
        v_source:=trim(coalesce(p_fields->>'source_technician',p_target->>'source_technician',''));
        v_destination:=trim(coalesce(p_fields->>'target_technician',p_target->>'target_technician',''));
        v_mode:=lower(trim(coalesce(p_fields->>'conflict_mode','')));
        IF v_source='' OR v_destination='' OR lower(v_source)=lower(v_destination) THEN RAISE EXCEPTION 'Distinct source and target technician names are required'; END IF;
        IF NOT EXISTS (SELECT 1 FROM public.lab_technician_costs WHERE lab_organization_id=v_lab AND lower(trim(tehnician))=lower(v_source)) THEN RAISE EXCEPTION 'Source technician costs not found'; END IF;
        IF EXISTS (SELECT 1 FROM public.lab_technician_costs WHERE lab_organization_id=v_lab AND lower(trim(tehnician))=lower(v_destination)) THEN
            IF v_mode NOT IN ('append','replace') THEN RAISE EXCEPTION 'Target technician already has costs; choose append or replace'; END IF;
            IF v_mode='replace' THEN DELETE FROM public.lab_technician_costs WHERE lab_organization_id=v_lab AND lower(trim(tehnician))=lower(v_destination); END IF;
        END IF;
        INSERT INTO public.lab_technician_costs(lab_organization_id,source_row_no,legacy_id,tehnician,tip_lucrare,etapa,cost,updated_at)
        SELECT v_lab,(v_next+row_number() over(order by source_row_no)-1)::integer,
               'cost_'||gen_random_uuid()::text,v_destination,tip_lucrare,etapa,cost,now()
        FROM public.lab_technician_costs
        WHERE lab_organization_id=v_lab AND lower(trim(tehnician))=lower(v_source)
        ORDER BY source_row_no;
        GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSIF v_op='create' THEN
        IF trim(coalesce(p_fields->>'technician',''))='' OR trim(coalesce(p_fields->>'work_type',''))='' OR trim(coalesce(p_fields->>'stage',''))='' OR NOT (p_fields?'cost') THEN RAISE EXCEPTION 'Technician, work type, stage and cost are required'; END IF;
        IF (p_fields->>'cost')::numeric<0 THEN RAISE EXCEPTION 'Cost cannot be negative'; END IF;
        INSERT INTO public.lab_technician_costs(lab_organization_id,source_row_no,legacy_id,tehnician,tip_lucrare,etapa,cost,updated_at)
        VALUES(v_lab,v_next,'cost_'||gen_random_uuid()::text,trim(p_fields->>'technician'),trim(p_fields->>'work_type'),trim(p_fields->>'stage'),(p_fields->>'cost')::numeric,now());
        v_count:=1;
    ELSIF v_op='update' THEN
        IF p_fields?'cost' AND (p_fields->>'cost')::numeric<0 THEN RAISE EXCEPTION 'Cost cannot be negative'; END IF;
        UPDATE public.lab_technician_costs SET
            tehnician=coalesce(nullif(trim(p_fields->>'technician'),''),tehnician),
            tip_lucrare=coalesce(nullif(trim(p_fields->>'work_type'),''),tip_lucrare),
            etapa=coalesce(nullif(trim(p_fields->>'stage'),''),etapa),
            cost=case when p_fields?'cost' then (p_fields->>'cost')::numeric else cost end,updated_at=now()
        WHERE lab_organization_id=v_lab AND source_row_no=(p_target->>'source_row_no')::integer;
        GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSIF v_op='delete' THEN
        DELETE FROM public.lab_technician_costs WHERE lab_organization_id=v_lab AND source_row_no=(p_target->>'source_row_no')::integer;
        GET DIAGNOSTICS v_count=ROW_COUNT;
    ELSE RAISE EXCEPTION 'Unsupported technician cost operation'; END IF;
    IF v_count=0 THEN RAISE EXCEPTION 'Technician cost target not found'; END IF;
    RETURN jsonb_build_object('ok',true,'entity','technician_cost','operation',v_op,'count',v_count,'target_technician',v_destination);
END; $$;
REVOKE ALL ON FUNCTION public.ai_admin_technician_cost_operation(text,jsonb,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_admin_technician_cost_operation.sql

-- BEGIN db/schema/20_functions/ai_admin_work_order_operation.sql
CREATE OR REPLACE FUNCTION public.ai_admin_work_order_operation(
    p_operation text,p_target jsonb,p_fields jsonb
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_op text:=lower(trim(p_operation));
    v_payload jsonb; v_result jsonb; v_ids jsonb;
BEGIN
    IF lower(coalesce(public.current_org_role(v_lab),''))<>'admin' THEN RAISE EXCEPTION 'Admin access required'; END IF;
    IF v_op='create' THEN
        v_payload:=jsonb_build_object('fields',p_fields);
    ELSE
        v_ids:=coalesce(p_target->'ids',jsonb_build_array(p_target->'id'));
        v_payload:=jsonb_build_object('ids',v_ids,'bulk_explicit',jsonb_array_length(v_ids)>1,'fields',p_fields);
    END IF;
    v_result:=public.ai_mutate_work_order(v_op,v_payload);
    IF NOT coalesce((v_result->>'ok')::boolean,false) THEN RAISE EXCEPTION '%',coalesce(v_result->>'error','Work Order operation failed'); END IF;
    RETURN v_result||jsonb_build_object('entity','work_order','operation',v_op);
END; $$;
REVOKE ALL ON FUNCTION public.ai_admin_work_order_operation(text,jsonb,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_admin_work_order_operation.sql

-- BEGIN db/schema/20_functions/ai_execute_operation.sql
CREATE OR REPLACE FUNCTION public.ai_execute_operation(p_envelope jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_entity text; v_operation text; v_request_key text;
    v_normalized jsonb; v_hash text; v_existing public.ai_operation_requests%rowtype;
    v_preview public.ai_operation_previews%rowtype; v_requires_preview boolean; v_result jsonb;
    v_allowed text[]; v_allowed_target text[]; v_role text;
BEGIN
    v_role:=public.effective_lab_role(v_lab);
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'AI operation access denied'; END IF;
    IF jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Operation envelope must be an object'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k NOT IN ('entity','operation','target','fields','request_key','preview_id')) THEN RAISE EXCEPTION 'Unknown operation envelope field'; END IF;
    v_entity:=lower(trim(coalesce(p_envelope->>'entity',''))); v_operation:=lower(trim(coalesce(p_envelope->>'operation','')));
    IF (v_entity,v_operation) NOT IN (
        ('work_order','create'),('work_order','update'),('work_order','delete'),('work_order_price','set'),
        ('contract_price','create'),('contract_price','update'),('contract_price','delete'),('contract_price','duplicate'),
        ('technician_cost','create'),('technician_cost','update'),('technician_cost','delete'),('technician_cost','duplicate'),
        ('work_type','create'),('work_type','update'),('work_type','delete'),
        ('material','set'),('material','add'),('material','subtract'),
        ('calendar_event','create'),('calendar_event','update'),('calendar_event','delete')
    ) THEN RAISE EXCEPTION 'Unsupported AI entity or operation'; END IF;
    IF jsonb_typeof(coalesce(p_envelope->'target','{}'::jsonb))<>'object'
       OR jsonb_typeof(coalesce(p_envelope->'fields','{}'::jsonb))<>'object' THEN
        RAISE EXCEPTION 'Operation target and fields must be objects';
    END IF;
    v_request_key:=trim(coalesce(p_envelope->>'request_key',''));
    IF v_request_key='' THEN RAISE EXCEPTION 'Request key is required'; END IF;
    v_normalized:=(p_envelope-'preview_id'-'request_key')||jsonb_build_object('entity',v_entity,'operation',v_operation);
    v_hash:=md5(v_normalized::text);

    v_allowed:=case v_entity
      when 'work_order' then array['Deadline','Data_Receptie','Nume_Pacient','Nume_Partener','items','case','Contract','Status','Discount','Tehnician_Model','Tehnician1_Modelare','Tehnician2_Cer_Fin','Status_Model','Status_Modelare','Status_Cer_Fin','Paid_Model','Paid_Modelare','Paid_Cer_Fin','Model_Not_Applicable','Modelare_Not_Applicable','Cer_Fin_Not_Applicable','Settlement_Model','Settlement_Modelare','Settlement_Cer_Fin','Locked']
      when 'work_order_price' then array['unit_price','discount','reason']
      when 'contract_price' then array['id','contract','work_type','price','source_contract','target_contract','conflict_mode']
      when 'technician_cost' then array['technician','work_type','stage','cost','source_technician','target_technician','conflict_mode']
      when 'work_type' then array['work_type','active']
      when 'material' then array['value','expected_quantity']
      when 'calendar_event' then array['title','event_type','description','status','start_date','end_date','start_time','calendar_scope'] else null end;
    IF v_allowed IS NULL OR EXISTS (SELECT 1 FROM jsonb_object_keys(coalesce(p_envelope->'fields','{}'::jsonb)) k WHERE NOT k=ANY(v_allowed)) THEN RAISE EXCEPTION 'Unsupported field for AI entity'; END IF;
    v_allowed_target:=case v_entity
      when 'work_order' then array['id','ids']
      when 'work_order_price' then array['id']
      when 'contract_price' then array['id','source_contract','target_contract']
      when 'technician_cost' then array['source_row_no','source_technician','target_technician']
      when 'work_type' then array['id']
      when 'material' then array['id']
      when 'calendar_event' then array['id'] else array[]::text[] end;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(coalesce(p_envelope->'target','{}'::jsonb)) k WHERE NOT k=ANY(v_allowed_target)) THEN RAISE EXCEPTION 'Unsupported target field for AI entity'; END IF;
    IF v_role='technician' AND v_entity NOT IN ('material','calendar_event') THEN RAISE EXCEPTION 'AI operation not allowed for Technician'; END IF;
    IF v_role='manager' AND v_entity NOT IN ('material','calendar_event') THEN RAISE EXCEPTION 'Admin access required for this AI operation'; END IF;

    -- A completed request is authoritative even after its destructive preview
    -- has been consumed. This makes network retries return the original result
    -- instead of failing with "preview already used".
    SELECT * INTO v_existing
    FROM public.ai_operation_requests
    WHERE lab_organization_id=v_lab AND request_key=v_request_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.requested_by_user_id<>auth.uid() THEN RAISE EXCEPTION 'Request key belongs to another user'; END IF;
        IF v_existing.envelope_hash<>v_hash THEN RAISE EXCEPTION 'Request key was already used for another operation'; END IF;
        IF v_existing.state='completed' THEN RETURN v_existing.result; END IF;
    END IF;

    INSERT INTO public.ai_operation_requests(lab_organization_id,request_key,requested_by_user_id,envelope_hash)
    VALUES(v_lab,v_request_key,auth.uid(),v_hash) ON CONFLICT DO NOTHING;
    SELECT * INTO v_existing
    FROM public.ai_operation_requests
    WHERE lab_organization_id=v_lab AND request_key=v_request_key
    FOR UPDATE;
    IF v_existing.requested_by_user_id<>auth.uid() THEN RAISE EXCEPTION 'Request key belongs to another user'; END IF;
    IF v_existing.envelope_hash<>v_hash THEN RAISE EXCEPTION 'Request key was already used for another operation'; END IF;
    IF v_existing.state='completed' THEN RETURN v_existing.result; END IF;

    v_requires_preview:=v_operation IN ('delete','duplicate') OR jsonb_array_length(coalesce(p_envelope#>'{target,ids}','[]'::jsonb))>1;
    IF v_requires_preview THEN
        IF nullif(p_envelope->>'preview_id','') IS NULL THEN RAISE EXCEPTION 'Confirmed preview is required'; END IF;
        SELECT * INTO v_preview FROM public.ai_operation_previews WHERE id=(p_envelope->>'preview_id')::uuid FOR UPDATE;
        IF NOT FOUND OR v_preview.lab_organization_id<>v_lab OR v_preview.requested_by_user_id<>auth.uid() OR v_preview.consumed_at IS NOT NULL OR v_preview.expires_at<=now() THEN RAISE EXCEPTION 'Preview is missing, expired or already used'; END IF;
        IF v_entity IN ('work_order','work_order_price') THEN
            PERFORM 1 FROM public.lab_work_orders wo
            WHERE wo.lab_organization_id=v_lab
              AND wo.id IN (SELECT value::bigint FROM jsonb_array_elements_text(
                  coalesce(v_normalized#>'{target,ids}',jsonb_build_array(v_normalized#>'{target,id}'))
              )) FOR UPDATE;
        ELSIF v_entity='contract_price' THEN
            PERFORM pg_advisory_xact_lock(hashtext(v_lab::text||':contract_price'));
            PERFORM 1 FROM public.lab_contract_work_prices cp
            WHERE cp.lab_organization_id=v_lab AND (
                cp.id=v_normalized#>>'{target,id}'
                OR lower(trim(cp.contract)) IN (
                    lower(trim(coalesce(v_normalized#>>'{fields,source_contract}',v_normalized#>>'{target,source_contract}',''))),
                    lower(trim(coalesce(v_normalized#>>'{fields,target_contract}',v_normalized#>>'{target,target_contract}','')))
                )
            ) FOR UPDATE;
        ELSIF v_entity='technician_cost' THEN
            PERFORM pg_advisory_xact_lock(hashtext(v_lab::text||':technician_cost'));
            PERFORM 1 FROM public.lab_technician_costs tc
            WHERE tc.lab_organization_id=v_lab AND (
                tc.source_row_no=nullif(v_normalized#>>'{target,source_row_no}','')::integer
                OR lower(trim(tc.tehnician)) IN (
                    lower(trim(coalesce(v_normalized#>>'{fields,source_technician}',v_normalized#>>'{target,source_technician}',''))),
                    lower(trim(coalesce(v_normalized#>>'{fields,target_technician}',v_normalized#>>'{target,target_technician}','')))
                )
            ) FOR UPDATE;
        ELSIF v_entity='work_type' THEN
            PERFORM 1 FROM public.lab_work_types wt WHERE wt.lab_organization_id=v_lab
              AND wt.id=nullif(v_normalized#>>'{target,id}','')::bigint FOR UPDATE;
        ELSIF v_entity='material' THEN
            PERFORM 1 FROM public.lab_materials_inventory m WHERE m.lab_organization_id=v_lab
              AND m.id=nullif(v_normalized#>>'{target,id}','')::bigint FOR UPDATE;
        ELSIF v_entity='calendar_event' THEN
            PERFORM 1 FROM public.lab_calendar_events e WHERE e.lab_organization_id=v_lab
              AND e.id=nullif(v_normalized#>>'{target,id}','')::bigint FOR UPDATE;
        END IF;
        IF v_preview.envelope<>v_normalized OR v_preview.checksum<>md5(public.ai_operation_state(v_normalized)::text) THEN RAISE EXCEPTION 'Preview is stale; review the operation again'; END IF;
    END IF;

    IF v_entity='work_order' THEN v_result:=public.ai_admin_work_order_operation(v_operation,coalesce(p_envelope->'target','{}'::jsonb),coalesce(p_envelope->'fields','{}'::jsonb));
    ELSIF v_entity IN ('contract_price','work_order_price') THEN v_result:=public.ai_admin_price_operation(v_entity,v_operation,coalesce(p_envelope->'target','{}'::jsonb),coalesce(p_envelope->'fields','{}'::jsonb));
    ELSIF v_entity='technician_cost' THEN v_result:=public.ai_admin_technician_cost_operation(v_operation,coalesce(p_envelope->'target','{}'::jsonb),coalesce(p_envelope->'fields','{}'::jsonb));
    ELSIF v_entity='work_type' THEN v_result:=public.ai_admin_config_operation(v_entity,v_operation,coalesce(p_envelope->'target','{}'::jsonb),coalesce(p_envelope->'fields','{}'::jsonb));
    ELSIF v_entity='material' THEN v_result:=public.adjust_material_quantity(
        v_lab,(p_envelope#>>'{target,id}')::bigint,v_operation,(p_envelope#>>'{fields,value}')::numeric,
        nullif(p_envelope#>>'{fields,expected_quantity}','')::numeric,v_request_key||':material');
    ELSIF v_entity='calendar_event' THEN v_result:=public.mutate_calendar_event(
        v_operation,nullif(p_envelope#>>'{target,id}','')::bigint,coalesce(p_envelope->'fields','{}'::jsonb),v_request_key||':calendar');
    ELSE RAISE EXCEPTION 'Unsupported AI entity or operation'; END IF;

    v_result:=v_result||jsonb_build_object('request_key',v_request_key);
    UPDATE public.ai_operation_requests SET state='completed',result=v_result,completed_at=now()
    WHERE lab_organization_id=v_lab AND request_key=v_request_key;
    IF v_requires_preview THEN UPDATE public.ai_operation_previews SET consumed_at=now() WHERE id=v_preview.id; END IF;
    RETURN v_result;
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error',sqlerrm,'entity',v_entity,'operation',v_operation);
END; $$;
REVOKE ALL ON FUNCTION public.ai_execute_operation(jsonb) FROM public;
GRANT EXECUTE ON FUNCTION public.ai_execute_operation(jsonb) TO authenticated;
-- END db/schema/20_functions/ai_execute_operation.sql

-- BEGIN db/schema/20_functions/ai_mutate_work_order.sql
-- AI uses the same atomic item-aware role writers as the browser.
CREATE OR REPLACE FUNCTION public.ai_mutate_work_order(p_action text,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id();
    v_role text:=public.effective_lab_role(v_lab);
    v_action text:=lower(trim(coalesce(p_action,'')));
    v_fields jsonb:=coalesce(p_payload->'fields',p_payload,'{}'::jsonb);
    v_ids jsonb; v_id bigint; v_text text; v_created bigint; v_items jsonb;
    v_order public.lab_work_orders%rowtype;
BEGIN
    IF v_role NOT IN ('admin','manager','technician') OR v_role IS NULL THEN RAISE EXCEPTION 'AI mutations are not enabled for this role'; END IF;
    IF v_action NOT IN ('create','update','delete') THEN RAISE EXCEPTION 'Unsupported AI mutation action'; END IF;
    IF v_action='create' THEN
        IF v_role='technician' THEN
            v_created:=public.create_technician_work_order(v_lab,nullif(v_fields->>'Deadline','')::date,
                v_fields->>'Nume_Pacient',v_fields->>'Nume_Partener',v_fields->'items',
                nullif(v_fields->>'Data_Receptie','')::timestamptz,coalesce(v_fields->>'My_Stage','Model'),coalesce(v_fields->'case','{}'::jsonb));
            RETURN jsonb_build_object('ok',true,'type','create_work_order','ids',jsonb_build_array(v_created));
        END IF;
        v_created:=public.create_management_work_order(
            p_lab_organization_id=>v_lab,p_deadline=>nullif(v_fields->>'Deadline','')::date,
            p_nume_pacient=>v_fields->>'Nume_Pacient',p_nume_partener=>v_fields->>'Nume_Partener',
            p_items=>v_fields->'items',p_contract=>coalesce(v_fields->>'Contract','General'),
            p_status=>coalesce(v_fields->>'Status','Not Started'),p_discount=>coalesce((v_fields->>'Discount')::numeric,0),
            p_data_receptie=>nullif(v_fields->>'Data_Receptie','')::timestamptz,
            p_tehnician_model=>v_fields->>'Tehnician_Model',p_tehnician1_modelare=>v_fields->>'Tehnician1_Modelare',
            p_tehnician2_cer_fin=>v_fields->>'Tehnician2_Cer_Fin',
            p_status_model=>coalesce(v_fields->>'Status_Model','Not Started'),
            p_status_modelare=>coalesce(v_fields->>'Status_Modelare','Not Started'),
            p_status_cer_fin=>coalesce(v_fields->>'Status_Cer_Fin','Not Started'),
            p_paid_model=>coalesce(v_fields->>'Paid_Model','Not Paid'),
            p_paid_modelare=>coalesce(v_fields->>'Paid_Modelare','Not Paid'),
            p_paid_cer_fin=>coalesce(v_fields->>'Paid_Cer_Fin','Not Paid'),
            p_model_not_applicable=>coalesce((v_fields->>'Model_Not_Applicable')::boolean,false),
            p_modelare_not_applicable=>coalesce((v_fields->>'Modelare_Not_Applicable')::boolean,false),
            p_cer_fin_not_applicable=>coalesce((v_fields->>'Cer_Fin_Not_Applicable')::boolean,false),
            p_locked=>coalesce((v_fields->>'Locked')::boolean,false),p_case=>coalesce(v_fields->'case','{}'::jsonb));
        RETURN jsonb_build_object('ok',true,'type','create_work_order','ids',jsonb_build_array(v_created),'count',1);
    ELSE
        v_ids:=coalesce(p_payload->'ids',jsonb_build_array(coalesce(p_payload->'id',p_payload->'target_id',v_fields->'ID')));
    END IF;
    IF jsonb_typeof(v_ids)<>'array' OR jsonb_array_length(v_ids)=0 OR jsonb_array_length(v_ids)>100 THEN RAISE EXCEPTION 'Supply between 1 and 100 Work Order IDs'; END IF;
    IF jsonb_array_length(v_ids)>1 AND NOT coalesce((p_payload->>'bulk_explicit')::boolean,false) THEN RAISE EXCEPTION 'Multiple Work Orders require bulk_explicit=true'; END IF;
    FOR v_text IN SELECT jsonb_array_elements_text(v_ids) LOOP
        v_id:=v_text::bigint;
        SELECT * INTO v_order FROM public.lab_work_orders WHERE lab_organization_id=v_lab AND id=v_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found: %',v_id; END IF;
        IF v_action='delete' THEN
            IF v_role NOT IN ('admin','manager') THEN RAISE EXCEPTION 'Only Admin/Manager can delete Work Orders'; END IF;
            PERFORM public.delete_management_work_order(v_lab,v_id);
        ELSE
            IF v_role NOT IN ('admin','manager') THEN RAISE EXCEPTION 'Technician AI may create Work Orders but may not update or delete them'; END IF;
            -- Absent items means a metadata-only edit; a supplied empty/null scope is rejected by the writer.
            IF v_fields ? 'items' THEN v_items:=v_fields->'items';
            ELSE SELECT items INTO v_items FROM public.work_order_item_scope(v_lab,v_id,false); END IF;
            PERFORM public.update_management_work_order_v188(
                p_lab_organization_id=>v_lab,p_work_order_id=>v_id,
                p_deadline=>CASE WHEN v_fields ? 'Deadline' THEN nullif(v_fields->>'Deadline','')::date ELSE v_order.deadline END,
                p_status=>coalesce(v_fields->>'Status',v_order.status),
                p_nume_pacient=>coalesce(v_fields->>'Nume_Pacient',v_order.nume_pacient),
                p_nume_partener=>coalesce(v_fields->>'Nume_Partener',v_order.nume_partener),
                p_contract=>coalesce(v_fields->>'Contract',v_order.contract),
                p_discount=>coalesce((v_fields->>'Discount')::numeric,v_order.discount),
                p_data_receptie=>CASE WHEN v_fields ? 'Data_Receptie' THEN nullif(v_fields->>'Data_Receptie','')::timestamptz ELSE v_order.data_receptie END,
                p_tehnician_model=>CASE WHEN v_fields ? 'Tehnician_Model' THEN v_fields->>'Tehnician_Model' ELSE v_order.tehnician_model END,
                p_tehnician1_modelare=>CASE WHEN v_fields ? 'Tehnician1_Modelare' THEN v_fields->>'Tehnician1_Modelare' ELSE v_order.tehnician1_modelare END,
                p_tehnician2_cer_fin=>CASE WHEN v_fields ? 'Tehnician2_Cer_Fin' THEN v_fields->>'Tehnician2_Cer_Fin' ELSE v_order.tehnician2_cer_fin END,
                p_status_model=>coalesce(v_fields->>'Status_Model',v_order.status_model),
                p_status_modelare=>coalesce(v_fields->>'Status_Modelare',v_order.status_modelare),
                p_status_cer_fin=>coalesce(v_fields->>'Status_Cer_Fin',v_order.status_cer_fin),
                p_paid_model=>v_fields->>'Paid_Model',
                p_paid_modelare=>v_fields->>'Paid_Modelare',
                p_paid_cer_fin=>v_fields->>'Paid_Cer_Fin',
                p_model_not_applicable=>coalesce((v_fields->>'Model_Not_Applicable')::boolean,v_order.model_not_applicable),p_modelare_not_applicable=>coalesce((v_fields->>'Modelare_Not_Applicable')::boolean,v_order.modelare_not_applicable),
                p_cer_fin_not_applicable=>coalesce((v_fields->>'Cer_Fin_Not_Applicable')::boolean,v_order.cer_fin_not_applicable),p_locked=>coalesce((v_fields->>'Locked')::boolean,v_order.locked),
                p_model_settlement=>v_fields->>'Settlement_Model',p_modelare_settlement=>v_fields->>'Settlement_Modelare',
                p_cer_fin_settlement=>v_fields->>'Settlement_Cer_Fin',p_items=>v_items,
                p_requested_contract=>coalesce(v_fields->>'Contract',v_order.contract,'General'),p_case=>coalesce(v_fields->'case','{}'::jsonb));
        END IF;
    END LOOP;
    RETURN jsonb_build_object('ok',true,'type',v_action||'_work_order','ids',v_ids,'count',jsonb_array_length(v_ids));
EXCEPTION WHEN OTHERS THEN
    -- Exception block rolls back the entire mutation, including previous bulk rows.
    RETURN jsonb_build_object('ok',false,'error',sqlerrm);
END; $$;
REVOKE ALL ON FUNCTION public.ai_mutate_work_order(text,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_mutate_work_order.sql

-- BEGIN db/schema/20_functions/ai_mutate_work_order_role_safe.sql
-- Flowrise Supabase function: public.ai_mutate_work_order_role_safe(p_action text, p_payload jsonb)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.ai_mutate_work_order_role_safe(p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_role text := public.effective_lab_role(public.get_flowrise_lab_id());
    v_action text := lower(trim(coalesce(p_action,'')));
    v_fields jsonb := coalesce(p_payload->'fields',p_payload,'{}'::jsonb);
    v_created bigint;
    v_ids jsonb;
    v_id bigint;
    v_id_text text;
    v_items jsonb;
begin
    if v_role in ('admin','manager') then
        return public.ai_mutate_work_order(p_action,p_payload);
    end if;

    if coalesce(v_role,'') <> 'technician' then
        return jsonb_build_object(
            'ok',false,
            'error','AI mutations are not enabled for this role'
        );
    end if;

    if v_action='update' then
        if exists(select 1 from jsonb_object_keys(v_fields) field
            where field not in ('items','case','ID','Status_Model','Status_Modelare','Status_Cer_Fin')) then
            raise exception 'Technician may edit only tooth scope, clinical case and assigned stage status';
        end if;
        v_ids:=coalesce(p_payload->'ids',jsonb_build_array(coalesce(p_payload->'id',p_payload->'target_id',v_fields->'ID')));
        if jsonb_typeof(v_ids)<>'array' or jsonb_array_length(v_ids)=0 or jsonb_array_length(v_ids)>100 then
            raise exception 'Supply between 1 and 100 Work Order IDs';
        end if;
        if jsonb_array_length(v_ids)>1 and not coalesce((p_payload->>'bulk_explicit')::boolean,false) then
            raise exception 'Multiple Work Orders require bulk_explicit=true';
        end if;
        for v_id_text in select jsonb_array_elements_text(v_ids) loop
            v_id:=v_id_text::bigint;
            if not public.can_access_work_order(v_lab,v_id) then raise exception 'Work Order access denied'; end if;
            -- Lock before reading unchanged scope so a metadata-only edit cannot restore stale items.
            perform 1 from public.lab_work_orders where lab_organization_id=v_lab and id=v_id for update;
            if not found then raise exception 'Work Order not found'; end if;
            if v_fields ? 'items' then v_items:=v_fields->'items';
            else select scope.items into v_items from public.work_order_item_scope(v_lab,v_id,false) scope; end if;
            perform public.save_my_work_order_case(v_lab,v_id,
                v_fields->>'Status_Model',v_fields->>'Status_Modelare',v_fields->>'Status_Cer_Fin',
                v_items,coalesce(v_fields->'case','{}'::jsonb));
        end loop;
        return jsonb_build_object('ok',true,'type','update_work_order','ids',v_ids,'count',jsonb_array_length(v_ids));
    end if;

    if v_action not in ('create') then
        return jsonb_build_object(
            'ok',false,
            'error','Technician AI may create or update accessible Work Orders, but may not delete them'
        );
    end if;

    -- Technician-supplied commercial fields are ignored deliberately.
    -- Contract / Status / Discount / payment fields are controlled server-side.
    begin
        v_created := public.create_technician_work_order(
            v_lab,
            nullif(v_fields->>'Deadline','')::date,
            coalesce(v_fields->>'Nume_Pacient',''),
            coalesce(v_fields->>'Nume_Partener',''),
            v_fields->'items',
            nullif(v_fields->>'Data_Receptie','')::timestamptz,
            coalesce(
                nullif(v_fields->>'My_Stage',''),
                nullif(p_payload->>'my_stage',''),
                'Model'
            ),
            coalesce(v_fields->'case','{}'::jsonb)
        );
    exception
        when others then
            return jsonb_build_object(
                'ok',false,
                'error',sqlerrm
            );
    end;

    return jsonb_build_object(
        'ok',true,
        'type','create_work_order',
        'ids',jsonb_build_array(v_created)
    );
exception when others then
    -- A failed bulk row rolls back every earlier row in the same operation.
    return jsonb_build_object('ok',false,'error',sqlerrm);
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_action text, p_payload jsonb
REVOKE ALL ON FUNCTION public.ai_mutate_work_order_role_safe(text,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_mutate_work_order_role_safe.sql

-- BEGIN db/schema/20_functions/ai_mutate_work_order_role_safe_idempotent.sql
-- Retry-safe adapter for legacy create/update/delete AI intents.
CREATE OR REPLACE FUNCTION public.ai_mutate_work_order_role_safe_idempotent(
    p_action text,
    p_payload jsonb,
    p_request_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id();
    v_key text:='legacy:'||trim(coalesce(p_request_key,''));
    v_hash text:=md5(jsonb_build_object(
        'action',lower(trim(coalesce(p_action,''))),
        'payload',coalesce(p_payload,'{}'::jsonb)
    )::text);
    v_request public.ai_operation_requests%rowtype;
    v_result jsonb;
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
    IF trim(coalesce(p_request_key,''))='' THEN RAISE EXCEPTION 'Request key is required'; END IF;

    INSERT INTO public.ai_operation_requests(
        lab_organization_id,request_key,requested_by_user_id,envelope_hash
    ) VALUES (v_lab,v_key,auth.uid(),v_hash)
    ON CONFLICT DO NOTHING;

    SELECT * INTO v_request FROM public.ai_operation_requests
    WHERE lab_organization_id=v_lab AND request_key=v_key FOR UPDATE;
    IF v_request.requested_by_user_id<>auth.uid() THEN RAISE EXCEPTION 'Request key belongs to another user'; END IF;
    IF v_request.envelope_hash<>v_hash THEN RAISE EXCEPTION 'Request key was already used for another operation'; END IF;
    IF v_request.state='completed' THEN RETURN v_request.result; END IF;

    v_result:=public.ai_mutate_work_order_role_safe(p_action,coalesce(p_payload,'{}'::jsonb));
    v_result:=coalesce(v_result,'{}'::jsonb)||jsonb_build_object('request_key',p_request_key);
    UPDATE public.ai_operation_requests
    SET state='completed',result=v_result,completed_at=now()
    WHERE lab_organization_id=v_lab AND request_key=v_key;
    RETURN v_result;
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error',sqlerrm,'request_key',p_request_key);
END;
$$;

REVOKE ALL ON FUNCTION public.ai_mutate_work_order_role_safe_idempotent(text,jsonb,text) FROM public;
GRANT EXECUTE ON FUNCTION public.ai_mutate_work_order_role_safe_idempotent(text,jsonb,text) TO authenticated;
-- END db/schema/20_functions/ai_mutate_work_order_role_safe_idempotent.sql

-- BEGIN db/schema/20_functions/ai_operation_state.sql
CREATE OR REPLACE FUNCTION public.ai_operation_state(p_envelope jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_entity text:=lower(trim(p_envelope->>'entity'));
    v_operation text:=lower(trim(p_envelope->>'operation')); v_target jsonb:=coalesce(p_envelope->'target','{}'::jsonb);
    v_fields jsonb:=coalesce(p_envelope->'fields','{}'::jsonb); v_state jsonb; v_role text;
BEGIN
    v_role:=public.effective_lab_role(v_lab);
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'AI operation access denied'; END IF;
    IF v_role='technician' AND v_entity NOT IN ('material','calendar_event') THEN RAISE EXCEPTION 'AI operation not allowed for Technician'; END IF;
    IF v_role='manager' AND v_entity NOT IN ('material','calendar_event') THEN RAISE EXCEPTION 'Admin access required for this AI operation'; END IF;
    IF v_entity='technician_cost' AND v_operation='duplicate' THEN
        SELECT jsonb_build_object(
            'source',coalesce(jsonb_agg(to_jsonb(x) order by x.source_row_no) filter(where x.side='source'),'[]'::jsonb),
            'target',coalesce(jsonb_agg(to_jsonb(x) order by x.source_row_no) filter(where x.side='target'),'[]'::jsonb)
        ) INTO v_state FROM (
            SELECT 'source'::text side,source_row_no,tehnician,tip_lucrare,etapa,cost,updated_at
            FROM public.lab_technician_costs WHERE lab_organization_id=v_lab
              AND lower(trim(tehnician))=lower(trim(coalesce(v_fields->>'source_technician',v_target->>'source_technician','')))
            UNION ALL
            SELECT 'target',source_row_no,tehnician,tip_lucrare,etapa,cost,updated_at
            FROM public.lab_technician_costs WHERE lab_organization_id=v_lab
              AND lower(trim(tehnician))=lower(trim(coalesce(v_fields->>'target_technician',v_target->>'target_technician','')))
        ) x;
    ELSIF v_entity='contract_price' AND v_operation='duplicate' THEN
        SELECT jsonb_build_object(
            'source',coalesce(jsonb_agg(to_jsonb(x) order by x.id) filter(where x.side='source'),'[]'::jsonb),
            'target',coalesce(jsonb_agg(to_jsonb(x) order by x.id) filter(where x.side='target'),'[]'::jsonb)
        ) INTO v_state FROM (
            SELECT 'source'::text side,id,contract,tip_lucrare,pret,updated_at
            FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab
              AND lower(trim(contract))=lower(trim(coalesce(v_fields->>'source_contract',v_target->>'source_contract','')))
            UNION ALL
            SELECT 'target',id,contract,tip_lucrare,pret,updated_at
            FROM public.lab_contract_work_prices WHERE lab_organization_id=v_lab
              AND lower(trim(contract))=lower(trim(coalesce(v_fields->>'target_contract',v_target->>'target_contract','')))
        ) x;
    ELSIF v_entity='work_order' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(wo) order by wo.id),'[]'::jsonb) INTO v_state
        FROM public.lab_work_orders wo WHERE wo.lab_organization_id=v_lab
          AND wo.id IN (SELECT value::bigint FROM jsonb_array_elements_text(coalesce(v_target->'ids',jsonb_build_array(v_target->'id'))));
    ELSIF v_entity='contract_price' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(cp) order by cp.id),'[]'::jsonb) INTO v_state
        FROM public.lab_contract_work_prices cp WHERE cp.lab_organization_id=v_lab AND cp.id=v_target->>'id';
    ELSIF v_entity='technician_cost' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(tc) order by tc.source_row_no),'[]'::jsonb) INTO v_state
        FROM public.lab_technician_costs tc WHERE tc.lab_organization_id=v_lab AND tc.source_row_no=(v_target->>'source_row_no')::integer;
    ELSIF v_entity='work_type' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(wt) order by wt.id),'[]'::jsonb) INTO v_state
        FROM public.lab_work_types wt WHERE wt.lab_organization_id=v_lab AND wt.id=(v_target->>'id')::bigint;
    ELSIF v_entity='work_order_price' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(wo) order by wo.id),'[]'::jsonb) INTO v_state
        FROM public.lab_work_orders wo WHERE wo.lab_organization_id=v_lab AND wo.id=(v_target->>'id')::bigint;
    ELSIF v_entity='material' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]'::jsonb) INTO v_state
        FROM public.lab_materials_inventory m WHERE m.lab_organization_id=v_lab AND m.id=(v_target->>'id')::bigint;
    ELSIF v_entity='calendar_event' THEN
        SELECT coalesce(jsonb_agg(to_jsonb(e) order by e.id),'[]'::jsonb) INTO v_state
        FROM public.lab_calendar_events e WHERE e.lab_organization_id=v_lab AND e.id=(v_target->>'id')::bigint
          AND (public.effective_lab_role(v_lab) IN ('admin','manager') OR e.calendar_scope='shared' OR e.owner_user_id=auth.uid());
    ELSE
        v_state:='[]'::jsonb;
    END IF;
    RETURN coalesce(v_state,'[]'::jsonb);
END; $$;
REVOKE ALL ON FUNCTION public.ai_operation_state(jsonb) FROM public,authenticated;
-- END db/schema/20_functions/ai_operation_state.sql

-- BEGIN db/schema/20_functions/ai_preview_operation.sql
CREATE OR REPLACE FUNCTION public.ai_preview_operation(p_envelope jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_lab uuid:=public.get_flowrise_lab_id(); v_normalized jsonb; v_state jsonb; v_checksum text;
    v_id uuid; v_entity text; v_operation text; v_role text; v_expires timestamptz:=now()+interval '5 minutes';
    v_allowed text[]; v_allowed_target text[];
BEGIN
    v_role:=public.effective_lab_role(v_lab);
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'AI operation access denied'; END IF;
    IF jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Operation envelope must be an object'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_envelope) k WHERE k NOT IN ('entity','operation','target','fields','request_key','preview_id')) THEN RAISE EXCEPTION 'Unknown operation envelope field'; END IF;
    IF jsonb_typeof(coalesce(p_envelope->'target','{}'::jsonb))<>'object'
       OR jsonb_typeof(coalesce(p_envelope->'fields','{}'::jsonb))<>'object' THEN
        RAISE EXCEPTION 'Operation target and fields must be objects';
    END IF;
    v_entity:=lower(trim(coalesce(p_envelope->>'entity',''))); v_operation:=lower(trim(coalesce(p_envelope->>'operation','')));
    IF trim(coalesce(p_envelope->>'request_key',''))='' THEN RAISE EXCEPTION 'Request key is required'; END IF;
    IF (v_entity,v_operation) NOT IN (
        ('work_order','create'),('work_order','update'),('work_order','delete'),('work_order_price','set'),
        ('contract_price','create'),('contract_price','update'),('contract_price','delete'),('contract_price','duplicate'),
        ('technician_cost','create'),('technician_cost','update'),('technician_cost','delete'),('technician_cost','duplicate'),
        ('work_type','create'),('work_type','update'),('work_type','delete'),
        ('material','set'),('material','add'),('material','subtract'),
        ('calendar_event','create'),('calendar_event','update'),('calendar_event','delete')
    ) THEN RAISE EXCEPTION 'Unsupported AI entity or operation'; END IF;
    v_allowed:=case v_entity
      when 'work_order' then array['Deadline','Data_Receptie','Nume_Pacient','Nume_Partener','items','case','Contract','Status','Discount','Tehnician_Model','Tehnician1_Modelare','Tehnician2_Cer_Fin','Status_Model','Status_Modelare','Status_Cer_Fin','Paid_Model','Paid_Modelare','Paid_Cer_Fin','Model_Not_Applicable','Modelare_Not_Applicable','Cer_Fin_Not_Applicable','Locked']
      when 'work_order_price' then array['unit_price','discount','reason']
      when 'contract_price' then array['id','contract','work_type','price','source_contract','target_contract','conflict_mode']
      when 'technician_cost' then array['technician','work_type','stage','cost','source_technician','target_technician','conflict_mode']
      when 'work_type' then array['work_type','active']
      when 'material' then array['value','expected_quantity']
      when 'calendar_event' then array['title','event_type','description','status','start_date','end_date','start_time','calendar_scope'] else null end;
    IF v_allowed IS NULL OR EXISTS (
        SELECT 1 FROM jsonb_object_keys(coalesce(p_envelope->'fields','{}'::jsonb)) k WHERE NOT k=ANY(v_allowed)
    ) THEN RAISE EXCEPTION 'Unsupported field for AI entity'; END IF;
    v_allowed_target:=case v_entity
      when 'work_order' then array['id','ids']
      when 'work_order_price' then array['id']
      when 'contract_price' then array['id','source_contract','target_contract']
      when 'technician_cost' then array['source_row_no','source_technician','target_technician']
      when 'work_type' then array['id']
      when 'material' then array['id']
      when 'calendar_event' then array['id'] else array[]::text[] end;
    IF EXISTS (
        SELECT 1 FROM jsonb_object_keys(coalesce(p_envelope->'target','{}'::jsonb)) k WHERE NOT k=ANY(v_allowed_target)
    ) THEN RAISE EXCEPTION 'Unsupported target field for AI entity'; END IF;
    IF v_role='technician' AND v_entity NOT IN ('material','calendar_event') THEN RAISE EXCEPTION 'AI operation not allowed for Technician'; END IF;
    IF v_role='manager' AND v_entity NOT IN ('material','calendar_event') THEN RAISE EXCEPTION 'Admin access required for this AI operation'; END IF;
    v_normalized:=(p_envelope-'preview_id'-'request_key')||jsonb_build_object('entity',v_entity,'operation',v_operation);
    v_state:=public.ai_operation_state(v_normalized); v_checksum:=md5(v_state::text);
    INSERT INTO public.ai_operation_previews(
        lab_organization_id,requested_by_user_id,envelope,targets,before_value,after_value,checksum,expires_at
    ) VALUES(
        v_lab,auth.uid(),v_normalized,coalesce(v_normalized->'target','{}'::jsonb),v_state,
        coalesce(v_normalized->'fields','{}'::jsonb),v_checksum,v_expires
    ) RETURNING id INTO v_id;
    RETURN jsonb_build_object('ok',true,'preview_id',v_id,'expires_at',v_expires,
        'entity',v_entity,'operation',v_operation,'targets',coalesce(v_normalized->'target','{}'::jsonb),
        'before',v_state,'after',coalesce(v_normalized->'fields','{}'::jsonb),'checksum',v_checksum);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error',sqlerrm);
END; $$;
REVOKE ALL ON FUNCTION public.ai_preview_operation(jsonb) FROM public;
GRANT EXECUTE ON FUNCTION public.ai_preview_operation(jsonb) TO authenticated;
-- END db/schema/20_functions/ai_preview_operation.sql

-- BEGIN db/schema/20_functions/ai_read_calendar.sql
CREATE OR REPLACE FUNCTION public.ai_read_calendar(p_from date,p_to date)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE v_lab uuid:=public.get_flowrise_lab_id(); v_role text:=public.effective_lab_role(v_lab); v_rows jsonb;
BEGIN
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'Calendar access denied'; END IF;
    IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>366 THEN RAISE EXCEPTION 'Calendar range must be between 0 and 366 days'; END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'ID',id,'Title',title,'Event_Type',event_type,'Description',description,'Status',status,
        'Start_Date',start_date,'End_Date',end_date,'Start_Time',start_time,
        'Calendar_Scope',calendar_scope,'Owner_User_ID',owner_user_id,'Updated_At',updated_at
    ) order by start_date,start_time,id),'[]'::jsonb) INTO v_rows
    FROM public.lab_calendar_events
    WHERE lab_organization_id=v_lab
      AND start_date<=p_to AND coalesce(end_date,start_date)>=p_from
      AND (v_role IN ('admin','manager') OR calendar_scope='shared' OR owner_user_id=auth.uid());
    RETURN v_rows;
END; $$;
REVOKE ALL ON FUNCTION public.ai_read_calendar(date,date) FROM public;
GRANT EXECUTE ON FUNCTION public.ai_read_calendar(date,date) TO authenticated;
-- END db/schema/20_functions/ai_read_calendar.sql

-- BEGIN db/schema/20_functions/ai_read_dataset.sql
-- Flowrise Supabase function: public.ai_read_dataset(p_dataset text, p_limit integer, p_offset integer)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.ai_read_dataset(p_dataset text, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_role text := public.effective_lab_role(public.get_flowrise_lab_id());
    v_dataset text := lower(trim(coalesce(p_dataset,'')));
    v_limit integer := greatest(1,least(coalesce(p_limit,1000),5000));
    v_offset integer := greatest(0,coalesce(p_offset,0));
    v_rows jsonb := '[]'::jsonb;
    v_total bigint := 0;
    v_today date := (current_timestamp at time zone 'Europe/Bucharest')::date;
begin
    if v_role = 'technician' then

        if v_dataset = 'my_work_orders' then
            return jsonb_build_object(
                'dataset',v_dataset,
                'total_rows',jsonb_array_length(public.ai_technician_work_orders()),
                'rows',public.ai_technician_work_orders()
            );

        elsif v_dataset = 'my_receivables' then
            return jsonb_build_object(
                'dataset',v_dataset,
                'total_rows',1,
                'rows',jsonb_build_array(public.ai_technician_receivables())
            );

        elsif v_dataset = 'work_types' then
            return jsonb_build_object(
                'dataset',v_dataset,
                'total_rows',jsonb_array_length(public.ai_technician_work_types()),
                'rows',public.ai_technician_work_types()
            );

        elsif v_dataset = 'materials_inventory' then
            return jsonb_build_object(
                'dataset',v_dataset,'total_rows',jsonb_array_length(public.ai_read_materials()),
                'rows',public.ai_read_materials()
            );

        elsif v_dataset = 'calendar_events' then
            return jsonb_build_object(
                'dataset',v_dataset,
                'total_rows',jsonb_array_length(public.ai_read_calendar(v_today-30,v_today+336)),
                'rows',public.ai_read_calendar(v_today-30,v_today+336)
            );

        else
            raise exception 'Dataset not allowed for Technician';
        end if;
    end if;

    if v_role not in ('admin','manager') then
        raise exception 'AI dataset access denied';
    end if;

    -- Management datasets remain exactly as configured in V17.3.
    if v_dataset = 'users' then
        with q as (
            select
                p.id,
                au.email,
                p.username,
                p.display_name,
                p.legacy_user_id,
                p.technician_name,
                p.legacy_partner_name,
                p.active,
                p.created_at,
                p.updated_at,
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'organization_id',m.organization_id,
                            'organization',o.name,
                            'organization_type',o.organization_type,
                            'role',m.role,
                            'status',m.status
                        )
                        order by o.name
                    ) filter (where m.organization_id is not null),
                    '[]'::jsonb
                ) as memberships
            from public.profiles p
            left join auth.users au on au.id=p.id
            left join public.organization_memberships m on m.user_id=p.id
            left join public.organizations o on o.id=m.organization_id
            group by p.id,au.email
        )
        select count(*) into v_total from q;

        with q as (
            select
                p.id,
                au.email,
                p.username,
                p.display_name,
                p.legacy_user_id,
                p.technician_name,
                p.legacy_partner_name,
                p.active,
                p.created_at,
                p.updated_at,
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'organization_id',m.organization_id,
                            'organization',o.name,
                            'organization_type',o.organization_type,
                            'role',m.role,
                            'status',m.status
                        )
                        order by o.name
                    ) filter (where m.organization_id is not null),
                    '[]'::jsonb
                ) as memberships
            from public.profiles p
            left join auth.users au on au.id=p.id
            left join public.organization_memberships m on m.user_id=p.id
            left join public.organizations o on o.id=m.organization_id
            group by p.id,au.email
            order by p.display_name nulls last,p.username
            limit v_limit offset v_offset
        )
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows from q;

    elsif v_dataset = 'organizations' then
        select count(*) into v_total from public.organizations;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (select * from public.organizations order by name limit v_limit offset v_offset) q;

    elsif v_dataset = 'organization_memberships' then
        select count(*) into v_total from public.organization_memberships;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select m.organization_id,o.name as organization,o.organization_type,
                   m.user_id,p.username,p.display_name,m.role,m.status,m.created_at
            from public.organization_memberships m
            join public.organizations o on o.id=m.organization_id
            left join public.profiles p on p.id=m.user_id
            order by o.name,m.role,p.display_name
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'organization_relationships' then
        select count(*) into v_total from public.organization_relationships;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select r.*,clinic.name as clinic_name,lab.name as lab_name
            from public.organization_relationships r
            join public.organizations clinic on clinic.id=r.clinic_organization_id
            join public.organizations lab on lab.id=r.lab_organization_id
            order by r.created_at desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'lab_profiles' then
        select count(*) into v_total from public.lab_profiles;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select lp.*,o.name as organization_name
            from public.lab_profiles lp
            join public.organizations o on o.id=lp.organization_id
            order by o.name
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'lab_public_offers' then
        select count(*) into v_total from public.lab_public_offers;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (select * from public.lab_public_offers order by created_at desc limit v_limit offset v_offset) q;

    elsif v_dataset = 'relationship_terms' then
        select count(*) into v_total from public.relationship_terms;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (select * from public.relationship_terms order by updated_at desc limit v_limit offset v_offset) q;

    elsif v_dataset = 'relationship_prices' then
        select count(*) into v_total from public.relationship_prices;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (select * from public.relationship_prices order by updated_at desc limit v_limit offset v_offset) q;

    elsif v_dataset = 'work_orders' then
        select count(*) into v_total from public.lab_work_orders where lab_organization_id=v_lab and archived_at is null;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select
                wo.*,
                wo.contract as matched_price_contract,
                scope.items,scope.work_types,scope.work_type_summary,scope.element_count,
                wo.snapshot_list_price as list_price,
                wo.snapshot_final_price as final_price,
                (wo.snapshot_list_price is not null) as price_matched,
                wo.price_source,
                wo.price_migrated
            from public.lab_work_orders wo
            cross join lateral public.work_order_item_scope(wo.lab_organization_id,wo.id,true) scope
            where wo.lab_organization_id=v_lab
              and wo.archived_at is null
            order by wo.id desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'financial_history' then
        select count(*) into v_total
        from public.lab_work_order_stage_assignments a
        where a.lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select a.id as assignment_id,a.work_order_id,a.stage_key,a.technician_name,
                   a.unit_cost,a.quantity,public.assignment_agreed_amount(a.id) as agreed_amount,a.cost_source,a.fixed_at,
                   a.started_at,a.ended_at,a.migrated,
                   coalesce(pay.paid_amount,0)::numeric as paid_amount,
                   case when public.assignment_agreed_amount(a.id) is null then null
                        else public.assignment_agreed_amount(a.id)-coalesce(pay.paid_amount,0) end as outstanding_amount,
                   coalesce(pay.payments,'[]'::jsonb) as payments
            from public.lab_work_order_stage_assignments a
            left join lateral (
                select sum(p.amount)::numeric as paid_amount,
                       jsonb_agg(jsonb_build_object(
                           'id',p.id,'amount',p.amount,'paid_on',p.paid_on,
                           'recorded_at',p.recorded_at,'reversal_of',p.reversal_of,
                           'migration_balance',p.migration_balance,'note',p.note
                       ) order by p.recorded_at) as payments
                from public.technician_payments p where p.assignment_id=a.id
            ) pay on true
            where a.lab_organization_id=v_lab
            order by a.work_order_id desc,a.started_at desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'patient_cases' then
        select count(*) into v_total from public.lab_patient_cases where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_patient_cases
            where lab_organization_id=v_lab
            order by work_order_id desc,id desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'work_types' then
        select count(*) into v_total from public.lab_work_types where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_work_types
            where lab_organization_id=v_lab
            order by tip_lucrare,id
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'contract_prices' then
        select count(*) into v_total from public.lab_contract_work_prices where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_contract_work_prices
            where lab_organization_id=v_lab
            order by contract,tip_lucrare,id
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'technician_costs' then
        select count(*) into v_total from public.lab_technician_costs where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_technician_costs
            where lab_organization_id=v_lab
            order by tehnician,tip_lucrare,etapa,source_row_no
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'calendar_events' then
        select count(*) into v_total from public.lab_calendar_events where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_calendar_events
            where lab_organization_id=v_lab
            order by start_date desc,start_time desc nulls last,id desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'materials_inventory' then
        select count(*) into v_total from public.lab_materials_inventory where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_materials_inventory
            where lab_organization_id=v_lab
            order by material,id
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'chat_history' then
        select count(*) into v_total from public.lab_chat_history where lab_organization_id=v_lab;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.lab_chat_history
            where lab_organization_id=v_lab
            order by created_at desc nulls last,id desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'work_order_files' then
        select count(*) into v_total
        from public.work_order_files
        where lab_organization_id=v_lab or lab_organization_id is null;

        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.work_order_files
            where lab_organization_id=v_lab or lab_organization_id is null
            order by created_at desc
            limit v_limit offset v_offset
        ) q;

    elsif v_dataset = 'role_permissions' then
        select count(*) into v_total from public.role_permissions;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (select * from public.role_permissions order by role limit v_limit offset v_offset) q;

    elsif v_dataset = 'legacy_user_directory' then
        select count(*) into v_total from public.legacy_user_directory;
        select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into v_rows
        from (
            select * from public.legacy_user_directory
            order by role,name
            limit v_limit offset v_offset
        ) q;

    else
        raise exception 'Unknown or disallowed AI dataset: %',v_dataset;
    end if;

    return jsonb_build_object(
        'dataset',v_dataset,
        'total_rows',v_total,
        'offset',v_offset,
        'returned_rows',jsonb_array_length(v_rows),
        'rows',v_rows
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_dataset text, p_limit integer, p_offset integer
-- END db/schema/20_functions/ai_read_dataset.sql

-- BEGIN db/schema/20_functions/ai_read_datasets.sql
-- Flowrise Supabase function: public.ai_read_datasets(p_datasets text[], p_limit integer)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.ai_read_datasets(p_datasets text[], p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_dataset text;
    v_result jsonb := '{}'::jsonb;
    v_role text := public.effective_lab_role(public.get_flowrise_lab_id());
    v_max_datasets integer;
begin
    if p_datasets is null or cardinality(p_datasets)=0 then
        return jsonb_build_object(
            'role',v_role,
            'datasets','{}'::jsonb
        );
    end if;

    v_max_datasets := case
        when v_role in ('admin','manager') then 20
        when v_role='technician' then 3
        else 0
    end;

    if cardinality(p_datasets) > v_max_datasets then
        raise exception 'Too many datasets requested for role';
    end if;

    foreach v_dataset in array p_datasets
    loop
        v_result := v_result || jsonb_build_object(
            lower(trim(v_dataset)),
            public.ai_read_dataset(v_dataset,p_limit,0)
        );
    end loop;

    return jsonb_build_object(
        'role',v_role,
        'datasets',v_result
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_datasets text[], p_limit integer
-- END db/schema/20_functions/ai_read_datasets.sql

-- BEGIN db/schema/20_functions/ai_read_materials.sql
CREATE OR REPLACE FUNCTION public.ai_read_materials()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE v_lab uuid:=public.get_flowrise_lab_id(); v_role text:=public.effective_lab_role(v_lab); v_rows jsonb;
BEGIN
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'Materials access denied'; END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'ID',id,'Material',material,'Furnizor',furnizor,'UM',um,'Cantitate',cantitate,
        'Prag_Minim',prag_minim,'Observatii',observatii,'Ultima_Actualizare',ultima_actualizare
    ) order by material,id),'[]'::jsonb) INTO v_rows
    FROM public.lab_materials_inventory WHERE lab_organization_id=v_lab;
    RETURN v_rows;
END; $$;
REVOKE ALL ON FUNCTION public.ai_read_materials() FROM public;
GRANT EXECUTE ON FUNCTION public.ai_read_materials() TO authenticated;
-- END db/schema/20_functions/ai_read_materials.sql

-- BEGIN db/schema/20_functions/ai_technician_receivables.sql
CREATE OR REPLACE FUNCTION public.ai_technician_receivables()
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_lab uuid := public.get_flowrise_lab_id();
    v_technician text := lower(trim(coalesce(public.current_technician_name(),'')));
    v_result jsonb;
BEGIN
    IF public.effective_lab_role(v_lab) <> 'technician' THEN RAISE EXCEPTION 'Technician access required'; END IF;
    IF v_technician='' THEN RAISE EXCEPTION 'Technician profile mapping is missing'; END IF;

    WITH assigned AS (
        SELECT a.id AS assignment_id,a.work_order_id,wo.nume_pacient,wo.nume_partener,
               scope.items,scope.work_types,scope.work_type_summary,scope.element_count,a.stage_key,
               CASE a.stage_key WHEN 'model' THEN 'Model' WHEN 'modelare' THEN 'Modelare' ELSE 'Cer / Fin' END AS stage_label,
               CASE a.stage_key WHEN 'model' THEN coalesce(wo.status_model,'Not Started')
                                WHEN 'modelare' THEN coalesce(wo.status_modelare,'Not Started')
                                ELSE coalesce(wo.status_cer_fin,'Not Started') END AS stage_status,
               a.unit_cost,public.assignment_agreed_amount(a.id) as agreed_amount,
               coalesce(pay.paid_amount,0)::numeric AS paid_amount,
               CASE WHEN public.assignment_agreed_amount(a.id) is null then null
                    ELSE public.assignment_agreed_amount(a.id)-coalesce(pay.paid_amount,0) END AS outstanding_amount,
               a.cost_source,a.started_at,a.ended_at,a.migrated
        FROM public.lab_work_order_stage_assignments a
        JOIN public.lab_work_orders wo
          ON wo.lab_organization_id=a.lab_organization_id AND wo.id=a.work_order_id
        CROSS JOIN LATERAL public.work_order_item_scope(wo.lab_organization_id,wo.id,false) scope
        LEFT JOIN LATERAL (
            SELECT coalesce(sum(p.amount),0)::numeric AS paid_amount
            FROM public.technician_payments p WHERE p.assignment_id=a.id
        ) pay ON true
        WHERE a.lab_organization_id=v_lab
          AND (a.technician_user_id=auth.uid() OR (
              a.technician_user_id is null AND lower(trim(a.technician_name))=v_technician
          ))
    ), totals AS (
        SELECT count(*)::bigint AS stage_count,
               count(*) FILTER (WHERE agreed_amount is null)::bigint AS missing_cost_count,
               coalesce(sum(agreed_amount),0)::numeric AS accrued,
               coalesce(sum(paid_amount),0)::numeric AS paid
        FROM assigned
    ), breakdown AS (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
            'Assignment_ID',assignment_id,'Work_Order_ID',work_order_id,
            'Nume_Pacient',nume_pacient,'Nume_Partener',nume_partener,
            'items',items,'work_types',work_types,'work_type_summary',work_type_summary,'element_count',element_count,'Stage',stage_key,'Stage_Label',stage_label,
            'Stage_Status',stage_status,
            'Payment_Status',case when agreed_amount is not null and paid_amount>=agreed_amount then 'Paid' else 'Not Paid' end,
            'Unit_Cost',unit_cost,'Amount',agreed_amount,'Agreed_Amount',agreed_amount,
            'Paid_Amount',paid_amount,'Outstanding_Amount',outstanding_amount,
            'Cost_Source',cost_source,'Started_At',started_at,'Ended_At',ended_at,'Migrated',migrated
        ) order by work_order_id desc,started_at desc),'[]'::jsonb) AS rows
        FROM assigned
    ), by_partner AS (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
            'Nume_Partener',partner_name,'Stage_Count',stage_count,
            'Missing_Cost_Count',missing_count,'Total_Accrued',accrued,
            'Total_Paid',paid,'Total_Outstanding',accrued-paid
        ) order by accrued desc,partner_name),'[]'::jsonb) AS rows
        FROM (
            SELECT coalesce(nullif(trim(nume_partener),''),'Partener nespecificat') AS partner_name,
                   count(*)::bigint AS stage_count,
                   count(*) FILTER (WHERE agreed_amount is null)::bigint AS missing_count,
                   coalesce(sum(agreed_amount),0)::numeric AS accrued,
                   coalesce(sum(paid_amount),0)::numeric AS paid
            FROM assigned GROUP BY 1
        ) grouped
    )
    SELECT jsonb_build_object(
        'Technician',public.current_technician_name(),'Currency','RON',
        'Stage_Count',t.stage_count,'Missing_Cost_Count',t.missing_cost_count,
        'Total_Accrued',t.accrued,'Total_Paid',t.paid,
        'Total_Outstanding',t.accrued-t.paid,
        'By_Partner',p.rows,'Breakdown',b.rows
    ) INTO v_result FROM totals t CROSS JOIN breakdown b CROSS JOIN by_partner p;
    RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.ai_technician_receivables() FROM public;
GRANT EXECUTE ON FUNCTION public.ai_technician_receivables() TO authenticated;
-- END db/schema/20_functions/ai_technician_receivables.sql

-- BEGIN db/schema/20_functions/ai_technician_work_orders.sql
-- Flowrise Supabase function: public.ai_technician_work_orders()
-- Added by the Technician AI RPC repair migration.
-- The function is technician-only and returns only row-scoped data.

create or replace function public.ai_technician_work_orders()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_technician text := lower(trim(coalesce(public.current_technician_name(),'')));
    v_rows jsonb := '[]'::jsonb;
begin
    if public.effective_lab_role(v_lab) <> 'technician' then
        raise exception 'Technician access required';
    end if;

    if v_technician = '' then
        raise exception 'Technician profile mapping is missing';
    end if;

    with assigned as (
        select
            wo.id,
            wo.deadline,
            wo.data_receptie,
            wo.nume_pacient,
            wo.nume_partener,
            scope.items,scope.work_types,scope.work_type_summary,scope.element_count,
            wo.status,
            coalesce(wo.locked,false) as locked,
            s.stage_key,
            s.stage_label,
            s.stage_order,
            s.stage_status,
            case when cost_rule.agreed_amount is not null
                      and cost_rule.paid_amount>=cost_rule.agreed_amount then 'Paid' else 'Not Paid' end as payment_status,
            s.not_applicable,
            cost_rule.unit_cost,
            cost_rule.agreed_amount,
            coalesce(case_row.case_data,'{}'::jsonb) as case_data
        from public.lab_work_orders wo
        cross join lateral public.work_order_item_scope(wo.lab_organization_id,wo.id,false) scope
        cross join lateral (
            values
                (
                    'Model'::text,
                    'Model'::text,
                    1,
                    wo.tehnician_model,
                    coalesce(wo.status_model,'Not Started'),
                    coalesce((to_jsonb(wo)->>'model_not_applicable')::boolean,false)
                ),
                (
                    'Modelare'::text,
                    'Modelare'::text,
                    2,
                    wo.tehnician1_modelare,
                    coalesce(wo.status_modelare,'Not Started'),
                    coalesce((to_jsonb(wo)->>'modelare_not_applicable')::boolean,false)
                ),
                (
                    'Cer_Fin'::text,
                    'Cer / Fin'::text,
                    3,
                    wo.tehnician2_cer_fin,
                    coalesce(wo.status_cer_fin,'Not Started'),
                    coalesce((to_jsonb(wo)->>'cer_fin_not_applicable')::boolean,false)
                )
        ) as s(stage_key,stage_label,stage_order,technician_name,stage_status,not_applicable)
        left join lateral (
            select a.unit_cost,public.assignment_agreed_amount(a.id) as agreed_amount,
                (select coalesce(sum(p.amount),0) from public.technician_payments p where p.assignment_id=a.id) as paid_amount
            from public.lab_work_order_stage_assignments a
            where a.lab_organization_id=wo.lab_organization_id
              and a.work_order_id=wo.id
              and a.stage_key=lower(s.stage_key)
              and a.ended_at is null
              and (a.technician_user_id=auth.uid() or (
                  a.technician_user_id is null and lower(trim(a.technician_name))=v_technician
              ))
            order by a.started_at desc
            limit 1
        ) cost_rule on true
        left join lateral (
            select jsonb_build_object(
                'Selected_Teeth', pc.selected_teeth,
                'Tooth_Details', pc.tooth_details_json,
                'Shade', pc.shade,
                'Method', pc.method,
                'Clinic_Note', pc.clinic_note
            ) as case_data
            from public.lab_patient_cases pc
            where pc.lab_organization_id = wo.lab_organization_id
              and pc.work_order_id = wo.id
            order by pc.id desc
            limit 1
        ) case_row on true
        where wo.lab_organization_id = v_lab
          and wo.archived_at is null
          and s.not_applicable = false
          and lower(trim(coalesce(s.technician_name,''))) = v_technician
    ), order_rows as (
        select
            a.id,
            a.deadline,
            a.data_receptie,
            a.nume_pacient,
            a.nume_partener,
            a.items,a.work_types,a.work_type_summary,a.element_count,
            a.status,
            a.locked,
            a.case_data,
            jsonb_agg(
                jsonb_build_object(
                    'Stage', a.stage_key,
                    'Stage_Label', a.stage_label,
                    'Status', a.stage_status,
                    'Payment_Status', a.payment_status,
                    'Unit_Cost', a.unit_cost,
                    'Amount', a.agreed_amount
                )
                order by a.stage_order
            ) as my_stages,
            coalesce(sum(a.agreed_amount),0)::numeric as own_technician_cost
        from assigned a
        group by a.id,a.deadline,a.data_receptie,a.nume_pacient,a.nume_partener,
                 a.items,a.work_types,a.work_type_summary,a.element_count,a.status,a.locked,a.case_data
    )
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'ID', o.id,
                'Deadline', o.deadline,
                'Data_Receptie', o.data_receptie,
                'Status', o.status,
                'Nume_Pacient', o.nume_pacient,
                'Nume_Partener', o.nume_partener,
                'items',o.items,'work_types',o.work_types,'work_type_summary',o.work_type_summary,'element_count',o.element_count,
                'Locked', o.locked,
                'Dental_Case', o.case_data,
                'My_Stages', o.my_stages,
                'Own_Technician_Cost', o.own_technician_cost
            )
            order by o.deadline nulls last,o.id desc
        ),
        '[]'::jsonb
    )
    into v_rows
    from order_rows o;

    return v_rows;
end;
$$;

revoke all on function public.ai_technician_work_orders() from public;
grant execute on function public.ai_technician_work_orders() to authenticated;
-- END db/schema/20_functions/ai_technician_work_orders.sql

