-- BEGIN db/schema/20_functions/append_my_chat_message.sql
-- Flowrise Supabase function: public.append_my_chat_message(p_session_id text, p_role text, p_message text)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.append_my_chat_message(p_session_id text, p_role text, p_message text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id bigint;
    v_role text := lower(trim(coalesce(p_role,'')));
    v_user text := public.current_legacy_user_id();
begin
    if v_user is null or trim(v_user) = '' then
        raise exception 'Active user not found';
    end if;

    if v_role not in ('user','assistant') then
        raise exception 'Invalid chat role';
    end if;

    if trim(coalesce(p_session_id,'')) = '' then
        raise exception 'Session ID is required';
    end if;

    if trim(coalesce(p_message,'')) = '' then
        raise exception 'Message is required';
    end if;

    insert into public.lab_chat_history (
        lab_organization_id,
        user_id,
        session_id,
        role,
        message,
        created_at
    )
    values (
        public.get_flowrise_lab_id(),
        v_user,
        p_session_id,
        v_role,
        p_message,
        now()
    )
    returning id into v_id;

    return v_id;
end;
$function$
;

-- Security definer: True
-- Return type: bigint
-- Identity arguments: p_session_id text, p_role text, p_message text
-- END db/schema/20_functions/append_my_chat_message.sql

-- BEGIN db/schema/20_functions/assignment_agreed_amount.sql
-- Internal aggregate; original agreed amount and all deltas remain immutable.
CREATE OR REPLACE FUNCTION public.assignment_agreed_amount(p_assignment uuid)
RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
    SELECT CASE WHEN a.agreed_amount IS NULL OR EXISTS(
        SELECT 1 FROM public.lab_work_order_assignment_adjustments d WHERE d.assignment_id=a.id AND d.amount IS NULL
    ) THEN NULL ELSE a.agreed_amount+coalesce((
        SELECT sum(d.amount) FROM public.lab_work_order_assignment_adjustments d WHERE d.assignment_id=a.id
    ),0) END FROM public.lab_work_order_stage_assignments a WHERE a.id=p_assignment
$$;
REVOKE ALL ON FUNCTION public.assignment_agreed_amount(uuid) FROM public,authenticated;

-- Internal current-stage status: adjustments and signed payments are authoritative.
CREATE OR REPLACE FUNCTION public.work_order_stage_payment_status(p_lab uuid,p_order bigint,p_stage text)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
    SELECT CASE WHEN EXISTS (
        SELECT 1 FROM public.lab_work_order_stage_assignments a
        WHERE a.lab_organization_id=p_lab AND a.work_order_id=p_order
          AND a.stage_key=p_stage AND a.ended_at IS NULL
          AND public.assignment_agreed_amount(a.id) IS NOT NULL
          AND coalesce((SELECT sum(p.amount) FROM public.technician_payments p WHERE p.assignment_id=a.id),0)
              >= public.assignment_agreed_amount(a.id)
    ) THEN 'Paid' ELSE 'Not Paid' END
$$;
REVOKE ALL ON FUNCTION public.work_order_stage_payment_status(uuid,bigint,text) FROM public,anon,authenticated;
-- END db/schema/20_functions/assignment_agreed_amount.sql

-- BEGIN db/schema/20_functions/backfill_work_order_financial_history.sql
-- Repairs current assignments from the current catalog. This is intentionally
-- limited to incomplete snapshots without payments or adjustments; valid frozen
-- history is never recalculated.
CREATE OR REPLACE FUNCTION public.backfill_work_order_financial_history(p_lab uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_order public.lab_work_orders%rowtype;
    v_stage record;
    v_assignment_id uuid;
    v_before_id uuid;
    v_before_repair_audits integer;
    v_after_repair_audits integer;
    v_prices integer := 0;
    v_assignments integer := 0;
    v_repaired integer := 0;
    v_missing jsonb := '[]'::jsonb;
    v_unresolved jsonb := '[]'::jsonb;
BEGIN
    IF lower(coalesce(public.current_org_role(p_lab),''))<>'admin' THEN RAISE EXCEPTION 'Admin access required'; END IF;
    UPDATE public.lab_work_orders wo SET
        snapshot_list_price=totals.list_price,
        snapshot_final_price=round(totals.list_price*(1-wo.discount/100),2),
        price_source='migration_items',price_fixed_at=now(),price_migrated=true
    FROM (SELECT work_order_id,CASE WHEN bool_and(line_total IS NOT NULL) THEN sum(line_total) END list_price
        FROM public.lab_work_order_items WHERE lab_organization_id=p_lab GROUP BY work_order_id) totals
    WHERE wo.lab_organization_id=p_lab AND wo.id=totals.work_order_id AND wo.price_fixed_at IS NULL
      AND wo.snapshot_list_price IS NULL AND wo.snapshot_final_price IS NULL;
    GET DIAGNOSTICS v_prices=ROW_COUNT;

    FOR v_order IN
        SELECT * FROM public.lab_work_orders
        WHERE lab_organization_id=p_lab
        ORDER BY id
    LOOP
        FOR v_stage IN SELECT * FROM (VALUES
            ('model'::text,v_order.tehnician_model),
            ('modelare'::text,v_order.tehnician1_modelare),
            ('cer_fin'::text,v_order.tehnician2_cer_fin)
        ) stages(stage_key,technician_name)
        LOOP
            IF nullif(trim(coalesce(v_stage.technician_name,'')),'') IS NULL THEN CONTINUE; END IF;

            v_before_id:=NULL;
            SELECT count(*)::integer INTO v_before_repair_audits
            FROM public.work_order_financial_audit
            WHERE lab_organization_id=p_lab AND work_order_id=v_order.id
              AND entity_type='stage_assignment'
              AND (action='repair_incomplete' OR action='repair_aggregate');
            SELECT a.id INTO v_before_id
            FROM public.lab_work_order_stage_assignments a
            WHERE a.lab_organization_id=p_lab AND a.work_order_id=v_order.id
              AND a.stage_key=v_stage.stage_key AND a.ended_at IS NULL;

            BEGIN
                v_assignment_id:=public.sync_work_order_stage_assignment(
                    p_lab,v_order.id,v_stage.stage_key,v_stage.technician_name
                );
                IF v_before_id IS NULL THEN
                    v_assignments:=v_assignments+1;
                ELSE
                    SELECT count(*)::integer INTO v_after_repair_audits
                    FROM public.work_order_financial_audit
                    WHERE lab_organization_id=p_lab AND work_order_id=v_order.id
                      AND entity_type='stage_assignment'
                      AND (action='repair_incomplete' OR action='repair_aggregate');
                    IF v_after_repair_audits>v_before_repair_audits THEN
                        v_repaired:=v_repaired+1;
                    END IF;
                END IF;
                UPDATE public.lab_work_order_stage_assignments SET migrated=true
                WHERE id=v_assignment_id AND (
                    v_before_id IS NULL OR v_after_repair_audits>v_before_repair_audits
                );
            EXCEPTION WHEN OTHERS THEN
                IF SQLERRM LIKE 'Missing technician cost configuration:%' THEN
                    v_missing:=v_missing||jsonb_build_array(jsonb_build_object(
                        'work_order_id',v_order.id,'stage',v_stage.stage_key,
                        'technician',v_stage.technician_name,'error',SQLERRM
                    ));
                ELSIF SQLERRM LIKE 'Incomplete technician cost snapshot cannot be repaired%' THEN
                    v_unresolved:=v_unresolved||jsonb_build_array(jsonb_build_object(
                        'work_order_id',v_order.id,'stage',v_stage.stage_key,
                        'technician',v_stage.technician_name,'error',SQLERRM
                    ));
                ELSE
                    RAISE;
                END IF;
            END;
        END LOOP;
    END LOOP;

    RETURN jsonb_build_object(
        'prices',v_prices,'assignments',v_assignments,
        'repaired_assignments',v_repaired,'missing_costs',v_missing,
        'unresolved_assignments',v_unresolved,
        'migration_balances',0
    );
END; $$;
REVOKE ALL ON FUNCTION public.backfill_work_order_financial_history(uuid) FROM public;
GRANT EXECUTE ON FUNCTION public.backfill_work_order_financial_history(uuid) TO authenticated;
-- END db/schema/20_functions/backfill_work_order_financial_history.sql

-- BEGIN db/schema/20_functions/can_access_work_order.sql
-- Flowrise Supabase function: public.can_access_work_order(p_lab_organization_id uuid, p_work_order_id bigint)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.can_access_work_order(p_lab_organization_id uuid, p_work_order_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_order public.lab_work_orders%rowtype;
    v_technician text;
begin
    select *
      into v_order
    from public.lab_work_orders
    where lab_organization_id = p_lab_organization_id
      and id = p_work_order_id
    limit 1;

    if not found then
        return false;
    end if;

    if public.is_lab_management(p_lab_organization_id)
       or public.is_lab_dashboard(p_lab_organization_id) then
        return true;
    end if;

    if public.is_lab_technician(p_lab_organization_id) then
        v_technician := lower(trim(coalesce(public.current_technician_name(),'')));

        return v_technician <> ''
           and v_technician in (
               lower(trim(coalesce(v_order.tehnician_model,''))),
               lower(trim(coalesce(v_order.tehnician1_modelare,''))),
               lower(trim(coalesce(v_order.tehnician2_cer_fin,'')))
           );
    end if;

    if public.is_connected_doctor_for_lab(p_lab_organization_id) then
        return public.doctor_matches_partner(v_order.nume_partener);
    end if;

    return false;
end;
$function$
;

-- Security definer: True
-- Return type: boolean
-- Identity arguments: p_lab_organization_id uuid, p_work_order_id bigint
-- END db/schema/20_functions/can_access_work_order.sql

