-- BEGIN db/schema/20_functions/chat_open_direct_thread.sql
-- Flowrise Supabase function: public.chat_open_direct_thread(p_other_user uuid)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.chat_open_direct_thread(p_other_user uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me uuid := auth.uid();
    v_key text;
    v_thread uuid;
begin
    if not public.chat_can_message(p_other_user) then
        raise exception 'You are not allowed to start this conversation';
    end if;

    v_key := case
        when v_me::text < p_other_user::text
            then v_me::text || ':' || p_other_user::text
        else p_other_user::text || ':' || v_me::text
    end;

    insert into public.chat_threads (
        thread_type,
        direct_key,
        created_by,
        created_at
    )
    values (
        'direct',
        v_key,
        v_me,
        now()
    )
    on conflict (direct_key)
    do update set direct_key=excluded.direct_key
    returning id into v_thread;

    insert into public.chat_thread_participants(thread_id,user_id,joined_at,last_read_at)
    values
        (v_thread,v_me,now(),now()),
        (v_thread,p_other_user,now(),null)
    on conflict (thread_id,user_id) do nothing;

    return v_thread;
end;
$function$
;

-- Security definer: True
-- Return type: uuid
-- Identity arguments: p_other_user uuid
-- END db/schema/20_functions/chat_open_direct_thread.sql

-- BEGIN db/schema/20_functions/chat_search_users.sql
-- Flowrise Supabase function: public.chat_search_users(p_query text, p_limit integer)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.chat_search_users(p_query text DEFAULT ''::text, p_limit integer DEFAULT 30)
 RETURNS TABLE(user_id uuid, username text, display_name text, role text, organization_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    with candidates as (
        select
            p.id as user_id,
            p.username::text,
            coalesce(p.display_name,p.username)::text as display_name
        from public.profiles p
        where p.active = true
          and p.id <> auth.uid()
          and public.chat_can_message(p.id)
          and (
              trim(coalesce(p_query,'')) = ''
              or lower(coalesce(p.display_name,'')) like '%'||lower(trim(p_query))||'%'
              or lower(coalesce(p.username::text,'')) like '%'||lower(trim(p_query))||'%'
              or lower(coalesce(p.legacy_user_id,'')) like '%'||lower(trim(p_query))||'%'
          )
        order by coalesce(p.display_name,p.username::text)
        limit greatest(1,least(coalesce(p_limit,30),100))
    )
    select
        c.user_id,
        c.username,
        c.display_name,
        coalesce(meta.role,'')::text,
        coalesce(meta.organization_name,'')::text
    from candidates c
    left join lateral (
        select
            initcap(m.role)::text as role,
            o.name::text as organization_name
        from public.organization_memberships m
        join public.organizations o on o.id=m.organization_id
        where m.user_id=c.user_id
          and m.status='active'
          and lower(m.role) in ('admin','manager','technician','doctor')
        order by
            case lower(m.role)
                when 'admin' then 1
                when 'manager' then 2
                when 'technician' then 3
                when 'doctor' then 4
                else 9
            end,
            o.name
        limit 1
    ) meta on true
    order by c.display_name;
$function$
;

-- Security definer: True
-- Return type: TABLE(user_id uuid, username text, display_name text, role text, organization_name text)
-- Identity arguments: p_query text, p_limit integer
-- END db/schema/20_functions/chat_search_users.sql

-- BEGIN db/schema/20_functions/chat_send_message.sql
-- Flowrise Supabase function: public.chat_send_message(p_thread_id uuid, p_body text, p_attachments jsonb)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.chat_send_message(p_thread_id uuid, p_body text DEFAULT NULL::text, p_attachments jsonb DEFAULT '[]'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me uuid := auth.uid();
    v_message_id bigint;
    v_attachment jsonb;
    v_path text;
    v_name text;
    v_mime text;
    v_size bigint;
begin
    if not public.chat_is_thread_participant(p_thread_id) then
        raise exception 'Conversation access denied';
    end if;

    if jsonb_typeof(coalesce(p_attachments,'[]'::jsonb)) <> 'array' then
        raise exception 'Invalid attachments payload';
    end if;

    if nullif(trim(coalesce(p_body,'')),'') is null
       and jsonb_array_length(coalesce(p_attachments,'[]'::jsonb)) = 0 then
        raise exception 'Message is empty';
    end if;

    if jsonb_array_length(coalesce(p_attachments,'[]'::jsonb)) > 10 then
        raise exception 'Maximum 10 files per message';
    end if;

    insert into public.chat_messages(thread_id,sender_id,body,created_at)
    values (
        p_thread_id,
        v_me,
        nullif(trim(coalesce(p_body,'')),''),
        now()
    )
    returning id into v_message_id;

    for v_attachment in
        select * from jsonb_array_elements(coalesce(p_attachments,'[]'::jsonb))
    loop
        v_path := trim(coalesce(v_attachment->>'storage_path',''));
        v_name := trim(coalesce(v_attachment->>'file_name',''));
        v_mime := nullif(trim(coalesce(v_attachment->>'mime_type','')),'');
        v_size := coalesce(nullif(v_attachment->>'size_bytes','')::bigint,0);

        if v_path = ''
           or v_name = ''
           or v_size < 0
           or v_size > 26214400 then
            raise exception 'Invalid attachment';
        end if;

        -- Expected private object path:
        -- <thread_uuid>/<sender_uuid>/<random>_<filename>
        if split_part(v_path,'/',1) <> p_thread_id::text
           or split_part(v_path,'/',2) <> v_me::text then
            raise exception 'Invalid attachment path';
        end if;

        insert into public.chat_attachments(
            message_id,
            thread_id,
            uploaded_by,
            storage_path,
            file_name,
            mime_type,
            size_bytes,
            created_at
        )
        values (
            v_message_id,
            p_thread_id,
            v_me,
            v_path,
            v_name,
            v_mime,
            v_size,
            now()
        );
    end loop;

    update public.chat_threads
    set last_message_at=now()
    where id=p_thread_id;

    update public.chat_thread_participants
    set last_read_at=now()
    where thread_id=p_thread_id
      and user_id=v_me;

    return v_message_id;
end;
$function$
;

-- Security definer: True
-- Return type: bigint
-- Identity arguments: p_thread_id uuid, p_body text, p_attachments jsonb
-- END db/schema/20_functions/chat_send_message.sql

