-- BEGIN db/schema/20_functions/estimate_work_order_items.sql
-- Flowrise Supabase function: public.estimate_work_order_items
-- Sourced from SUPABASE V18.16 Per-Tooth Multi-Price.sql.
-- Includes the complete function definition and available ACL statements.

create or replace function public.estimate_work_order_items(
    p_lab_organization_id uuid,
    p_partner_name text,
    p_requested_contract text,
    p_items jsonb,
    p_discount numeric default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_role text := public.effective_lab_role(p_lab_organization_id);
    v_partner text := nullif(trim(coalesce(p_partner_name,'')),'');
    v_requested text := coalesce(nullif(trim(coalesce(p_requested_contract,'')),''),'General');
    v_discount numeric := greatest(0,least(100,coalesce(p_discount,0)));
    v_lines jsonb := '[]'::jsonb;
    v_count integer := 0;
    v_list numeric := 0;
    v_matched_all boolean := false;
begin
    if v_role not in ('admin','manager','doctor') then
        raise exception 'Price estimate access denied';
    end if;
    if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then
        raise exception 'Items must be a JSON array';
    end if;

    if v_role='doctor' then
        select nullif(trim(p.legacy_partner_name),'') into v_partner
        from public.profiles p
        where p.id=auth.uid() and p.active=true;
        if v_partner is null then raise exception 'Doctor partner mapping is missing'; end if;
        v_requested := v_partner;
        v_discount := 0;
    elsif v_partner is null then
        raise exception 'Partner name is required';
    end if;

    with item_input as (
        select trim(item->>'work_type') as work_type, count(*)::integer as quantity
        from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) item
        where trim(coalesce(item->>'work_type','')) <> ''
        group by trim(item->>'work_type')
    ), resolved as (
        select i.work_type,i.quantity,
               coalesce(price.contract,'General') as contract,
               coalesce(price.pret,0)::numeric as unit_price,
               (price.contract is not null) as matched
        from item_input i
        left join lateral (
            select cp.contract,cp.pret
            from public.lab_contract_work_prices cp
            where cp.lab_organization_id=p_lab_organization_id
              and lower(trim(cp.tip_lucrare))=lower(i.work_type)
              and lower(trim(cp.contract)) in (
                  lower(coalesce(v_partner,'')),lower(v_requested),'general'
              )
            order by case
                when lower(trim(cp.contract))=lower(coalesce(v_partner,'')) then 0
                when lower(trim(cp.contract))=lower(v_requested) then 1
                else 2
            end, cp.id
            limit 1
        ) price on true
    )
    select
        coalesce(jsonb_agg(jsonb_build_object(
            'work_type',work_type,'quantity',quantity,'contract',contract,
            'unit_price',unit_price,'subtotal',round(unit_price*quantity,2),
            'matched',matched
        ) order by work_type),'[]'::jsonb),
        coalesce(sum(quantity),0)::integer,
        coalesce(sum(round(unit_price*quantity,2)),0),
        coalesce(bool_and(matched),false)
    into v_lines,v_count,v_list,v_matched_all
    from resolved;

    return jsonb_build_object(
        'lines',v_lines,
        'element_count',v_count,
        'list_price',round(v_list,2),
        'discount',v_discount,
        'final_price',round(v_list*(1-v_discount/100),2),
        'matched_all',v_matched_all,
        'partner_name',v_partner
    );
end;
$$;

revoke all on function public.estimate_work_order_items(uuid,text,text,jsonb,numeric) from public;
grant execute on function public.estimate_work_order_items(uuid,text,text,jsonb,numeric) to authenticated;
-- END db/schema/20_functions/estimate_work_order_items.sql

-- BEGIN db/schema/20_functions/get_ai_bootstrap.sql
-- Flowrise Supabase function: public.get_ai_bootstrap(p_session_id text)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.get_ai_bootstrap(p_session_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_role text := public.effective_lab_role(public.get_flowrise_lab_id());
    v_history jsonb := '[]'::jsonb;
    v_catalog jsonb := '[]'::jsonb;
    v_operations jsonb := '[]'::jsonb;
begin
    if v_role is null then
        return jsonb_build_object(
            'allowed', false,
            'message', 'No active Flowrise role'
        );
    end if;

    if v_role in ('doctor','dashboard') then
        return jsonb_build_object(
            'allowed', false,
            'role', v_role,
            'message', 'AI is disabled for this role'
        );
    end if;

    select coalesce(jsonb_agg(x.obj order by x.created_at),'[]'::jsonb)
      into v_history
    from (
        select
            ch.created_at,
            jsonb_build_object(
                'role', ch.role,
                'message', ch.message,
                'created_at', ch.created_at
            ) as obj
        from public.lab_chat_history ch
        where ch.lab_organization_id = v_lab
          and lower(coalesce(ch.user_id,'')) =
              lower(coalesce(public.current_legacy_user_id(),''))
          and ch.session_id = p_session_id
          and ch.message is not null
          and ch.role in ('user','assistant')
        order by ch.created_at desc nulls last, ch.id desc
        limit 14
    ) x;

    if v_role in ('admin','manager') then
        v_catalog := jsonb_build_array(
            jsonb_build_object('dataset','users','description','Sanitized users/profiles/memberships, including email. No passwords, hashes, tokens or credentials.'),
            jsonb_build_object('dataset','organizations','description','Clinics and laboratories.'),
            jsonb_build_object('dataset','organization_memberships','description','User membership and role per organization.'),
            jsonb_build_object('dataset','organization_relationships','description','Clinic-Lab relationships and status.'),
            jsonb_build_object('dataset','lab_profiles','description','Laboratory profile/discovery configuration.'),
            jsonb_build_object('dataset','lab_public_offers','description','Public laboratory offers.'),
            jsonb_build_object('dataset','relationship_terms','description','Clinic-Lab commercial terms.'),
            jsonb_build_object('dataset','relationship_prices','description','Optional negotiated prices attached to new organization relationships. This table may be empty; do not use it for legacy Work Order financial summaries.'),
            jsonb_build_object('dataset','work_orders','description','All operational Work Orders with persisted unit_price, list_price and final_price. These historic amounts do not change with the current tariff catalog.'),
            jsonb_build_object('dataset','financial_history','description','Persisted technician assignments, agreed costs, payments, reversals and migration provenance per Work Order.'),
            jsonb_build_object('dataset','patient_cases','description','All dental prescription / patient case rows.'),
            jsonb_build_object('dataset','work_types','description','Configured work types.'),
            jsonb_build_object('dataset','contract_prices','description','Authoritative legacy Contract + work-type client price list. Use with work_orders for management financial summaries; do not substitute relationship_prices.'),
            jsonb_build_object('dataset','technician_costs','description','Technician cost configuration for all technicians.'),
            jsonb_build_object('dataset','calendar_events','description','Laboratory calendar events.'),
            jsonb_build_object('dataset','materials_inventory','description','Materials stock and reorder thresholds.'),
            jsonb_build_object('dataset','chat_history','description','Application AI chat history stored in Supabase.'),
            jsonb_build_object('dataset','work_order_files','description','Work Order file metadata; does not contain file binary contents.'),
            jsonb_build_object('dataset','role_permissions','description','Application permission matrix.'),
            jsonb_build_object('dataset','legacy_user_directory','description','Non-secret legacy user mapping retained for migration compatibility.')
        );

        if v_role = 'admin' then
            v_operations := jsonb_build_array(
                'work_order.create','work_order.update','work_order.delete','work_order_price.set',
                'contract_price.create','contract_price.update','contract_price.delete','contract_price.duplicate',
                'technician_cost.create','technician_cost.update','technician_cost.delete','technician_cost.duplicate',
                'work_type.create','work_type.update','work_type.delete',
                'material.set','material.add','material.subtract',
                'calendar_event.create','calendar_event.update','calendar_event.delete'
            );
        else
            v_operations := jsonb_build_array(
                'work_order.create','work_order.update','work_order.delete',
                'material.set','material.add','material.subtract',
                'calendar_event.create','calendar_event.update','calendar_event.delete'
            );
        end if;

    elsif v_role = 'technician' then
        v_catalog := jsonb_build_array(
            jsonb_build_object(
                'dataset','my_work_orders',
                'description','Only Work Orders where this technician is assigned. Contains order/global status, own assigned stages, own stage status, own payment status and own compensation.'
            ),
            jsonb_build_object(
                'dataset','my_receivables',
                'description','Only this technician own compensation: accrued, paid and outstanding amounts, including a ready-to-use By_Partner summary. Use this for Technician financial summaries by partner; no client sale prices are needed.'
            ),
            jsonb_build_object(
                'dataset','work_types',
                'description','Active work type names only. No client price, contract or partner commercial information.'
            ),
            jsonb_build_object(
                'dataset','materials_inventory',
                'description','Shared laboratory material stock. Technician may read and adjust quantities.'
            ),
            jsonb_build_object(
                'dataset','calendar_events',
                'description','Shared calendar plus this user personal calendar. Other users personal events are excluded.'
            )
        );
        v_operations := jsonb_build_array(
            'work_order.create','material.set','material.add','material.subtract',
            'calendar_event.create','calendar_event.update','calendar_event.delete'
        );

    else
        return jsonb_build_object(
            'allowed', false,
            'role', v_role,
            'message', 'AI is not enabled for this role'
        );
    end if;

    return jsonb_build_object(
        'allowed', true,
        'role', v_role,
        'history', v_history,
        'catalog', v_catalog,
        'operations', v_operations
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_session_id text
-- END db/schema/20_functions/get_ai_bootstrap.sql

-- BEGIN db/schema/20_functions/get_ai_context.sql
-- Flowrise Supabase function: public.get_ai_context(p_session_id text)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.get_ai_context(p_session_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_role text := public.effective_lab_role(public.get_flowrise_lab_id());
    v_identity jsonb;
    v_history jsonb := '[]'::jsonb;
    v_orders jsonb := '[]'::jsonb;
    v_prices jsonb := '[]'::jsonb;
    v_costs jsonb := '[]'::jsonb;
    v_types jsonb := '[]'::jsonb;
    v_materials jsonb := '[]'::jsonb;
    v_tech text := lower(trim(coalesce(public.current_technician_name(),'')));
begin
    v_identity := public.get_app_identity();

    if coalesce((v_identity->>'ok')::boolean,false) = false then
        return jsonb_build_object('allowed',false,'identity',v_identity);
    end if;

    if v_role not in ('admin','manager','technician') then
        return jsonb_build_object(
            'allowed', false,
            'identity', v_identity,
            'message', 'AI is not enabled for this role'
        );
    end if;

    select coalesce(jsonb_agg(x.obj order by x.created_at),'[]'::jsonb)
      into v_history
    from (
        select
            ch.created_at,
            jsonb_build_object(
                'Role', ch.role,
                'Message', ch.message,
                'Created_At', ch.created_at
            ) as obj
        from public.lab_chat_history ch
        where ch.lab_organization_id = v_lab
          and lower(coalesce(ch.user_id,'')) =
              lower(coalesce(public.current_legacy_user_id(),''))
          and ch.session_id = p_session_id
          and ch.message is not null
          and ch.role in ('user','assistant')
        order by ch.created_at desc nulls last, ch.id desc
        limit 14
    ) x;

    select coalesce(jsonb_agg(
        jsonb_build_object(
            'ID', wt.id,
            'Tip_Lucrare', wt.tip_lucrare,
            'Active', wt.active
        )
        order by wt.tip_lucrare, wt.id
    ),'[]'::jsonb)
    into v_types
    from public.lab_work_types wt
    where wt.lab_organization_id = v_lab
      and wt.active = true;

    if v_role in ('admin','manager') then

        select coalesce(jsonb_agg(x.obj order by x.id desc),'[]'::jsonb)
          into v_orders
        from (
            select
                wo.id,
                jsonb_build_object(
                    'ID', wo.id,
                    'Deadline', wo.deadline,
                    'Data_Receptie', wo.data_receptie,
                    'Status', wo.status,
                    'Nume_Pacient', wo.nume_pacient,
                    'Nume_Partener', wo.nume_partener,
                    'Contract', wo.contract,
                    'items', scope.items,'work_types',scope.work_types,
                    'work_type_summary',scope.work_type_summary,'element_count',scope.element_count,
                    'Tehnician_Model', wo.tehnician_model,
                    'Tehnician1_Modelare', wo.tehnician1_modelare,
                    'Tehnician2_Cer_Fin', wo.tehnician2_cer_fin,
                    'Status_Model', wo.status_model,
                    'Status_Modelare', wo.status_modelare,
                    'Status_Cer_Fin', wo.status_cer_fin,
                    'Paid_Model', public.work_order_stage_payment_status(wo.lab_organization_id,wo.id,'model'),
                    'Paid_Modelare', public.work_order_stage_payment_status(wo.lab_organization_id,wo.id,'modelare'),
                    'Paid_Cer_Fin', public.work_order_stage_payment_status(wo.lab_organization_id,wo.id,'cer_fin'),
                    'Discount', wo.discount,
                    'Locked', wo.locked,
                    'Total_Pret_Lista', wo.snapshot_list_price,
                    'Total_dupa_Discount', wo.snapshot_final_price,
                    'Price_Source', wo.price_source,
                    'Price_Migrated', wo.price_migrated
                ) as obj
            from public.lab_work_orders wo
        cross join lateral public.work_order_item_scope(wo.lab_organization_id,wo.id,false) scope
            where wo.lab_organization_id = v_lab
              and wo.archived_at is null
            order by wo.id desc
            limit 500
        ) x;

        select coalesce(jsonb_agg(
            jsonb_build_object(
                'ID', cp.id,
                'Contract', cp.contract,
                'Tip_Lucrare', cp.tip_lucrare,
                'Pret', cp.pret
            )
            order by cp.contract, cp.tip_lucrare, cp.id
        ),'[]'::jsonb)
        into v_prices
        from public.lab_contract_work_prices cp
        where cp.lab_organization_id = v_lab;

        select coalesce(jsonb_agg(
            jsonb_build_object(
                'ID', tc.legacy_id,
                'Source_Row_No', tc.source_row_no,
                'Tehnician', tc.tehnician,
                'Tip_Lucrare', tc.tip_lucrare,
                'Etapa', tc.etapa,
                'Cost', tc.cost
            )
            order by tc.tehnician, tc.tip_lucrare, tc.etapa, tc.source_row_no
        ),'[]'::jsonb)
        into v_costs
        from public.lab_technician_costs tc
        where tc.lab_organization_id = v_lab;

        select coalesce(jsonb_agg(
            jsonb_build_object(
                'ID', mi.id,
                'Furnizor', mi.furnizor,
                'Material', mi.material,
                'UM', mi.um,
                'Cantitate', mi.cantitate,
                'Prag_Minim', mi.prag_minim,
                'Ultima_Actualizare', mi.ultima_actualizare,
                'Observatii', mi.observatii
            )
            order by mi.material, mi.id
        ),'[]'::jsonb)
        into v_materials
        from public.lab_materials_inventory mi
        where mi.lab_organization_id = v_lab;

    elsif v_role = 'technician' then

        select coalesce(jsonb_agg(x.obj order by x.id desc),'[]'::jsonb)
          into v_orders
        from (
            select
                wo.id,
                jsonb_build_object(
                    'ID', wo.id,
                    'Deadline', wo.deadline,
                    'Data_Receptie', wo.data_receptie,
                    'Status', wo.status,
                    'Nume_Pacient', wo.nume_pacient,
                    'Nume_Partener', wo.nume_partener,
                    'items', scope.items,'work_types',scope.work_types,
                    'work_type_summary',scope.work_type_summary,'element_count',scope.element_count,
                    'Tehnician_Model', wo.tehnician_model,
                    'Tehnician1_Modelare', wo.tehnician1_modelare,
                    'Tehnician2_Cer_Fin', wo.tehnician2_cer_fin,
                    'Status_Model', wo.status_model,
                    'Status_Modelare', wo.status_modelare,
                    'Status_Cer_Fin', wo.status_cer_fin,
                    'Paid_Model',
                        case when lower(trim(coalesce(wo.tehnician_model,''))) = v_tech
                             then public.work_order_stage_payment_status(wo.lab_organization_id,wo.id,'model') else null end,
                    'Paid_Modelare',
                        case when lower(trim(coalesce(wo.tehnician1_modelare,''))) = v_tech
                             then public.work_order_stage_payment_status(wo.lab_organization_id,wo.id,'modelare') else null end,
                    'Paid_Cer_Fin',
                        case when lower(trim(coalesce(wo.tehnician2_cer_fin,''))) = v_tech
                             then public.work_order_stage_payment_status(wo.lab_organization_id,wo.id,'cer_fin') else null end
                ) as obj
            from public.lab_work_orders wo
        cross join lateral public.work_order_item_scope(wo.lab_organization_id,wo.id,false) scope
            where wo.lab_organization_id = v_lab
              and v_tech <> ''
              and v_tech in (
                  lower(trim(coalesce(wo.tehnician_model,''))),
                  lower(trim(coalesce(wo.tehnician1_modelare,''))),
                  lower(trim(coalesce(wo.tehnician2_cer_fin,'')))
              )
            order by wo.id desc
            limit 500
        ) x;

        select coalesce(jsonb_agg(
            jsonb_build_object(
                'ID', tc.legacy_id,
                'Source_Row_No', tc.source_row_no,
                'Tehnician', tc.tehnician,
                'Tip_Lucrare', tc.tip_lucrare,
                'Etapa', tc.etapa,
                'Cost', tc.cost
            )
            order by tc.tip_lucrare, tc.etapa, tc.source_row_no
        ),'[]'::jsonb)
        into v_costs
        from public.lab_technician_costs tc
        where tc.lab_organization_id = v_lab
          and lower(trim(coalesce(tc.tehnician,''))) = v_tech;
    end if;

    return jsonb_build_object(
        'allowed', true,
        'identity', v_identity,
        'role', v_role,
        'history', v_history,
        'work_orders', v_orders,
        'contract_prices', v_prices,
        'technician_costs', v_costs,
        'work_types', v_types,
        'materials', v_materials
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_session_id text
-- END db/schema/20_functions/get_ai_context.sql

-- BEGIN db/schema/20_functions/get_app_identity.sql
-- Flowrise Supabase function: public.get_app_identity()
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.get_app_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    v_lab uuid := public.get_flowrise_lab_id();
    v_role text;
    v_role_display text;
    v_profile public.profiles%rowtype;
    v_perm public.role_permissions%rowtype;
begin
    select *
      into v_profile
    from public.profiles
    where id = auth.uid()
      and active = true
    limit 1;

    if not found then
        return jsonb_build_object('ok', false, 'message', 'Active profile not found');
    end if;

    v_role := public.effective_lab_role(v_lab);

    if v_role is null then
        return jsonb_build_object('ok', false, 'message', 'No active Flowrise role');
    end if;

    select *
      into v_perm
    from public.role_permissions
    where lower(role) = lower(v_role)
      and active = true
    limit 1;

    if not found then
        return jsonb_build_object('ok', false, 'message', 'Role permissions not found');
    end if;

    v_role_display := case lower(v_role)
        when 'admin' then 'Admin'
        when 'manager' then 'Manager'
        when 'technician' then 'Technician'
        when 'doctor' then 'Doctor'
        when 'dashboard' then 'Dashboard'
        else initcap(v_role)
    end;

    return jsonb_build_object(
        'ok', true,
        'lab_organization_id', v_lab,
        'user', jsonb_build_object(
            'User_ID', coalesce(v_profile.legacy_user_id, v_profile.username),
            'Email', coalesce(auth.jwt() ->> 'email', ''),
            'Name', coalesce(v_profile.display_name, v_profile.username),
            'Role', v_role_display,
            'Technician_Name', coalesce(v_profile.technician_name, ''),
            'Partner_Name', coalesce(v_profile.legacy_partner_name, ''),
            'Active', true
        ),
        'profile', jsonb_build_object(
            'id', v_profile.id,
            'username', v_profile.username,
            'display_name', v_profile.display_name,
            'legacy_user_id', v_profile.legacy_user_id,
            'active', v_profile.active
        ),
        'permissions', jsonb_build_object(
            'Can_View_Work_Orders', v_perm.can_view_work_orders,
            'Can_View_Production', v_perm.can_view_production,
            'Can_View_Partners', v_perm.can_view_partners,
            'Can_View_Technicians', v_perm.can_view_technicians,
            'Can_Create_Work_Orders', v_perm.can_create_work_orders,
            'Can_Edit_All_Work_Orders', v_perm.can_edit_all_work_orders,
            'Can_Edit_Own_Stage_Status', v_perm.can_edit_own_stage_status,
            'Can_Assign_Technicians', v_perm.can_assign_technicians,
            'Can_View_Client_Pricing', v_perm.can_view_client_pricing,
            'Can_View_Other_Technician_Costs', v_perm.can_view_other_technician_costs,
            'Can_View_Own_Technician_Cost', v_perm.can_view_own_technician_cost,
            'Can_Edit_Payment_Status', v_perm.can_edit_payment_status,
            'Can_Edit_Global_Status', v_perm.can_edit_global_status,
            'Can_Access_Backend', v_perm.can_access_backend,
            'Can_Edit_Partner_Work_Orders', v_perm.can_edit_partner_work_orders,
            'Work_Order_Scope', v_perm.work_order_scope,
            'AI_Flow', coalesce(v_perm.ai_flow, '')
        )
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments:
-- END db/schema/20_functions/get_app_identity.sql

