-- BEGIN db/schema/20_functions/get_my_chat_history.sql
-- Flowrise Supabase function: public.get_my_chat_history(p_session_id text, p_limit integer)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.get_my_chat_history(p_session_id text, p_limit integer DEFAULT 100)
 RETURNS TABLE(id bigint, user_id text, session_id text, role text, message text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        ch.id,
        ch.user_id,
        ch.session_id,
        ch.role,
        ch.message,
        ch.created_at
    from public.lab_chat_history ch
    where ch.lab_organization_id = public.get_flowrise_lab_id()
      and lower(coalesce(ch.user_id,'')) =
          lower(coalesce(public.current_legacy_user_id(),''))
      and ch.session_id = p_session_id
    order by ch.created_at asc nulls last, ch.id asc
    limit greatest(1,least(coalesce(p_limit,100),500));
$function$
;

-- Security definer: True
-- Return type: TABLE(id bigint, user_id text, session_id text, role text, message text, created_at timestamp with time zone)
-- Identity arguments: p_session_id text, p_limit integer
-- END db/schema/20_functions/get_my_chat_history.sql

-- BEGIN db/schema/20_functions/get_my_production.sql
-- Flowrise Supabase function: public.get_my_production(p_lab_organization_id uuid)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.get_my_production(p_lab_organization_id uuid)
 RETURNS TABLE(id bigint, deadline date, status text, nume_pacient text, nume_partener text, items jsonb, work_types text[], work_type_summary text, element_count numeric, locked boolean, tehnician_model text, tehnician1_modelare text, tehnician2_cer_fin text, status_model text, status_modelare text, status_cer_fin text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_is_management boolean := public.is_lab_management(p_lab_organization_id);
    v_is_dashboard boolean := public.is_lab_dashboard(p_lab_organization_id);
    v_is_technician boolean := public.is_lab_technician(p_lab_organization_id);
    v_is_doctor boolean := public.is_connected_doctor_for_lab(p_lab_organization_id);
begin
    if not (v_is_management or v_is_dashboard or v_is_technician or v_is_doctor) then
        raise exception 'Access denied';
    end if;

    return query
    select
        wo.id,
        wo.deadline,
        wo.status,
        wo.nume_pacient,
        wo.nume_partener,
        scope.items,scope.work_types,scope.work_type_summary,scope.element_count,
        wo.locked,

        wo.tehnician_model,
        wo.tehnician1_modelare,
        wo.tehnician2_cer_fin,

        wo.status_model,
        wo.status_modelare,
        wo.status_cer_fin
    from public.lab_work_orders wo
    cross join lateral public.work_order_item_scope(wo.lab_organization_id,wo.id,false) scope
    where wo.lab_organization_id = p_lab_organization_id
      and wo.archived_at is null
      and lower(wo.status) in ('not started','started','finished','shipped')
      and (
          v_is_management
          or v_is_dashboard
          or (
              v_is_technician
              and lower(trim(coalesce(public.current_technician_name(),''))) in (
                  lower(trim(coalesce(wo.tehnician_model,''))),
                  lower(trim(coalesce(wo.tehnician1_modelare,''))),
                  lower(trim(coalesce(wo.tehnician2_cer_fin,'')))
              )
          )
          or (
              v_is_doctor
              and public.doctor_matches_partner(wo.nume_partener)
          )
      )
    order by wo.deadline nulls last, wo.id desc;
end;
$function$
;
-- END db/schema/20_functions/get_my_production.sql

-- BEGIN db/schema/20_functions/get_my_salary.sql
CREATE OR REPLACE FUNCTION public.get_my_salary(p_lab_organization_id uuid)
RETURNS TABLE (
    work_order_id bigint,
    stage_key text,
    stage_label text,
    stage_status text,
    payment_status text,
    unit_cost numeric,
    amount numeric
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_technician text := trim(coalesce(public.current_technician_name(),''));
BEGIN
    IF NOT public.is_lab_technician(p_lab_organization_id) THEN RAISE EXCEPTION 'Technician access denied'; END IF;
    IF v_technician='' THEN RAISE EXCEPTION 'Technician profile mapping is missing'; END IF;

    RETURN QUERY
    SELECT a.work_order_id,
           CASE a.stage_key WHEN 'model' THEN 'Model' WHEN 'modelare' THEN 'Modelare' ELSE 'Cer_Fin' END,
           CASE a.stage_key WHEN 'model' THEN 'Model' WHEN 'modelare' THEN 'Modelare' ELSE 'Cer / Fin' END,
           CASE a.stage_key WHEN 'model' THEN coalesce(wo.status_model,'Not Started')
                            WHEN 'modelare' THEN coalesce(wo.status_modelare,'Not Started')
                            ELSE coalesce(wo.status_cer_fin,'Not Started') END,
           CASE WHEN public.assignment_agreed_amount(a.id) is not null AND coalesce(pay.paid,0)>=public.assignment_agreed_amount(a.id) THEN 'Paid' ELSE 'Not Paid' END,
           a.unit_cost,
           public.assignment_agreed_amount(a.id)
    FROM public.lab_work_order_stage_assignments a
    JOIN public.lab_work_orders wo
      ON wo.lab_organization_id=a.lab_organization_id AND wo.id=a.work_order_id
    LEFT JOIN LATERAL (
        SELECT coalesce(sum(p.amount),0)::numeric AS paid
        FROM public.technician_payments p WHERE p.assignment_id=a.id
    ) pay ON true
    WHERE a.lab_organization_id=p_lab_organization_id
      AND (a.technician_user_id=auth.uid() OR (
          a.technician_user_id is null AND lower(trim(a.technician_name))=lower(v_technician)
      ))
    ORDER BY a.work_order_id DESC,a.started_at DESC;
END;
$$;

REVOKE ALL ON FUNCTION public.get_my_salary(uuid) FROM public;
GRANT EXECUTE ON FUNCTION public.get_my_salary(uuid) TO authenticated;
-- END db/schema/20_functions/get_my_salary.sql

