-- BEGIN db/schema/20_functions/get_work_order_financial_history.sql
CREATE OR REPLACE FUNCTION public.get_work_order_financial_history(
    p_lab uuid,
    p_work_order_id bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_role text := public.effective_lab_role(p_lab);
    v_result jsonb;
BEGIN
    IF v_role NOT IN ('admin','manager','technician') THEN RAISE EXCEPTION 'Financial history access denied'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.lab_work_orders wo
        WHERE wo.lab_organization_id=p_lab AND wo.id=p_work_order_id
    ) THEN RAISE EXCEPTION 'Work Order not found'; END IF;
    IF v_role='technician' AND NOT EXISTS (
        SELECT 1 FROM public.lab_work_order_stage_assignments a
        WHERE a.lab_organization_id=p_lab AND a.work_order_id=p_work_order_id
          AND (
              a.technician_user_id=auth.uid()
              OR (
                  a.technician_user_id IS NULL
                  AND lower(trim(a.technician_name))=lower(trim(coalesce(public.current_technician_name(),'')))
              )
          )
    ) THEN RAISE EXCEPTION 'Financial history access denied'; END IF;

    SELECT jsonb_build_object(
        'Work_Order_ID',wo.id,
        'Sale_Price',case when v_role in ('admin','manager') then jsonb_build_object(
            'List_Price',wo.snapshot_list_price,
            'Final_Price',wo.snapshot_final_price,'Discount',wo.discount,
            'Source',wo.price_source,'Fixed_At',wo.price_fixed_at,'Migrated',wo.price_migrated
        ) else null end,
        'Assignments',coalesce((
            SELECT jsonb_agg(jsonb_build_object(
                'Assignment_ID',a.id,'Stage',a.stage_key,'Technician',a.technician_name,
                'Unit_Cost',a.unit_cost,'Quantity',a.quantity,'Agreed_Amount',public.assignment_agreed_amount(a.id),
                'Cost_Source',a.cost_source,'Fixed_At',a.fixed_at,'Started_At',a.started_at,
                'Ended_At',a.ended_at,'Migrated',a.migrated,
                'Original_Agreed_Amount',a.agreed_amount,
                'Adjustments',coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at,d.id) from public.lab_work_order_assignment_adjustments d where d.assignment_id=a.id),'[]'::jsonb),
                'Cost_Lines',coalesce((select jsonb_agg(to_jsonb(l) order by l.work_type)
                    from public.lab_work_order_assignment_cost_lines l where l.assignment_id=a.id),'[]'::jsonb),
                'Payments',coalesce((select jsonb_agg(jsonb_build_object(
                    'ID',p.id,'Amount',p.amount,'Currency',p.currency,'Paid_On',p.paid_on,
                    'Recorded_At',p.recorded_at,'Reversal_Of',p.reversal_of,
                    'Migration_Balance',p.migration_balance,'Note',p.note
                ) order by p.recorded_at) from public.technician_payments p where p.assignment_id=a.id),'[]'::jsonb)
            ) order by a.started_at
            FROM public.lab_work_order_stage_assignments a
            WHERE a.lab_organization_id=p_lab AND a.work_order_id=p_work_order_id
              AND (v_role in ('admin','manager') OR a.technician_user_id=auth.uid()
                   OR (a.technician_user_id is null AND lower(trim(a.technician_name))=lower(trim(coalesce(public.current_technician_name(),'')))))
        ),'[]'::jsonb)
    ) INTO v_result
    FROM public.lab_work_orders wo
    WHERE wo.lab_organization_id=p_lab AND wo.id=p_work_order_id;
    RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.get_work_order_financial_history(uuid,bigint) FROM public;
GRANT EXECUTE ON FUNCTION public.get_work_order_financial_history(uuid,bigint) TO authenticated;
-- END db/schema/20_functions/get_work_order_financial_history.sql

-- BEGIN db/schema/20_functions/get_work_order_reference_data.sql
-- Flowrise Supabase function: public.get_work_order_reference_data(p_lab_organization_id uuid)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.get_work_order_reference_data(p_lab_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_role text := public.effective_lab_role(p_lab_organization_id);
    v_work_types jsonb;
    v_technicians jsonb := '[]'::jsonb;
    v_prices jsonb := '[]'::jsonb;
begin
    if v_role is null then
        raise exception 'Access denied';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', wt.id,
                'tip_lucrare', wt.tip_lucrare,
                'active', wt.active
            )
            order by wt.tip_lucrare, wt.id
        ),
        '[]'::jsonb
    )
    into v_work_types
    from public.lab_work_types wt
    where wt.lab_organization_id = p_lab_organization_id
      and wt.active = true;

    if v_role in ('admin','manager','dashboard') then
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'username', p.username,
                    'display_name', p.display_name,
                    'technician_name', p.technician_name
                )
                order by coalesce(p.technician_name,p.display_name,p.username)
            ),
            '[]'::jsonb
        )
        into v_technicians
        from public.organization_memberships m
        join public.profiles p
          on p.id = m.user_id
        where m.organization_id = p_lab_organization_id
          and m.status = 'active'::public.membership_status
          and lower(m.role) = 'technician'
          and p.active = true;
    end if;

    if v_role in ('admin','manager') then
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'id', cp.id,
                    'contract', cp.contract,
                    'tip_lucrare', cp.tip_lucrare,
                    'pret', cp.pret
                )
                order by cp.contract, cp.tip_lucrare, cp.id
            ),
            '[]'::jsonb
        )
        into v_prices
        from public.lab_contract_work_prices cp
        where cp.lab_organization_id = p_lab_organization_id;
    end if;

    return jsonb_build_object(
        'role', v_role,
        'work_types', v_work_types,
        'technicians', v_technicians,
        'contract_prices', v_prices
    );
end;
$function$
;

-- Security definer: True
-- Return type: jsonb
-- Identity arguments: p_lab_organization_id uuid
-- END db/schema/20_functions/get_work_order_reference_data.sql

-- BEGIN db/schema/20_functions/has_org_role.sql
-- Flowrise Supabase function: public.has_org_role(p_organization_id uuid, p_roles text[])
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.has_org_role(p_organization_id uuid, p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1
        from public.organization_memberships as m
        join public.profiles as p
          on p.id = m.user_id
        where m.organization_id = p_organization_id
          and m.user_id = auth.uid()
          and m.status = 'active'::public.membership_status
          and p.active = true
          and lower(m.role) = any (
              select lower(x)
              from unnest(p_roles) as x
          )
    );
$function$
;

-- Security definer: True
-- Return type: boolean
-- Identity arguments: p_organization_id uuid, p_roles text[]
