-- BEGIN db/schema/20_functions/prepare_stage_reassignment.sql
-- Validate how an outstanding balance should remain on the assignment that is
-- about to be closed. Nothing is transferred to the new technician.
CREATE OR REPLACE FUNCTION public.prepare_stage_reassignment(
    p_lab uuid,
    p_work_order_id bigint,
    p_stage text,
    p_new_technician_name text,
    p_settlement text DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_stage text := lower(trim(coalesce(p_stage,'')));
    v_choice text := lower(trim(coalesce(p_settlement,'')));
    v_order public.lab_work_orders%rowtype;
    v_assignment public.lab_work_order_stage_assignments%rowtype;
    v_old_name text;
    v_new_name text := nullif(trim(coalesce(p_new_technician_name,'')),'');
    v_paid numeric;
    v_outstanding numeric;
BEGIN
    IF NOT public.is_lab_management(p_lab) THEN RAISE EXCEPTION 'Management access denied'; END IF;
    IF v_stage NOT IN ('model','modelare','cer_fin') THEN RAISE EXCEPTION 'Invalid stage'; END IF;

    SELECT * INTO v_order FROM public.lab_work_orders
    WHERE lab_organization_id=p_lab AND id=p_work_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;
    v_old_name := CASE v_stage WHEN 'model' THEN v_order.tehnician_model
        WHEN 'modelare' THEN v_order.tehnician1_modelare ELSE v_order.tehnician2_cer_fin END;
    IF lower(trim(coalesce(v_old_name,'')))=lower(trim(coalesce(v_new_name,''))) THEN RETURN true; END IF;

    SELECT * INTO v_assignment
    FROM public.lab_work_order_stage_assignments
    WHERE lab_organization_id=p_lab AND work_order_id=p_work_order_id
      AND stage_key=v_stage AND ended_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN RETURN true; END IF;

    SELECT coalesce(sum(amount),0) INTO v_paid
    FROM public.technician_payments WHERE assignment_id=v_assignment.id;
    v_outstanding := CASE WHEN public.assignment_agreed_amount(v_assignment.id) IS NULL THEN 0
        ELSE greatest(public.assignment_agreed_amount(v_assignment.id)-v_paid,0) END;
    IF v_outstanding<=0 THEN RETURN true; END IF;

    IF v_choice='pay_outstanding' THEN
        PERFORM public.set_stage_payment_status(p_lab,p_work_order_id,v_stage,'Paid');
    ELSIF v_choice='keep_outstanding' THEN
        NULL;
    ELSIF v_choice='' THEN
        RAISE EXCEPTION 'OUTSTANDING_ASSIGNMENT:%:%',v_stage,v_outstanding;
    ELSE
        RAISE EXCEPTION 'Settlement must be keep_outstanding or pay_outstanding';
    END IF;
    RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.prepare_stage_reassignment(uuid,bigint,text,text,text) FROM public,authenticated;
-- END db/schema/20_functions/prepare_stage_reassignment.sql

-- BEGIN db/schema/20_functions/record_technician_payment.sql
CREATE OR REPLACE FUNCTION public.record_technician_payment(
    p_assignment_id uuid,
    p_amount numeric,
    p_paid_on date,
    p_request_key text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_assignment public.lab_work_order_stage_assignments%rowtype;
    v_existing public.technician_payments%rowtype;
    v_paid numeric;
    v_outstanding numeric;
    v_id uuid;
BEGIN
    SELECT * INTO v_assignment FROM public.lab_work_order_stage_assignments
    WHERE id = p_assignment_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Technician assignment not found'; END IF;
    IF NOT public.is_lab_management(v_assignment.lab_organization_id) THEN
        RAISE EXCEPTION 'Management access denied';
    END IF;
    IF trim(coalesce(p_request_key,'')) = '' THEN RAISE EXCEPTION 'Payment request key is required'; END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be greater than zero'; END IF;
    IF p_paid_on IS NULL THEN RAISE EXCEPTION 'Payment date is required'; END IF;

    SELECT * INTO v_existing FROM public.technician_payments
    WHERE lab_organization_id=v_assignment.lab_organization_id AND request_key=p_request_key;
    IF FOUND THEN
        IF v_existing.recorded_by_user_id IS DISTINCT FROM auth.uid()
           OR v_existing.assignment_id<>p_assignment_id
           OR v_existing.amount<>round(p_amount,2)
           OR v_existing.paid_on IS DISTINCT FROM p_paid_on THEN
            RAISE EXCEPTION 'Payment request key was already used for another payment';
        END IF;
        RETURN v_existing.id;
    END IF;
    IF public.assignment_agreed_amount(v_assignment.id) IS NULL THEN RAISE EXCEPTION 'Assignment cost is missing'; END IF;

    SELECT coalesce(sum(amount),0) INTO v_paid
    FROM public.technician_payments WHERE assignment_id=p_assignment_id;
    v_outstanding := public.assignment_agreed_amount(v_assignment.id) - v_paid;
    IF p_amount > v_outstanding THEN RAISE EXCEPTION 'Payment exceeds outstanding amount'; END IF;

    INSERT INTO public.technician_payments (
        lab_organization_id,assignment_id,amount,paid_on,recorded_by_user_id,request_key
    ) VALUES (
        v_assignment.lab_organization_id,p_assignment_id,round(p_amount,2),p_paid_on,auth.uid(),p_request_key
    ) RETURNING id INTO v_id;

    INSERT INTO public.work_order_financial_audit (
        lab_organization_id,work_order_id,entity_type,entity_id,action,before_value,after_value,changed_by_user_id
    ) VALUES (
        v_assignment.lab_organization_id,v_assignment.work_order_id,'technician_payment',v_id::text,
        'payment',jsonb_build_object('outstanding',v_outstanding),
        jsonb_build_object('amount',round(p_amount,2),'paid_on',p_paid_on),auth.uid()
    );
    RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.record_technician_payment(uuid,numeric,date,text) FROM public;
GRANT EXECUTE ON FUNCTION public.record_technician_payment(uuid,numeric,date,text) TO authenticated;
-- END db/schema/20_functions/record_technician_payment.sql

-- BEGIN db/schema/20_functions/replace_work_order_items.sql
-- Saves per-tooth price snapshots. Unchanged tooth/type pairs retain their
-- original price even when the contract catalog changes.
create or replace function public.replace_work_order_items(
    p_lab_organization_id uuid,
    p_work_order_id bigint,
    p_items jsonb,
    p_requested_contract text default 'General'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_role text := public.effective_lab_role(p_lab_organization_id);
    v_order public.lab_work_orders%rowtype;
    v_first_contract text;
    v_count numeric;
    v_scope_before jsonb;
    v_scope_after jsonb;
    v_list numeric;
    v_final numeric;
    v_lines jsonb;
    v_before_lines jsonb;
    v_matched_all boolean;
    v_order_price_source text;
    v_order_price_fixed_at timestamptz;
begin
    if v_role not in ('admin','manager','doctor','technician') then
        raise exception 'Work Order item update denied';
    end if;
    if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then
        raise exception 'Items must be a JSON array';
    end if;

    select * into v_order
    from public.lab_work_orders
    where lab_organization_id=p_lab_organization_id and id=p_work_order_id
    for update;
    if not found then raise exception 'Work Order not found'; end if;
    if v_role='technician' then
        p_requested_contract:=coalesce(nullif(trim(v_order.contract),''),'General');
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
        'tooth_number',tooth_number,'work_type',work_type,'quantity',quantity,
        'contract',contract,'unit_price',unit_price,'subtotal',line_total,
        'matched',unit_price is not null,'price_source',price_source
    ) order by tooth_number),'[]'::jsonb)
    into v_before_lines
    from public.lab_work_order_items
    where lab_organization_id=p_lab_organization_id and work_order_id=p_work_order_id;

    if v_role='doctor' then
        if not public.doctor_matches_partner(v_order.nume_partener) then raise exception 'Work Order access denied'; end if;
        if v_order.locked then raise exception 'Work Order is locked'; end if;
        if lower(trim(coalesce(v_order.status,''))) <> 'not started' then
            raise exception 'Doctor can edit only Not Started Work Orders';
        end if;
    elsif v_role='technician' then
        if not public.can_access_work_order(p_lab_organization_id,p_work_order_id) then raise exception 'Work Order access denied'; end if;
        if v_order.locked then raise exception 'Work Order is locked'; end if;
    elsif not public.is_lab_management(p_lab_organization_id) then
        raise exception 'Management access denied';
    end if;

    select count(*) into v_count from jsonb_array_elements(coalesce(p_items,'[]'::jsonb));
    if coalesce(v_count,0)=0 then raise exception 'At least one configured tooth is required'; end if;
    if exists (
        select 1
        from jsonb_array_elements(p_items) item
        where trim(coalesce(item->>'work_type','')) = ''
           or coalesce((item->>'tooth_number')::integer,0) / 10 not between 1 and 4
           or coalesce((item->>'tooth_number')::integer,0) % 10 not between 1 and 8
           or not exists (
               select 1 from public.lab_work_types wt
               where wt.lab_organization_id=p_lab_organization_id and wt.active=true
                 and lower(trim(wt.tip_lucrare))=lower(trim(item->>'work_type'))
           )
    ) then raise exception 'Every tooth requires a valid active Work Type'; end if;
    if exists (
        select 1 from jsonb_array_elements(p_items) item
        group by (item->>'tooth_number')::integer having count(*)>1
    ) then raise exception 'Duplicate tooth number'; end if;

    select coalesce(jsonb_agg(jsonb_build_object('work_type',work_type,'quantity',quantity) order by work_type),'[]'::jsonb)
    into v_scope_before from (select work_type,sum(quantity) quantity from public.lab_work_order_items
    where lab_organization_id=p_lab_organization_id and work_order_id=p_work_order_id group by work_type) scope;

    with incoming as (
        select (item->>'tooth_number')::integer as tooth_number,
               trim(item->>'work_type') as work_type
        from jsonb_array_elements(p_items) item
    ), resolved as (
        select i.tooth_number,coalesce(old.work_type,i.work_type) as work_type,
               coalesce(old.quantity,1) as quantity,
               case when old.tooth_number is not null then old.line_total else round(price.pret,2) end as line_total,
               case when old.tooth_number is not null then old.contract
                    else coalesce(price.contract,'General') end as contract,
               case when old.tooth_number is not null then old.unit_price
                    else price.pret end as unit_price,
               case when old.tooth_number is not null then old.price_source
                    when price.pret is null then 'missing' else 'catalog' end as price_source,
               case when old.tooth_number is not null then old.price_fixed_at else now() end as price_fixed_at,
               case when old.tooth_number is not null then old.price_migrated else false end as price_migrated
        from incoming i
        left join public.lab_work_order_items old
          on old.lab_organization_id=p_lab_organization_id
         and old.work_order_id=p_work_order_id
         and old.tooth_number=i.tooth_number
         and lower(trim(old.work_type))=lower(i.work_type)
        left join lateral (
            select cp.contract,cp.pret
            from public.lab_contract_work_prices cp
            where cp.lab_organization_id=p_lab_organization_id
              and lower(trim(cp.tip_lucrare))=lower(i.work_type)
              and lower(trim(cp.contract)) in (
                  lower(trim(v_order.nume_partener)),
                  lower(coalesce(nullif(trim(p_requested_contract),''),'General')),
                  'general'
              )
            order by case
                when lower(trim(cp.contract))=lower(trim(v_order.nume_partener)) then 0
                when lower(trim(cp.contract))=lower(coalesce(nullif(trim(p_requested_contract),''),'General')) then 1
                else 2
            end, cp.id
            limit 1
        ) price on true
    )
    insert into public.lab_work_order_items (
        lab_organization_id,work_order_id,tooth_number,work_type,contract,
        unit_price,quantity,line_total,price_source,price_fixed_at,price_migrated,
        created_by_user_id,updated_by_user_id,updated_at
    )
    select p_lab_organization_id,p_work_order_id,tooth_number,work_type,contract,
           unit_price,quantity,line_total,
           price_source,price_fixed_at,price_migrated,
           public.current_legacy_user_id(),public.current_legacy_user_id(),now()
    from resolved
    on conflict (lab_organization_id,work_order_id,tooth_number)
    do update set
        work_type=excluded.work_type,contract=excluded.contract,
        unit_price=excluded.unit_price,quantity=excluded.quantity,
        line_total=excluded.line_total,price_source=excluded.price_source,
        price_fixed_at=excluded.price_fixed_at,price_migrated=excluded.price_migrated,
        updated_by_user_id=excluded.updated_by_user_id,updated_at=now();

    delete from public.lab_work_order_items existing
    where existing.lab_organization_id=p_lab_organization_id
      and existing.work_order_id=p_work_order_id
      and not exists (
          select 1 from jsonb_array_elements(p_items) item
          where (item->>'tooth_number')::integer=existing.tooth_number
      );

    select contract into v_first_contract
    from public.lab_work_order_items
    where lab_organization_id=p_lab_organization_id and work_order_id=p_work_order_id
    order by tooth_number limit 1;

    select sum(quantity),
           case when bool_and(line_total is not null) then round(sum(line_total),2) else null end,
           coalesce(bool_and(unit_price is not null),false),
           coalesce(jsonb_agg(jsonb_build_object(
               'tooth_number',tooth_number,'work_type',work_type,'quantity',quantity,
               'contract',contract,'unit_price',unit_price,'subtotal',line_total,
               'matched',unit_price is not null,'price_source',price_source
           ) order by tooth_number),'[]'::jsonb),
           case when bool_and(price_source='admin_override') then 'admin_override'
                else 'item_snapshots' end,
           max(price_fixed_at)
      into v_count,v_list,v_matched_all,v_lines,v_order_price_source,v_order_price_fixed_at
    from public.lab_work_order_items
    where lab_organization_id=p_lab_organization_id and work_order_id=p_work_order_id;

    v_final := case when v_list is null then null
        else round(v_list*(1-(case when v_role='doctor' then 0 else v_order.discount end)/100),2) end;

    update public.lab_work_orders
    set contract=coalesce(v_first_contract,'General'),
        discount=case when v_role='doctor' then 0 else discount end,
        snapshot_list_price=v_list,snapshot_final_price=v_final,
        price_source=v_order_price_source,price_fixed_at=coalesce(v_order_price_fixed_at,now()),price_migrated=false,
        updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
    where lab_organization_id=p_lab_organization_id and id=p_work_order_id;

    if (v_order.snapshot_list_price,v_order.snapshot_final_price,v_before_lines)
       is distinct from (v_list,v_final,v_lines) then
        insert into public.work_order_financial_audit (
            lab_organization_id,work_order_id,entity_type,entity_id,action,
            before_value,after_value,changed_by_user_id
        ) values (
            p_lab_organization_id,p_work_order_id,'work_order_price',p_work_order_id::text,
            'item_change',
            jsonb_build_object(
                'list_price',v_order.snapshot_list_price,'final_price',v_order.snapshot_final_price,
                'quantity',(select sum((item->>'quantity')::numeric) from jsonb_array_elements(v_before_lines) item),
                'items',v_before_lines
            ),
            jsonb_build_object(
                'list_price',v_list,'final_price',v_final,'quantity',v_count,'items',v_lines
            ),auth.uid()
        );
    end if;

    select coalesce(jsonb_agg(jsonb_build_object('work_type',work_type,'quantity',quantity) order by work_type),'[]'::jsonb)
    into v_scope_after from (select work_type,sum(quantity) quantity from public.lab_work_order_items
    where lab_organization_id=p_lab_organization_id and work_order_id=p_work_order_id group by work_type) scope;
    if v_scope_before is distinct from v_scope_after then
        perform public.adjust_work_order_scope_costs(p_lab_organization_id,p_work_order_id,v_scope_before,v_scope_after);
        insert into public.work_order_financial_audit(lab_organization_id,work_order_id,entity_type,entity_id,action,before_value,after_value,changed_by_user_id)
        values(p_lab_organization_id,p_work_order_id,'work_order_scope',p_work_order_id::text,'scope_change',v_scope_before,v_scope_after,auth.uid());
    end if;

    if v_role='technician' then
        return (select to_jsonb(scope) from public.work_order_item_scope(p_lab_organization_id,p_work_order_id,false) scope);
    end if;
    return jsonb_build_object(
        'lines',v_lines,'element_count',v_count,'list_price',v_list,
        'discount',case when v_role='doctor' then 0 else v_order.discount end,
        'final_price',v_final,'matched_all',v_matched_all,
        'partner_name',v_order.nume_partener
    );
end;
$$;

revoke all on function public.replace_work_order_items(uuid,bigint,jsonb,text) from public,anon,authenticated;
-- END db/schema/20_functions/replace_work_order_items.sql

-- BEGIN db/schema/20_functions/resolve_effective_work_order_contract.sql
-- Flowrise Supabase function: public.resolve_effective_work_order_contract
-- Sourced from SUPABASE V18.14 Doctor Contract Pricing.sql.
-- Includes the complete function definition and available ACL statements.

create or replace function public.resolve_effective_work_order_contract(
    p_lab_organization_id uuid,
    p_partner_name text,
    p_work_type text
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_contract text;
begin
    select cp.contract into v_contract
    from public.lab_contract_work_prices cp
    where cp.lab_organization_id=p_lab_organization_id
      and lower(trim(cp.contract))=lower(trim(coalesce(p_partner_name,'')))
      and lower(trim(cp.tip_lucrare))=lower(trim(coalesce(p_work_type,'')))
    order by cp.id
    limit 1;

    if v_contract is not null then return v_contract; end if;

    select cp.contract into v_contract
    from public.lab_contract_work_prices cp
    where cp.lab_organization_id=p_lab_organization_id
      and lower(trim(cp.contract))='general'
      and lower(trim(cp.tip_lucrare))=lower(trim(coalesce(p_work_type,'')))
    order by cp.id
    limit 1;

    return coalesce(v_contract,'General');
end;
$$;

revoke all on function public.resolve_effective_work_order_contract(uuid,text,text) from public;
-- END db/schema/20_functions/resolve_effective_work_order_contract.sql

-- BEGIN db/schema/20_functions/resolve_work_order_price_snapshot.sql
CREATE OR REPLACE FUNCTION public.resolve_work_order_price_snapshot(
    p_lab uuid,
    p_partner text,
    p_contract text,
    p_work_type text,
    p_quantity numeric,
    p_discount numeric
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_price numeric;
    v_contract text;
    v_quantity numeric := greatest(coalesce(p_quantity, 0), 0);
    v_discount numeric := greatest(0, least(100, coalesce(p_discount, 0)));
BEGIN
    IF public.effective_lab_role(p_lab) NOT IN ('admin', 'manager', 'doctor', 'technician') THEN
        RAISE EXCEPTION 'Price resolution denied';
    END IF;

    SELECT cp.pret, cp.contract
      INTO v_price, v_contract
    FROM public.lab_contract_work_prices cp
    WHERE cp.lab_organization_id = p_lab
      AND lower(trim(cp.tip_lucrare)) = lower(trim(coalesce(p_work_type, '')))
      AND lower(trim(cp.contract)) IN (
          lower(trim(coalesce(p_contract, ''))),
          lower(trim(coalesce(p_partner, ''))),
          'general'
      )
    ORDER BY CASE
        WHEN lower(trim(cp.contract)) = lower(trim(coalesce(p_contract, ''))) THEN 0
        WHEN lower(trim(cp.contract)) = lower(trim(coalesce(p_partner, ''))) THEN 1
        ELSE 2
    END, cp.id
    LIMIT 1;

    RETURN jsonb_build_object(
        'unit_price', v_price,
        'list_price', CASE WHEN v_price IS NULL THEN NULL ELSE round(v_price * v_quantity, 2) END,
        'final_price', CASE WHEN v_price IS NULL THEN NULL ELSE round(v_price * v_quantity * (1 - v_discount / 100), 2) END,
        'matched_contract', v_contract,
        'price_source', CASE WHEN v_price IS NULL THEN 'missing' ELSE 'catalog' END
    );
END;
$$;

REVOKE ALL ON FUNCTION public.resolve_work_order_price_snapshot(uuid,text,text,text,numeric,numeric) FROM public;
REVOKE ALL ON FUNCTION public.resolve_work_order_price_snapshot(uuid,text,text,text,numeric,numeric) FROM authenticated;
-- END db/schema/20_functions/resolve_work_order_price_snapshot.sql

-- BEGIN db/schema/20_functions/resolve_work_order_technician_costs.sql
-- Canonical catalog lookup shared by assignment creation and scope adjustments.
CREATE OR REPLACE FUNCTION public.resolve_technician_unit_cost(
    p_lab uuid,
    p_technician_name text,
    p_work_type text,
    p_stage text
)
RETURNS numeric
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT tc.cost
    FROM public.lab_technician_costs tc
    WHERE tc.lab_organization_id = p_lab
      AND regexp_replace(lower(trim(tc.tehnician)), '[[:space:]]+', ' ', 'g')
          = regexp_replace(lower(trim(p_technician_name)), '[[:space:]]+', ' ', 'g')
      AND regexp_replace(lower(trim(tc.tip_lucrare)), '[[:space:]]+', ' ', 'g')
          = regexp_replace(lower(trim(p_work_type)), '[[:space:]]+', ' ', 'g')
      AND CASE lower(trim(p_stage))
          WHEN 'model' THEN regexp_replace(lower(coalesce(tc.etapa,'')), '[^a-z0-9]', '', 'g') = 'model'
          WHEN 'modelare' THEN regexp_replace(lower(coalesce(tc.etapa,'')), '[^a-z0-9]', '', 'g') = 'modelare'
          WHEN 'cer_fin' THEN regexp_replace(lower(coalesce(tc.etapa,'')), '[^a-z0-9]', '', 'g')
              IN ('cerfin','ceramicafinisare','ceramicfinisare')
          ELSE false
      END
    ORDER BY tc.source_row_no
    LIMIT 1
$$;

REVOKE ALL ON FUNCTION public.resolve_technician_unit_cost(uuid,text,text,text) FROM public,authenticated;

-- One row per selected work type. Quantity is the number of configured teeth
-- carrying that type; amount is the frozen technician cost for the stage.
CREATE OR REPLACE FUNCTION public.resolve_work_order_technician_costs(
    p_lab uuid,
    p_work_order_id bigint,
    p_stage text,
    p_technician_name text
)
RETURNS TABLE (
    work_type text,
    quantity numeric,
    unit_cost numeric,
    amount numeric,
    cost_source text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    WITH normalized_scope AS (
        SELECT i.work_type,i.quantity,
               regexp_replace(lower(trim(i.work_type)), '[[:space:]]+', ' ', 'g') AS work_type_key
        FROM public.lab_work_order_items i
        WHERE i.lab_organization_id = p_lab
          AND i.work_order_id = p_work_order_id
    ), scope AS (
        SELECT min(work_type) AS work_type,work_type_key,sum(quantity)::numeric AS quantity
        FROM normalized_scope
        GROUP BY work_type_key
    )
    SELECT scope.work_type,
           scope.quantity,
           tc.cost AS unit_cost,
           CASE WHEN tc.cost IS NULL THEN NULL ELSE round(tc.cost * scope.quantity, 2) END AS amount,
           CASE WHEN tc.cost IS NULL THEN 'missing' ELSE 'catalog' END AS cost_source
    FROM scope
    LEFT JOIN LATERAL (
        SELECT public.resolve_technician_unit_cost(
            p_lab,p_technician_name,scope.work_type,p_stage
        ) AS cost
    ) tc ON true
    ORDER BY scope.work_type
$$;

REVOKE ALL ON FUNCTION public.resolve_work_order_technician_costs(uuid,bigint,text,text) FROM public,authenticated;
-- END db/schema/20_functions/resolve_work_order_technician_costs.sql

-- BEGIN db/schema/20_functions/reverse_technician_payment.sql
CREATE OR REPLACE FUNCTION public.reverse_technician_payment(
    p_payment_id uuid,
    p_reason text,
    p_request_key text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_payment public.technician_payments%rowtype;
    v_assignment public.lab_work_order_stage_assignments%rowtype;
    v_existing public.technician_payments%rowtype;
    v_id uuid;
BEGIN
    SELECT * INTO v_payment FROM public.technician_payments WHERE id=p_payment_id FOR UPDATE;
    IF NOT FOUND OR v_payment.amount <= 0 THEN RAISE EXCEPTION 'Reversible payment not found'; END IF;
    SELECT * INTO v_assignment FROM public.lab_work_order_stage_assignments WHERE id=v_payment.assignment_id;
    IF NOT public.is_lab_management(v_payment.lab_organization_id) THEN RAISE EXCEPTION 'Management access denied'; END IF;
    IF trim(coalesce(p_reason,'')) = '' THEN RAISE EXCEPTION 'Reversal reason is required'; END IF;
    IF trim(coalesce(p_request_key,'')) = '' THEN RAISE EXCEPTION 'Reversal request key is required'; END IF;

    SELECT * INTO v_existing FROM public.technician_payments
    WHERE lab_organization_id=v_payment.lab_organization_id AND request_key=p_request_key;
    IF FOUND THEN
        IF v_existing.recorded_by_user_id IS DISTINCT FROM auth.uid()
           OR v_existing.reversal_of IS DISTINCT FROM p_payment_id THEN
            RAISE EXCEPTION 'Reversal request key was already used for another payment';
        END IF;
        RETURN v_existing.id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.technician_payments WHERE reversal_of=p_payment_id) THEN
        RAISE EXCEPTION 'Payment is already reversed';
    END IF;

    INSERT INTO public.technician_payments (
        lab_organization_id,assignment_id,amount,paid_on,recorded_by_user_id,
        request_key,reversal_of,note
    ) VALUES (
        v_payment.lab_organization_id,v_payment.assignment_id,-v_payment.amount,
        (current_timestamp at time zone 'Europe/Bucharest')::date,auth.uid(),p_request_key,p_payment_id,trim(p_reason)
    ) RETURNING id INTO v_id;

    INSERT INTO public.work_order_financial_audit (
        lab_organization_id,work_order_id,entity_type,entity_id,action,before_value,after_value,changed_by_user_id
    ) VALUES (
        v_payment.lab_organization_id,v_assignment.work_order_id,'technician_payment',v_id::text,
        'reversal',to_jsonb(v_payment),jsonb_build_object('reason',trim(p_reason),'amount',-v_payment.amount),auth.uid()
    );
    RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.reverse_technician_payment(uuid,text,text) FROM public;
GRANT EXECUTE ON FUNCTION public.reverse_technician_payment(uuid,text,text) TO authenticated;
-- END db/schema/20_functions/reverse_technician_payment.sql

-- BEGIN db/schema/20_functions/sanitize_tooth_details.sql
-- Remove obsolete clinical keys recursively, including the __case entry.
CREATE OR REPLACE FUNCTION public.sanitize_tooth_details(p_details jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
DECLARE v_result jsonb;
BEGIN
    IF jsonb_typeof(p_details)='object' THEN
        SELECT coalesce(jsonb_object_agg(key,public.sanitize_tooth_details(value)),'{}'::jsonb)
        INTO v_result FROM jsonb_each(p_details)
        WHERE lower(key) NOT IN ('material','tip_lucrare','nr_elemente');
        RETURN v_result;
    ELSIF jsonb_typeof(p_details)='array' THEN
        SELECT coalesce(jsonb_agg(public.sanitize_tooth_details(value)),'[]'::jsonb)
        INTO v_result FROM jsonb_array_elements(p_details);
        RETURN v_result;
    END IF;
    RETURN p_details;
END; $$;
REVOKE ALL ON FUNCTION public.sanitize_tooth_details(jsonb) FROM public,authenticated;
-- END db/schema/20_functions/sanitize_tooth_details.sql

-- BEGIN db/schema/20_functions/save_my_work_order_case.sql
CREATE OR REPLACE FUNCTION public.save_my_work_order_case(
    p_lab_organization_id uuid,p_work_order_id bigint,
    p_status_model text,p_status_modelare text,p_status_cer_fin text,
    p_items jsonb,p_case jsonb DEFAULT '{}'::jsonb)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_order public.lab_work_orders%rowtype;
BEGIN
    IF NOT public.is_lab_technician(p_lab_organization_id) THEN RAISE EXCEPTION 'Technician access denied'; END IF;
    IF NOT public.can_access_work_order(p_lab_organization_id,p_work_order_id) THEN RAISE EXCEPTION 'Work Order access denied'; END IF;
    SELECT * INTO v_order FROM public.lab_work_orders WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;
    IF v_order.locked THEN RAISE EXCEPTION 'Work Order is locked'; END IF;
    PERFORM public.replace_work_order_items(p_lab_organization_id,p_work_order_id,p_items,v_order.contract);
    IF p_status_model IS NOT NULL THEN PERFORM public.update_my_stage_status(p_lab_organization_id,p_work_order_id,'model',p_status_model); END IF;
    IF p_status_modelare IS NOT NULL THEN PERFORM public.update_my_stage_status(p_lab_organization_id,p_work_order_id,'modelare',p_status_modelare); END IF;
    IF p_status_cer_fin IS NOT NULL THEN PERFORM public.update_my_stage_status(p_lab_organization_id,p_work_order_id,'cer_fin',p_status_cer_fin); END IF;
    RETURN public.save_work_order_clinical_case(p_lab_organization_id,p_work_order_id,p_case);
END; $$;
REVOKE ALL ON FUNCTION public.save_my_work_order_case(uuid,bigint,text,text,text,jsonb,jsonb) FROM public;
GRANT EXECUTE ON FUNCTION public.save_my_work_order_case(uuid,bigint,text,text,text,jsonb,jsonb) TO authenticated;
-- END db/schema/20_functions/save_my_work_order_case.sql

-- BEGIN db/schema/20_functions/save_work_order_clinical_case.sql
-- Internal writer shared by all atomic role RPCs. Tooth scope always comes from items.
CREATE OR REPLACE FUNCTION public.save_work_order_clinical_case(p_lab uuid,p_order_id bigint,p_case jsonb DEFAULT '{}'::jsonb)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
    v_order public.lab_work_orders%rowtype;
    v_id bigint;
    v_case public.lab_patient_cases%rowtype;
    v_details jsonb;
    v_teeth text;
    v_case_metadata jsonb;
    v_key text;
BEGIN
    p_case:=coalesce(p_case,'{}'::jsonb);
    IF jsonb_typeof(p_case)<>'object' THEN RAISE EXCEPTION 'Clinical case must be an object'; END IF;
    FOR v_key IN SELECT jsonb_object_keys(p_case) LOOP
        IF v_key NOT IN ('tooth_details','tooth_details_json','clinic_note','shade','method','production_notes') THEN
            RAISE EXCEPTION 'Unsupported clinical case field: %',v_key;
        END IF;
        IF v_key IN ('clinic_note','shade','method','production_notes') AND jsonb_typeof(p_case->v_key) NOT IN ('string','null') THEN
            RAISE EXCEPTION 'Clinical case field % must be text',v_key;
        END IF;
    END LOOP;
    IF p_case ? 'tooth_details' AND p_case ? 'tooth_details_json' THEN
        RAISE EXCEPTION 'Supply tooth_details or tooth_details_json, not both';
    END IF;
    SELECT * INTO v_order FROM public.lab_work_orders
    WHERE lab_organization_id=p_lab AND id=p_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;
    SELECT * INTO v_case FROM public.lab_patient_cases
    WHERE lab_organization_id=p_lab AND work_order_id=p_order_id ORDER BY id LIMIT 1;
    v_id:=v_case.id;
    IF v_id IS NULL THEN
        v_id:=p_order_id;
        IF EXISTS(SELECT 1 FROM public.lab_patient_cases WHERE lab_organization_id=p_lab AND id=v_id) THEN
            SELECT coalesce(max(id),0)+1 INTO v_id FROM public.lab_patient_cases WHERE lab_organization_id=p_lab;
        END IF;
    END IF;
    v_details:=public.sanitize_tooth_details(coalesce(
        p_case->'tooth_details',
        CASE WHEN jsonb_typeof(p_case->'tooth_details_json')='string' THEN (p_case->>'tooth_details_json')::jsonb
             ELSE p_case->'tooth_details_json' END,
        nullif(v_case.tooth_details_json,'')::jsonb,'{}'::jsonb));
    IF jsonb_typeof(v_details)<>'object' THEN RAISE EXCEPTION 'Tooth details must be an object'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_each(v_details) d
        WHERE (d.key<>'__case' AND d.key !~ '^[1-4][1-8]$') OR jsonb_typeof(d.value)<>'object') THEN
        RAISE EXCEPTION 'Tooth details must map FDI numbers or __case to objects';
    END IF;
    v_case_metadata:=coalesce(v_details->'__case','{}'::jsonb);
    -- Discard stale tooth entries and overwrite clinical work types with canonical scope.
    SELECT coalesce(jsonb_object_agg(i.tooth_number::text,
        coalesce(v_details->i.tooth_number::text,'{}'::jsonb)||jsonb_build_object('work_type',i.work_type,'type',i.work_type)),'{}'::jsonb),
        string_agg(i.tooth_number::text,',' ORDER BY i.tooth_number)
    INTO v_details,v_teeth FROM public.lab_work_order_items i
    WHERE i.lab_organization_id=p_lab AND i.work_order_id=p_order_id;
    IF v_case_metadata<>'{}'::jsonb THEN v_details:=v_details||jsonb_build_object('__case',v_case_metadata); END IF;
    INSERT INTO public.lab_patient_cases(lab_organization_id,id,work_order_id,nume_pacient,nume_partener,
        deadline,selected_teeth,tooth_details_json,shade,method,clinic_note,production_notes,
        created_by_user_id,created_at,updated_by_user_id,updated_at)
    VALUES(p_lab,v_id,p_order_id,v_order.nume_pacient,v_order.nume_partener,v_order.deadline,v_teeth,v_details::text,
        coalesce(p_case->>'shade',v_case.shade),coalesce(p_case->>'method',v_case.method),
        coalesce(p_case->>'clinic_note',v_case.clinic_note),
        CASE WHEN public.is_lab_management(p_lab) THEN coalesce(p_case->>'production_notes',v_case.production_notes) ELSE v_case.production_notes END,
        public.current_legacy_user_id(),now(),public.current_legacy_user_id(),now())
    ON CONFLICT(lab_organization_id,id) DO UPDATE SET
        nume_pacient=excluded.nume_pacient,nume_partener=excluded.nume_partener,deadline=excluded.deadline,
        selected_teeth=excluded.selected_teeth,tooth_details_json=excluded.tooth_details_json,
        shade=excluded.shade,method=excluded.method,clinic_note=excluded.clinic_note,production_notes=excluded.production_notes,
        updated_by_user_id=excluded.updated_by_user_id,updated_at=excluded.updated_at;
    RETURN v_id;
END; $$;
REVOKE ALL ON FUNCTION public.save_work_order_clinical_case(uuid,bigint,jsonb) FROM public,authenticated;
-- END db/schema/20_functions/save_work_order_clinical_case.sql

-- BEGIN db/schema/20_functions/set_stage_payment_status.sql
CREATE OR REPLACE FUNCTION public.set_stage_payment_status(
    p_lab_organization_id uuid,
    p_work_order_id bigint,
    p_stage text,
    p_paid_status text
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_stage text := lower(trim(coalesce(p_stage,'')));
    v_paid text := trim(coalesce(p_paid_status,''));
    v_order public.lab_work_orders%rowtype;
    v_current text;
    v_technician text;
    v_assignment public.lab_work_order_stage_assignments%rowtype;
    v_net_paid numeric;
    v_outstanding numeric;
    v_payment_id uuid;
BEGIN
    IF NOT public.is_lab_management(p_lab_organization_id) THEN
        RAISE EXCEPTION 'Management access denied';
    END IF;
    IF v_stage NOT IN ('model','modelare','cer_fin') THEN RAISE EXCEPTION 'Invalid stage'; END IF;
    IF lower(v_paid) NOT IN ('paid','not paid') THEN RAISE EXCEPTION 'Payment status must be Paid or Not Paid'; END IF;

    SELECT * INTO v_order FROM public.lab_work_orders
    WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;

    v_technician := case v_stage when 'model' then v_order.tehnician_model
        when 'modelare' then v_order.tehnician1_modelare else v_order.tehnician2_cer_fin end;

    SELECT * INTO v_assignment FROM public.lab_work_order_stage_assignments
    WHERE lab_organization_id=p_lab_organization_id AND work_order_id=p_work_order_id
      AND stage_key=v_stage AND ended_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN
        PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,v_stage,v_technician);
        SELECT * INTO v_assignment FROM public.lab_work_order_stage_assignments
        WHERE lab_organization_id=p_lab_organization_id AND work_order_id=p_work_order_id
          AND stage_key=v_stage AND ended_at IS NULL FOR UPDATE;
    END IF;
    IF v_assignment.id IS NULL THEN RAISE EXCEPTION 'Technician assignment is required before payment'; END IF;

    SELECT coalesce(sum(amount),0) INTO v_net_paid
    FROM public.technician_payments WHERE assignment_id=v_assignment.id;
    v_outstanding := public.assignment_agreed_amount(v_assignment.id) - v_net_paid;
    v_current := public.work_order_stage_payment_status(p_lab_organization_id,p_work_order_id,v_stage);

    IF lower(v_paid)='paid' THEN
        IF public.assignment_agreed_amount(v_assignment.id) IS NULL THEN RAISE EXCEPTION 'Assignment cost is missing'; END IF;
        IF v_outstanding > 0 THEN
            PERFORM public.record_technician_payment(
                v_assignment.id,v_outstanding,(current_timestamp at time zone 'Europe/Bucharest')::date,
                'legacy-paid:'||v_assignment.id::text||':'||txid_current()::text
            );
        END IF;
    ELSIF v_current='Paid' THEN
        SELECT p.id INTO v_payment_id
        FROM public.technician_payments p
        WHERE p.assignment_id=v_assignment.id AND p.amount>0
          AND p.request_key LIKE 'legacy-paid:%'
          AND NOT EXISTS (SELECT 1 FROM public.technician_payments r WHERE r.reversal_of=p.id)
        ORDER BY p.recorded_at DESC LIMIT 1;
        IF v_payment_id IS NOT NULL THEN
            PERFORM public.reverse_technician_payment(
                v_payment_id,'Legacy payment status changed to Not Paid',
                'legacy-reversal:'||v_payment_id::text
            );
        END IF;
    END IF;

    -- Keep compatibility flags consistent even when no payment action was needed.
    v_paid := public.work_order_stage_payment_status(p_lab_organization_id,p_work_order_id,v_stage);
    IF v_stage='model' THEN
        UPDATE public.lab_work_orders SET paid_model=v_paid,updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;
    ELSIF v_stage='modelare' THEN
        UPDATE public.lab_work_orders SET paid_modelare=v_paid,updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;
    ELSE
        UPDATE public.lab_work_orders SET paid_cer_fin=v_paid,updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;
    END IF;
    RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.set_stage_payment_status(uuid,bigint,text,text) FROM public;
GRANT EXECUTE ON FUNCTION public.set_stage_payment_status(uuid,bigint,text,text) TO authenticated;
-- END db/schema/20_functions/set_stage_payment_status.sql

