-- BEGIN db/schema/20_functions/sync_work_order_stage_assignment.sql
CREATE OR REPLACE FUNCTION public.sync_work_order_stage_assignment(
    p_lab uuid,
    p_work_order_id bigint,
    p_stage text,
    p_technician_name text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_stage text := lower(trim(coalesce(p_stage, '')));
    v_name text := nullif(trim(coalesce(p_technician_name, '')), '');
    v_order public.lab_work_orders%rowtype;
    v_current public.lab_work_order_stage_assignments%rowtype;
    v_assignment_id uuid;
    v_user_ids uuid[];
    v_user_id uuid;
    v_missing text;
    v_line_count integer;
    v_repair_incomplete boolean := false;
    v_lines_complete boolean := false;
    v_adjustments_complete boolean := true;
    v_saved_amount numeric;
    v_saved_unit_cost numeric;
    v_saved_quantity numeric;
    v_has_financial_activity boolean := false;
BEGIN
    IF public.effective_lab_role(p_lab) NOT IN ('admin', 'manager', 'technician') THEN
        RAISE EXCEPTION 'Stage assignment update denied';
    END IF;
    IF v_stage NOT IN ('model', 'modelare', 'cer_fin') THEN
        RAISE EXCEPTION 'Invalid stage';
    END IF;

    SELECT * INTO v_order
    FROM public.lab_work_orders
    WHERE lab_organization_id = p_lab AND id = p_work_order_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;

    SELECT * INTO v_current
    FROM public.lab_work_order_stage_assignments
    WHERE lab_organization_id = p_lab
      AND work_order_id = p_work_order_id
      AND stage_key = v_stage
      AND ended_at IS NULL
    FOR UPDATE;

    IF FOUND AND lower(trim(v_current.technician_name)) = lower(coalesce(v_name, '')) THEN
        WITH effective_saved AS (
            SELECT min(saved_scope.work_type) AS work_type,
                   saved_scope.work_type_key,
                   sum(saved_scope.quantity)::numeric AS quantity
            FROM (
                SELECT saved.work_type,
                       regexp_replace(lower(trim(saved.work_type)), '[[:space:]]+', ' ', 'g') AS work_type_key,
                       saved.quantity
                FROM public.lab_work_order_assignment_cost_lines saved
                WHERE saved.assignment_id=v_current.id
                UNION ALL
                SELECT delta.work_type,
                       regexp_replace(lower(trim(delta.work_type)), '[[:space:]]+', ' ', 'g') AS work_type_key,
                       delta.quantity_delta AS quantity
                FROM public.lab_work_order_assignment_adjustments delta
                WHERE delta.assignment_id=v_current.id
            ) saved_scope
            GROUP BY work_type_key
            HAVING sum(saved_scope.quantity)<>0
        )
        SELECT EXISTS (SELECT 1 FROM public.lab_work_order_assignment_cost_lines base
                       WHERE base.assignment_id=v_current.id)
               AND EXISTS (
                   SELECT 1 FROM public.resolve_work_order_technician_costs(
                       p_lab,p_work_order_id,v_stage,v_name
                   ) expected
               )
               AND NOT EXISTS (
                   SELECT 1
                   FROM public.resolve_work_order_technician_costs(
                       p_lab,p_work_order_id,v_stage,v_name
                   ) expected
                   LEFT JOIN effective_saved saved
                     ON saved.work_type_key=regexp_replace(lower(trim(expected.work_type)), '[[:space:]]+', ' ', 'g')
                   WHERE saved.work_type_key IS NULL
                      OR saved.quantity IS DISTINCT FROM expected.quantity
               )
               AND NOT EXISTS (
                   SELECT 1
                   FROM effective_saved saved
                   LEFT JOIN public.resolve_work_order_technician_costs(
                       p_lab,p_work_order_id,v_stage,v_name
                   ) expected
                     ON saved.work_type_key=regexp_replace(lower(trim(expected.work_type)), '[[:space:]]+', ' ', 'g')
                   WHERE expected.work_type IS NULL
               )
               AND NOT EXISTS (
                   SELECT 1 FROM public.lab_work_order_assignment_cost_lines saved
                   WHERE saved.assignment_id=v_current.id AND saved.amount IS NULL
               ),
               (SELECT sum(saved.amount) FROM public.lab_work_order_assignment_cost_lines saved
                WHERE saved.assignment_id=v_current.id),
               (SELECT CASE WHEN count(*)=1 THEN max(saved.unit_cost) END
                FROM public.lab_work_order_assignment_cost_lines saved
                WHERE saved.assignment_id=v_current.id),
               (SELECT sum(saved.quantity) FROM public.lab_work_order_assignment_cost_lines saved
                WHERE saved.assignment_id=v_current.id),
               NOT EXISTS (
                   SELECT 1 FROM public.lab_work_order_assignment_adjustments d
                   WHERE d.assignment_id=v_current.id AND d.amount IS NULL
               )
          INTO v_lines_complete,v_saved_amount,v_saved_unit_cost,v_saved_quantity,v_adjustments_complete;

        IF v_lines_complete AND v_current.agreed_amount IS DISTINCT FROM v_saved_amount THEN
            UPDATE public.lab_work_order_stage_assignments
            SET agreed_amount=v_saved_amount,unit_cost=v_saved_unit_cost,quantity=v_saved_quantity,
                cost_source=CASE WHEN cost_source='missing' THEN 'catalog' ELSE cost_source END
            WHERE id=v_current.id;
            INSERT INTO public.work_order_financial_audit (
                lab_organization_id,work_order_id,entity_type,entity_id,action,
                before_value,after_value,changed_by_user_id
            ) VALUES (
                p_lab,p_work_order_id,'stage_assignment',v_current.id::text,'repair_aggregate',
                to_jsonb(v_current),
                (SELECT to_jsonb(a) FROM public.lab_work_order_stage_assignments a WHERE a.id=v_current.id),
                auth.uid()
            );
            IF v_adjustments_complete THEN RETURN v_current.id; END IF;
        END IF;

        IF v_lines_complete AND v_adjustments_complete
           AND public.assignment_agreed_amount(v_current.id) IS NOT NULL THEN
            RETURN v_current.id;
        END IF;

        SELECT EXISTS (SELECT 1 FROM public.technician_payments p WHERE p.assignment_id=v_current.id)
            OR EXISTS (SELECT 1 FROM public.lab_work_order_assignment_adjustments d WHERE d.assignment_id=v_current.id)
          INTO v_has_financial_activity;
        IF v_has_financial_activity THEN
            RAISE EXCEPTION 'Incomplete technician cost snapshot cannot be repaired after financial activity for assignment %',v_current.id;
        END IF;

        -- repair_incomplete: legacy/current assignments without a usable per-type
        -- snapshot are rebuilt in place. Valid frozen snapshots never reach here.
        v_repair_incomplete := true;
        v_assignment_id := v_current.id;
    END IF;

    IF v_name IS NULL THEN
        IF v_current.id IS NOT NULL THEN
            UPDATE public.lab_work_order_stage_assignments SET ended_at = now()
            WHERE id = v_current.id;
            INSERT INTO public.work_order_financial_audit (
                lab_organization_id,work_order_id,entity_type,entity_id,action,
                before_value,after_value,changed_by_user_id
            ) VALUES (
                p_lab,p_work_order_id,'stage_assignment',v_current.id::text,'unassign',
                to_jsonb(v_current),
                (SELECT to_jsonb(a) FROM public.lab_work_order_stage_assignments a WHERE a.id=v_current.id),
                auth.uid()
            );
        END IF;
        RETURN NULL;
    END IF;

    SELECT array_agg(p.id ORDER BY p.id)
      INTO v_user_ids
    FROM public.profiles p
    JOIN public.organization_memberships m
      ON m.user_id = p.id AND m.organization_id = p_lab
    WHERE p.active = true AND m.status = 'active'
      AND lower(m.role) = 'technician'
      AND lower(trim(coalesce(p.technician_name, p.display_name, ''))) = lower(v_name);

    IF coalesce(array_length(v_user_ids, 1), 0) > 1 THEN
        RAISE EXCEPTION 'Technician name is ambiguous';
    END IF;
    v_user_id := v_user_ids[1];

    IF v_current.id IS NOT NULL AND NOT v_repair_incomplete THEN
        UPDATE public.lab_work_order_stage_assignments SET ended_at = now()
        WHERE id = v_current.id;
    END IF;

    IF v_repair_incomplete THEN
        DELETE FROM public.lab_work_order_assignment_cost_lines
        WHERE assignment_id=v_assignment_id;
        UPDATE public.lab_work_order_stage_assignments
        SET technician_user_id=coalesce(technician_user_id,v_user_id)
        WHERE id=v_assignment_id;
    ELSE
        INSERT INTO public.lab_work_order_stage_assignments (
            lab_organization_id, work_order_id, stage_key, technician_user_id,
            technician_name, quantity, cost_source, created_by_user_id
        ) VALUES (
            p_lab, p_work_order_id, v_stage, v_user_id, v_name,
            (SELECT sum(quantity) FROM public.lab_work_order_items WHERE lab_organization_id=p_lab AND work_order_id=p_work_order_id), 'catalog', auth.uid()
        ) RETURNING id INTO v_assignment_id;
    END IF;

    INSERT INTO public.lab_work_order_assignment_cost_lines (
        assignment_id, work_type, quantity, unit_cost, amount, cost_source
    )
    SELECT v_assignment_id,costs.work_type,costs.quantity,costs.unit_cost,costs.amount,costs.cost_source
    FROM public.resolve_work_order_technician_costs(
        p_lab,p_work_order_id,v_stage,v_name
    ) costs;

    SELECT count(*)::integer,
           string_agg(work_type,', ' ORDER BY work_type) FILTER (WHERE amount IS NULL)
      INTO v_line_count,v_missing
    FROM public.lab_work_order_assignment_cost_lines
    WHERE assignment_id=v_assignment_id;
    IF v_line_count=0 THEN
        RAISE EXCEPTION 'Cannot calculate technician cost without configured teeth';
    END IF;
    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'Missing technician cost configuration: % / % / %',v_name,v_missing,v_stage;
    END IF;

    UPDATE public.lab_work_order_stage_assignments a
    SET unit_cost = totals.unit_cost,
        quantity = totals.quantity,
        agreed_amount = totals.agreed_amount,
        cost_source = CASE WHEN totals.missing_count > 0 THEN 'missing' ELSE 'catalog' END
    FROM (
        SELECT CASE WHEN count(*) = 1 THEN max(unit_cost) ELSE NULL END AS unit_cost,
               sum(quantity) AS quantity,
               CASE WHEN count(*) FILTER (WHERE amount IS NULL) > 0 THEN NULL ELSE sum(amount) END AS agreed_amount,
               count(*) FILTER (WHERE amount IS NULL) AS missing_count
        FROM public.lab_work_order_assignment_cost_lines
        WHERE assignment_id = v_assignment_id
    ) totals
    WHERE a.id = v_assignment_id;

    INSERT INTO public.work_order_financial_audit (
        lab_organization_id, work_order_id, entity_type, entity_id, action,
        before_value, after_value, changed_by_user_id
    ) VALUES (
        p_lab, p_work_order_id, 'stage_assignment', v_assignment_id::text,
        CASE WHEN v_repair_incomplete THEN 'repair_incomplete'
             WHEN v_current.id IS NULL THEN 'assign' ELSE 'reassign' END,
        CASE WHEN v_current.id IS NULL THEN '{}'::jsonb ELSE to_jsonb(v_current) END,
        (SELECT to_jsonb(a) FROM public.lab_work_order_stage_assignments a WHERE a.id=v_assignment_id),
        auth.uid()
    );

    RETURN v_assignment_id;
END;
$$;

REVOKE ALL ON FUNCTION public.sync_work_order_stage_assignment(uuid,bigint,text,text) FROM public;
REVOKE ALL ON FUNCTION public.sync_work_order_stage_assignment(uuid,bigint,text,text) FROM authenticated;
-- END db/schema/20_functions/sync_work_order_stage_assignment.sql

-- BEGIN db/schema/20_functions/update_doctor_work_order.sql
CREATE OR REPLACE FUNCTION public.update_doctor_work_order(p_lab_organization_id uuid, p_work_order_id bigint, p_deadline date, p_nume_pacient text, p_items jsonb, p_case jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_order public.lab_work_orders%rowtype;
begin
    if not public.is_connected_doctor_for_lab(p_lab_organization_id) then
        raise exception 'Doctor access denied';
    end if;

    select *
      into v_order
    from public.lab_work_orders
    where lab_organization_id = p_lab_organization_id
      and id = p_work_order_id
    for update;

    if not found or not public.doctor_matches_partner(v_order.nume_partener) then
        raise exception 'Work Order access denied';
    end if;

    if v_order.locked then
        raise exception 'Work Order is locked';
    end if;

    if lower(trim(coalesce(v_order.status,''))) <> 'not started' then
        raise exception 'Doctor can edit only Not Started Work Orders';
    end if;

    if trim(coalesce(p_nume_pacient,'')) = '' then
        raise exception 'Nume_Pacient is required';
    end if;

    update public.lab_work_orders
    set
        deadline = p_deadline,
        nume_pacient = trim(p_nume_pacient),
        updated_by_user_id = public.current_legacy_user_id(),
        updated_at = now()
    where lab_organization_id = p_lab_organization_id
      and id = p_work_order_id;

    perform public.replace_work_order_items(p_lab_organization_id,p_work_order_id,p_items,'General');
    perform public.save_work_order_clinical_case(p_lab_organization_id,p_work_order_id,p_case);
    return true;
end;
$function$
;
-- END db/schema/20_functions/update_doctor_work_order.sql

-- BEGIN db/schema/20_functions/update_management_work_order.sql
-- The obsolete scalar editor is removed by the per-tooth cutover.
-- Call update_management_work_order_v188 with p_items instead.
-- END db/schema/20_functions/update_management_work_order.sql

-- BEGIN db/schema/20_functions/update_management_work_order_stage_field.sql
-- Focused RPC for the management table's quick stage controls. Keeping this
-- path server-side also creates/ends immutable technician-cost assignments.
CREATE OR REPLACE FUNCTION public.update_management_work_order_stage_field(
    p_lab_organization_id uuid,
    p_work_order_id bigint,
    p_field text,
    p_value text,
    p_settlement text DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_order public.lab_work_orders%rowtype;
    v_field text := lower(trim(coalesce(p_field,'')));
    v_value text := nullif(trim(coalesce(p_value,'')),'');
    v_old_technician text;
    v_saved_technician text;
    v_changed boolean;
BEGIN
    IF NOT public.is_lab_management(p_lab_organization_id) THEN
        RAISE EXCEPTION 'Management access denied';
    END IF;

    SELECT * INTO v_order
    FROM public.lab_work_orders
    WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;

    IF v_field='status_model' THEN
        UPDATE public.lab_work_orders SET status_model=coalesce(v_value,'Not Started'),
            updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;
    ELSIF v_field='status_modelare' THEN
        UPDATE public.lab_work_orders SET status_modelare=coalesce(v_value,'Not Started'),
            updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;
    ELSIF v_field='status_cer_fin' THEN
        UPDATE public.lab_work_orders SET status_cer_fin=coalesce(v_value,'Not Started'),
            updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;
    ELSIF v_field='tehnician_model' THEN
        v_old_technician:=v_order.tehnician_model;
        v_changed:=lower(trim(coalesce(v_old_technician,'')))
            IS DISTINCT FROM lower(trim(coalesce(v_value,'')));
        IF v_changed THEN
            PERFORM public.prepare_stage_reassignment(
                p_lab_organization_id,p_work_order_id,'model',v_value,p_settlement);
        END IF;
        UPDATE public.lab_work_orders SET tehnician_model=v_value,
            paid_model=CASE WHEN v_changed THEN 'Not Paid' ELSE paid_model END,
            status_model=CASE WHEN v_changed THEN 'Not Started' ELSE status_model END,
            status=CASE WHEN v_changed AND status NOT IN ('Not Started','Started') THEN 'Started' ELSE status END,
            updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id
        RETURNING tehnician_model INTO v_saved_technician;
        PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,'model',v_saved_technician);
    ELSIF v_field='tehnician1_modelare' THEN
        v_old_technician:=v_order.tehnician1_modelare;
        v_changed:=lower(trim(coalesce(v_old_technician,'')))
            IS DISTINCT FROM lower(trim(coalesce(v_value,'')));
        IF v_changed THEN
            PERFORM public.prepare_stage_reassignment(
                p_lab_organization_id,p_work_order_id,'modelare',v_value,p_settlement);
        END IF;
        UPDATE public.lab_work_orders SET tehnician1_modelare=v_value,
            paid_modelare=CASE WHEN v_changed THEN 'Not Paid' ELSE paid_modelare END,
            status_modelare=CASE WHEN v_changed THEN 'Not Started' ELSE status_modelare END,
            status=CASE WHEN v_changed AND status NOT IN ('Not Started','Started') THEN 'Started' ELSE status END,
            updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id
        RETURNING tehnician1_modelare INTO v_saved_technician;
        PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,'modelare',v_saved_technician);
    ELSIF v_field='tehnician2_cer_fin' THEN
        v_old_technician:=v_order.tehnician2_cer_fin;
        v_changed:=lower(trim(coalesce(v_old_technician,'')))
            IS DISTINCT FROM lower(trim(coalesce(v_value,'')));
        IF v_changed THEN
            PERFORM public.prepare_stage_reassignment(
                p_lab_organization_id,p_work_order_id,'cer_fin',v_value,p_settlement);
        END IF;
        UPDATE public.lab_work_orders SET tehnician2_cer_fin=v_value,
            paid_cer_fin=CASE WHEN v_changed THEN 'Not Paid' ELSE paid_cer_fin END,
            status_cer_fin=CASE WHEN v_changed THEN 'Not Started' ELSE status_cer_fin END,
            status=CASE WHEN v_changed AND status NOT IN ('Not Started','Started') THEN 'Started' ELSE status END,
            updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id
        RETURNING tehnician2_cer_fin INTO v_saved_technician;
        PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,'cer_fin',v_saved_technician);
    ELSE
        RAISE EXCEPTION 'Unsupported management stage field';
    END IF;

    RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.update_management_work_order_stage_field(uuid,bigint,text,text,text) FROM public;
GRANT EXECUTE ON FUNCTION public.update_management_work_order_stage_field(uuid,bigint,text,text,text) TO authenticated;
-- END db/schema/20_functions/update_management_work_order_stage_field.sql

-- BEGIN db/schema/20_functions/update_management_work_order_v188.sql
CREATE OR REPLACE FUNCTION public.update_management_work_order_v188(
    p_lab_organization_id uuid,
    p_work_order_id bigint,
    p_deadline date,
    p_status text,
    p_nume_pacient text,
    p_nume_partener text,
    p_contract text,
    p_discount numeric,
    p_data_receptie timestamptz,
    p_tehnician_model text,
    p_tehnician1_modelare text,
    p_tehnician2_cer_fin text,
    p_status_model text,
    p_status_modelare text,
    p_status_cer_fin text,
    p_paid_model text,
    p_paid_modelare text,
    p_paid_cer_fin text,
    p_model_not_applicable boolean,
    p_modelare_not_applicable boolean,
    p_cer_fin_not_applicable boolean,
    p_locked boolean,
    p_model_settlement text DEFAULT NULL,
    p_modelare_settlement text DEFAULT NULL,
    p_cer_fin_settlement text DEFAULT NULL,
    p_items jsonb DEFAULT NULL,
    p_requested_contract text DEFAULT 'General',
    p_case jsonb DEFAULT '{}'::jsonb
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_old public.lab_work_orders%rowtype;
    v_saved public.lab_work_orders%rowtype;
    v_before jsonb;
    v_after jsonb;
    v_model text;
    v_modelare text;
    v_cer_fin text;
    v_status_model text;
    v_status_modelare text;
    v_status_cer_fin text;
    v_paid_model text;
    v_paid_modelare text;
    v_paid_cer_fin text;
    v_model_changed boolean;
    v_modelare_changed boolean;
    v_cer_fin_changed boolean;
    v_work_status text;
BEGIN
    IF NOT public.is_lab_management(p_lab_organization_id) THEN
        RAISE EXCEPTION 'Management access denied';
    END IF;

    SELECT * INTO v_old
    FROM public.lab_work_orders
    WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;

    IF trim(coalesce(p_nume_pacient,''))='' THEN RAISE EXCEPTION 'Nume_Pacient is required'; END IF;
    IF trim(coalesce(p_nume_partener,''))='' THEN RAISE EXCEPTION 'Nume_Partener is required'; END IF;
    IF coalesce(p_discount,0)<0 OR coalesce(p_discount,0)>100 THEN
        RAISE EXCEPTION 'Discount must be between 0 and 100';
    END IF;

    v_model := CASE WHEN coalesce(p_model_not_applicable,false) THEN NULL
        ELSE nullif(trim(coalesce(p_tehnician_model,'')),'') END;
    v_modelare := CASE WHEN coalesce(p_modelare_not_applicable,false) THEN NULL
        ELSE nullif(trim(coalesce(p_tehnician1_modelare,'')),'') END;
    v_cer_fin := CASE WHEN coalesce(p_cer_fin_not_applicable,false) THEN NULL
        ELSE nullif(trim(coalesce(p_tehnician2_cer_fin,'')),'') END;
    v_status_model := CASE WHEN coalesce(p_model_not_applicable,false) THEN 'Not Started'
        ELSE coalesce(nullif(trim(p_status_model),''),'Not Started') END;
    v_status_modelare := CASE WHEN coalesce(p_modelare_not_applicable,false) THEN 'Not Started'
        ELSE coalesce(nullif(trim(p_status_modelare),''),'Not Started') END;
    v_status_cer_fin := CASE WHEN coalesce(p_cer_fin_not_applicable,false) THEN 'Not Started'
        ELSE coalesce(nullif(trim(p_status_cer_fin),''),'Not Started') END;
    v_paid_model := CASE WHEN v_model IS NULL THEN 'Not Paid'
        ELSE nullif(trim(p_paid_model),'') END;
    v_paid_modelare := CASE WHEN v_modelare IS NULL THEN 'Not Paid'
        ELSE nullif(trim(p_paid_modelare),'') END;
    v_paid_cer_fin := CASE WHEN v_cer_fin IS NULL THEN 'Not Paid'
        ELSE nullif(trim(p_paid_cer_fin),'') END;

    v_model_changed := lower(trim(coalesce(v_old.tehnician_model,'')))
        IS DISTINCT FROM lower(trim(coalesce(v_model,'')));
    v_modelare_changed := lower(trim(coalesce(v_old.tehnician1_modelare,'')))
        IS DISTINCT FROM lower(trim(coalesce(v_modelare,'')));
    v_cer_fin_changed := lower(trim(coalesce(v_old.tehnician2_cer_fin,'')))
        IS DISTINCT FROM lower(trim(coalesce(v_cer_fin,'')));
    -- Reassignment closes the former assignment without undoing its payment.
    -- The new assignment always starts unpaid, even if the form carried the
    -- previous assignment's stale Paid value.
    IF v_model_changed THEN v_paid_model:='Not Paid'; END IF;
    IF v_modelare_changed THEN v_paid_modelare:='Not Paid'; END IF;
    IF v_cer_fin_changed THEN v_paid_cer_fin:='Not Paid'; END IF;
    IF v_model_changed THEN v_status_model:='Not Started'; END IF;
    IF v_modelare_changed THEN v_status_modelare:='Not Started'; END IF;
    IF v_cer_fin_changed THEN v_status_cer_fin:='Not Started'; END IF;
    v_work_status:=coalesce(nullif(trim(p_status),''),'Not Started');
    IF (v_model_changed OR v_modelare_changed OR v_cer_fin_changed)
       AND v_work_status NOT IN ('Not Started','Started') THEN
        v_work_status:='Started';
    END IF;

    IF v_model_changed THEN
        PERFORM public.prepare_stage_reassignment(
            p_lab_organization_id,p_work_order_id,'model',v_model,p_model_settlement);
    END IF;
    IF v_modelare_changed THEN
        PERFORM public.prepare_stage_reassignment(
            p_lab_organization_id,p_work_order_id,'modelare',v_modelare,p_modelare_settlement);
    END IF;
    IF v_cer_fin_changed THEN
        PERFORM public.prepare_stage_reassignment(
            p_lab_organization_id,p_work_order_id,'cer_fin',v_cer_fin,p_cer_fin_settlement);
    END IF;

    -- Close changed technicians before the scope replacement; their frozen balance belongs
    -- to the prior scope, and the new assignment is priced only after new items exist.
    WITH closed AS (
        UPDATE public.lab_work_order_stage_assignments SET ended_at=now()
        WHERE lab_organization_id=p_lab_organization_id AND work_order_id=p_work_order_id AND ended_at IS NULL
          AND ((stage_key='model' AND v_model_changed) OR (stage_key='modelare' AND v_modelare_changed)
               OR (stage_key='cer_fin' AND v_cer_fin_changed)) RETURNING *
    ) INSERT INTO public.work_order_financial_audit(lab_organization_id,work_order_id,entity_type,entity_id,action,before_value,after_value,changed_by_user_id)
      SELECT p_lab_organization_id,p_work_order_id,'stage_assignment',id::text,'close_for_reassignment',
          to_jsonb(closed)||jsonb_build_object('ended_at',null),to_jsonb(closed),auth.uid() FROM closed;

    v_before := jsonb_build_object(
        'list_price',v_old.snapshot_list_price,'final_price',v_old.snapshot_final_price,
        'discount',v_old.discount
    );

    UPDATE public.lab_work_orders wo
    SET deadline=p_deadline,
        status=v_work_status,
        nume_pacient=trim(p_nume_pacient),
        nume_partener=trim(p_nume_partener),
        contract=coalesce(nullif(trim(p_contract),''),'General'),
        discount=coalesce(p_discount,0),
        data_receptie=p_data_receptie,
        tehnician_model=v_model,
        tehnician1_modelare=v_modelare,
        tehnician2_cer_fin=v_cer_fin,
        status_model=v_status_model,
        status_modelare=v_status_modelare,
        status_cer_fin=v_status_cer_fin,
        paid_model=CASE WHEN v_model_changed THEN 'Not Paid' ELSE paid_model END,
        paid_modelare=CASE WHEN v_modelare_changed THEN 'Not Paid' ELSE paid_modelare END,
        paid_cer_fin=CASE WHEN v_cer_fin_changed THEN 'Not Paid' ELSE paid_cer_fin END,
        model_not_applicable=coalesce(p_model_not_applicable,false),
        modelare_not_applicable=coalesce(p_modelare_not_applicable,false),
        cer_fin_not_applicable=coalesce(p_cer_fin_not_applicable,false),
        locked=coalesce(p_locked,false),
        updated_by_user_id=public.current_legacy_user_id(),
        updated_at=now()
    WHERE wo.lab_organization_id=p_lab_organization_id AND wo.id=p_work_order_id
    RETURNING wo.* INTO v_saved;

    -- Price lines must be fixed before technician costs. This prevents a
    -- multi-type case from assigning every tooth the primary work-type cost.
    IF p_items IS NULL THEN RAISE EXCEPTION 'At least one configured tooth is required'; END IF;
    PERFORM public.replace_work_order_items(
        p_lab_organization_id,p_work_order_id,p_items,p_requested_contract);
    SELECT * INTO v_saved FROM public.lab_work_orders
    WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id;

    v_after := jsonb_build_object(
        'list_price',v_saved.snapshot_list_price,'final_price',v_saved.snapshot_final_price,
        'discount',v_saved.discount
    );
    IF v_before IS DISTINCT FROM v_after THEN
        INSERT INTO public.work_order_financial_audit(
            lab_organization_id,work_order_id,entity_type,entity_id,action,
            before_value,after_value,changed_by_user_id
        ) VALUES (
            p_lab_organization_id,p_work_order_id,'work_order_price',p_work_order_id::text,
            'quantity_or_discount',v_before,v_after,auth.uid()
        );
    END IF;

    UPDATE public.lab_patient_cases
    SET nume_pacient=trim(p_nume_pacient),nume_partener=trim(p_nume_partener),
        deadline=p_deadline,
        updated_by_user_id=public.current_legacy_user_id(),updated_at=now()
    WHERE lab_organization_id=p_lab_organization_id AND work_order_id=p_work_order_id;

    PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,'model',v_saved.tehnician_model);
    PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,'modelare',v_saved.tehnician1_modelare);
    PERFORM public.sync_work_order_stage_assignment(p_lab_organization_id,p_work_order_id,'cer_fin',v_saved.tehnician2_cer_fin);

    IF v_saved.tehnician_model IS NOT NULL
       AND v_paid_model IS NOT NULL
       AND v_paid_model IS DISTINCT FROM public.work_order_stage_payment_status(p_lab_organization_id,p_work_order_id,'model') THEN
        PERFORM public.set_stage_payment_status(p_lab_organization_id,p_work_order_id,'model',v_paid_model);
    END IF;
    IF v_saved.tehnician1_modelare IS NOT NULL
       AND v_paid_modelare IS NOT NULL
       AND v_paid_modelare IS DISTINCT FROM public.work_order_stage_payment_status(p_lab_organization_id,p_work_order_id,'modelare') THEN
        PERFORM public.set_stage_payment_status(p_lab_organization_id,p_work_order_id,'modelare',v_paid_modelare);
    END IF;
    IF v_saved.tehnician2_cer_fin IS NOT NULL
       AND v_paid_cer_fin IS NOT NULL
       AND v_paid_cer_fin IS DISTINCT FROM public.work_order_stage_payment_status(p_lab_organization_id,p_work_order_id,'cer_fin') THEN
        PERFORM public.set_stage_payment_status(p_lab_organization_id,p_work_order_id,'cer_fin',v_paid_cer_fin);
    END IF;

    PERFORM public.save_work_order_clinical_case(p_lab_organization_id,p_work_order_id,p_case);
    RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.update_management_work_order_v188(
    uuid,bigint,date,text,text,text,text,numeric,timestamptz,
    text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,
    text,text,text,jsonb,text,jsonb
) FROM public;
GRANT EXECUTE ON FUNCTION public.update_management_work_order_v188(
    uuid,bigint,date,text,text,text,text,numeric,timestamptz,
    text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,
    text,text,text,jsonb,text,jsonb
) TO authenticated;
-- END db/schema/20_functions/update_management_work_order_v188.sql

-- BEGIN db/schema/20_functions/update_material_quantity.sql
-- Flowrise Supabase function: public.update_material_quantity(p_lab_organization_id uuid, p_material_id bigint, p_quantity numeric)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.update_material_quantity(p_lab_organization_id uuid, p_material_id bigint, p_quantity numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_quantity numeric(14,3);
    v_result jsonb;
begin
    if not (
        public.is_lab_management(p_lab_organization_id)
        or public.is_lab_technician(p_lab_organization_id)
    ) then
        raise exception 'Material quantity update denied';
    end if;

    if p_quantity is null or p_quantity < 0 then
        raise exception 'Quantity must be zero or greater';
    end if;

    v_result:=public.adjust_material_quantity(p_lab_organization_id,p_material_id,'set',p_quantity,null,null);
    v_quantity:=(v_result->>'new_quantity')::numeric;
    return v_quantity;
end;
$function$
;

-- Security definer: True
-- Return type: numeric
-- Identity arguments: p_lab_organization_id uuid, p_material_id bigint, p_quantity numeric
-- END db/schema/20_functions/update_material_quantity.sql

-- BEGIN db/schema/20_functions/update_my_stage_status.sql
-- Flowrise Supabase function: public.update_my_stage_status(p_lab_organization_id uuid, p_work_order_id bigint, p_stage text, p_status text)
-- Generated from the Supabase schema snapshot dated 2026-09-04.
-- The complete CREATE OR REPLACE FUNCTION definition follows.

CREATE OR REPLACE FUNCTION public.update_my_stage_status(p_lab_organization_id uuid, p_work_order_id bigint, p_stage text, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tech text;
    v_stage text := lower(trim(coalesce(p_stage,'')));
    v_status text := trim(coalesce(p_status,''));
    v_order public.lab_work_orders%rowtype;
begin
    if not public.is_lab_technician(p_lab_organization_id) then
        raise exception 'Technician access denied';
    end if;

    if v_stage not in ('model','modelare','cer_fin') then
        raise exception 'Invalid stage';
    end if;

    if lower(v_status) not in ('not started','started','finished') then
        raise exception 'Invalid stage status';
    end if;

    v_tech := lower(trim(coalesce(public.current_technician_name(),'')));
    if v_tech = '' then
        raise exception 'Technician profile mapping is missing';
    end if;

    select *
      into v_order
    from public.lab_work_orders
    where lab_organization_id = p_lab_organization_id
      and id = p_work_order_id
    limit 1;

    if not found then
        raise exception 'Work Order not found';
    end if;

    if v_stage = 'model' then
        if lower(trim(coalesce(v_order.tehnician_model,''))) <> v_tech then
            raise exception 'Technician is not assigned to Model';
        end if;

        update public.lab_work_orders
        set status_model = v_status,
            updated_by_user_id = public.current_legacy_user_id(),
            updated_at = now()
        where lab_organization_id = p_lab_organization_id
          and id = p_work_order_id;

    elsif v_stage = 'modelare' then
        if lower(trim(coalesce(v_order.tehnician1_modelare,''))) <> v_tech then
            raise exception 'Technician is not assigned to Modelare';
        end if;

        update public.lab_work_orders
        set status_modelare = v_status,
            updated_by_user_id = public.current_legacy_user_id(),
            updated_at = now()
        where lab_organization_id = p_lab_organization_id
          and id = p_work_order_id;

    else
        if lower(trim(coalesce(v_order.tehnician2_cer_fin,''))) <> v_tech then
            raise exception 'Technician is not assigned to Ceramica/Finisare';
        end if;

        update public.lab_work_orders
        set status_cer_fin = v_status,
            updated_by_user_id = public.current_legacy_user_id(),
            updated_at = now()
        where lab_organization_id = p_lab_organization_id
          and id = p_work_order_id;
    end if;

    return true;
end;
$function$
;

-- Security definer: True
-- Return type: boolean
-- Identity arguments: p_lab_organization_id uuid, p_work_order_id bigint, p_stage text, p_status text
-- END db/schema/20_functions/update_my_stage_status.sql

-- BEGIN db/schema/20_functions/upsert_patient_case.sql
CREATE OR REPLACE FUNCTION public.upsert_patient_case(
    p_lab_organization_id uuid,p_work_order_id bigint,p_items jsonb,p_case jsonb DEFAULT '{}'::jsonb)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_order public.lab_work_orders%rowtype;
BEGIN
    IF NOT (public.is_lab_management(p_lab_organization_id) OR public.is_connected_doctor_for_lab(p_lab_organization_id)) THEN
        RAISE EXCEPTION 'Patient case write denied';
    END IF;
    SELECT * INTO v_order FROM public.lab_work_orders WHERE lab_organization_id=p_lab_organization_id AND id=p_work_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Work Order not found'; END IF;
    IF NOT public.is_lab_management(p_lab_organization_id) THEN
        IF NOT public.doctor_matches_partner(v_order.nume_partener) THEN RAISE EXCEPTION 'Work Order access denied'; END IF;
        IF v_order.locked OR lower(coalesce(v_order.status,''))<>'not started' THEN RAISE EXCEPTION 'Doctor can edit only unlocked Not Started Work Orders'; END IF;
    END IF;
    PERFORM public.replace_work_order_items(p_lab_organization_id,p_work_order_id,p_items,v_order.contract);
    RETURN public.save_work_order_clinical_case(p_lab_organization_id,p_work_order_id,p_case);
END; $$;
-- END db/schema/20_functions/upsert_patient_case.sql

-- BEGIN db/schema/20_functions/work_order_item_scope.sql
-- Internal read model; callers decide whether sale-price snapshots may be exposed.
CREATE OR REPLACE FUNCTION public.work_order_item_scope(p_lab uuid,p_order bigint,p_include_prices boolean DEFAULT false)
RETURNS TABLE(items jsonb,work_types text[],work_type_summary text,element_count numeric)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
    SELECT coalesce((SELECT jsonb_agg(
        jsonb_build_object('tooth_number',i.tooth_number,'work_type',i.work_type,'quantity',i.quantity)
        || CASE WHEN p_include_prices THEN jsonb_build_object('contract',i.contract,'unit_price',i.unit_price,
            'line_total',i.line_total,'price_source',i.price_source,'price_fixed_at',i.price_fixed_at,'price_migrated',i.price_migrated)
            ELSE '{}'::jsonb END ORDER BY i.tooth_number)
        FROM public.lab_work_order_items i WHERE i.lab_organization_id=p_lab AND i.work_order_id=p_order),'[]'::jsonb),
        coalesce((SELECT array_agg(t.work_type ORDER BY t.first_tooth,t.work_type) FROM
            (SELECT work_type,min(tooth_number) first_tooth FROM public.lab_work_order_items
             WHERE lab_organization_id=p_lab AND work_order_id=p_order GROUP BY work_type) t),ARRAY[]::text[]),
        (SELECT string_agg(t.work_type,' / ' ORDER BY t.first_tooth,t.work_type) FROM
            (SELECT work_type,min(tooth_number) first_tooth FROM public.lab_work_order_items
             WHERE lab_organization_id=p_lab AND work_order_id=p_order GROUP BY work_type) t),
        coalesce((SELECT sum(quantity) FROM public.lab_work_order_items WHERE lab_organization_id=p_lab AND work_order_id=p_order),0)
$$;
REVOKE ALL ON FUNCTION public.work_order_item_scope(uuid,bigint,boolean) FROM public,authenticated;
-- END db/schema/20_functions/work_order_item_scope.sql


